window.songs=[{"order":1,"id":"01-cette-histoire","title":"Cette histoire","titleZh":"这段往事","lines":[{"id":"la-dame-aux-camelias-01-001","lineIndex":1,"sourceLineIndex":1,"speaker":"","original":"Née dans la boue, ange pur et sacré.","ipa":"/nˈe dˈɑ̃ lˈa- bˈu ˈɑ̃ʒ pˈyʁ ˈe sakʁˈe/","zh":"生于泥淖，一个纯洁而神圣的天使。","en":"Born in the mud, a pure and sacred angel.","note":"推定修订"},{"id":"la-dame-aux-camelias-01-002","lineIndex":2,"sourceLineIndex":2,"speaker":"","original":"Elle s’est battue pour s’élever du fossé.","ipa":"/ˈɛl sˈɛ batˈy pˈuʁ selvˈe dˈy- fɔsˈe/","zh":"她奋力挣扎，要从沟壑中站起。","en":"She fought to rise from the ditch.","note":"推定修订"},{"id":"la-dame-aux-camelias-01-003","lineIndex":3,"sourceLineIndex":3,"speaker":"","original":"Elle a bravé les flammes, oublié ses blessures.","ipa":"/ˈɛl ˈa bʁavˈe lˈe- flˈam ubliˈe sˈe- blɛsˈyʁ/","zh":"她无畏烈焰，忘却伤痛。","en":"She braved the flames and forgot her wounds.","note":"推定修订"},{"id":"la-dame-aux-camelias-01-004","lineIndex":4,"sourceLineIndex":4,"speaker":"","original":"Elle a soigné son amant malgré ses déchirures.","ipa":"/ˈɛl ˈa swanjˈe sˈɔ̃ amˈɑ̃ malɡʁˈe sˈe- deʃiʁˈyʁ/","zh":"尽管自己伤痕累累，她仍照料着爱人。","en":"She cared for her lover despite her wounds.","note":"推定修订"},{"id":"la-dame-aux-camelias-01-005","lineIndex":5,"sourceLineIndex":5,"speaker":"","original":"Prenant sa revanche, idole adulée.","ipa":"/pʁənˈɑ̃ sˈa- ʁəvˈɑ̃ʃ idˈɔl adylˈe/","zh":"她复仇归来，成为众人崇拜的偶像。","en":"Taking her revenge, a beloved idol.","note":"推定修订"},{"id":"la-dame-aux-camelias-01-006","lineIndex":6,"sourceLineIndex":6,"speaker":"","original":"Plus célèbre que les reines qu’on a vu couronner.","ipa":"/plˈy selˈɛbʁ kˈə lˈe- ʁˈɛn kˈɔ̃ ˈa vˈy kuʁɔnˈe/","zh":"她比那些受加冕的王后更有名。","en":"More famous than the queens crowned.","note":"推定修订"},{"id":"la-dame-aux-camelias-01-007","lineIndex":7,"sourceLineIndex":7,"speaker":"","original":"À Paris, cité des amours éphémères.","ipa":"/ˈa paʁˈi sitˈe dˈe- amˈuʁ efemˈɛʁ/","zh":"在巴黎，这座短暂爱情之城。","en":"In Paris, city of fleeting loves.","note":"推定修订"},{"id":"la-dame-aux-camelias-01-008","lineIndex":8,"sourceLineIndex":8,"speaker":"","original":"Où les passions naissent et meurent en un soir.","ipa":"/ˈu lˈe- pasjˈɔ̃ nˈɛs ˈe mˈœʁ ˈɑ̃ ˈœ̃ swˈaʁ/","zh":"激情在这里一夜之间诞生，又一夜之间消亡。","en":"Where passions are born and die in a single night.","note":"推定修订"},{"id":"la-dame-aux-camelias-01-009","lineIndex":9,"sourceLineIndex":9,"speaker":"","original":"Camélias fanés, cœur brisé en miettes.","ipa":"/kameljˈa fanˈe kˈœʁ bʁizˈe ˈɑ̃ mjˈɛt/","zh":"茶花凋零，心碎成片。","en":"Withered camellias, a heart broken to pieces.","note":"推定修订"},{"id":"la-dame-aux-camelias-01-010","lineIndex":10,"sourceLineIndex":10,"speaker":"","original":"L’amour est un jeu, mais la mort est la reine.","ipa":"/lamˈuʁ ˈɛ ˈœ̃ ʒˈø mˈɛ lˈa- mˈɔʁ ˈɛ lˈa- ʁˈɛn/","zh":"爱情是一场游戏，但死亡才是女王。","en":"Love is a game, but death is the queen.","note":"推定修订"},{"id":"la-dame-aux-camelias-01-011","lineIndex":11,"sourceLineIndex":11,"speaker":"","original":"Je suis l’ami dans l’ombre de son succès.","ipa":"/ʒˈə- syˈi lamˈi dˈɑ̃ lˈɔ̃bʁ dˈə- sˈɔ̃ syksˈɛ/","zh":"我是她成功背后的朋友。","en":"I am the friend in the shadow of her success.","note":"推定修订"},{"id":"la-dame-aux-camelias-01-012","lineIndex":12,"sourceLineIndex":12,"speaker":"","original":"Elle est ma mine d’or où je puis à l’excès.","ipa":"/ˈɛl ˈɛ mˈa- mˈin dˈɔʁ ˈu ʒˈə- pyˈi ˈa lɛksˈɛ/","zh":"她是我的金矿，让我得以无度索取。","en":"She is my gold mine, where I can indulge to excess.","note":"推定修订"},{"id":"la-dame-aux-camelias-01-013","lineIndex":13,"sourceLineIndex":13,"speaker":"","original":"Mais mon envie a dévoré ma raison.","ipa":"/mˈɛ mˈɔ̃ ɑ̃vˈi ˈa devoʁˈe mˈa- ʁɛzˈɔ̃/","zh":"但我的嫉妒吞噬了理智。","en":"But my envy devoured my reason.","note":"推定修订"},{"id":"la-dame-aux-camelias-01-014","lineIndex":14,"sourceLineIndex":14,"speaker":"","original":"Je l’ai tant jalousée, et ce en toute saison.","ipa":"/ʒˈə- lˈe tˈɑ̃ ʒaluzˈe ˈe sˈə- ˈɑ̃ tˈut sɛzˈɔ̃/","zh":"我如此嫉妒她，一年四季皆是如此。","en":"I envied her so much, in every season.","note":"推定修订"},{"id":"la-dame-aux-camelias-01-015","lineIndex":15,"sourceLineIndex":15,"speaker":"","original":"Son élégance rare était mon danger.","ipa":"/sˈɔ̃ eleɡˈɑ̃s ʁˈaʁ etˈɛ mˈɔ̃ dɑ̃ʒˈe/","zh":"她罕见的优雅成了我的威胁。","en":"Her rare elegance was my danger.","note":"推定修订"},{"id":"la-dame-aux-camelias-01-016","lineIndex":16,"sourceLineIndex":16,"speaker":"","original":"Car sous mon sourire, je voulais la juger.","ipa":"/kˈaʁ sˈu mˈɔ̃ suʁˈiʁ ʒˈə- vulˈɛ lˈa- ʒyʒˈe/","zh":"因为在微笑之下，我想要评判她。","en":"For beneath my smile, I wanted to judge her.","note":"推定修订"},{"id":"la-dame-aux-camelias-01-017","lineIndex":17,"sourceLineIndex":17,"speaker":"","original":"Elle fut grandeur, elle fut l’allure, la femme pure.","ipa":"/ˈɛl fˈy ɡʁɑ̃dˈœʁ ˈɛl fˈy lalˈyʁ lˈa- fˈam pˈyʁ/","zh":"她曾如此卓越，如此风姿绰约，是纯洁的女人。","en":"She was greatness, she was grace, the pure woman.","note":"推定修订"},{"id":"la-dame-aux-camelias-01-018","lineIndex":18,"sourceLineIndex":18,"speaker":"","original":"Face aux belles aventures, elle cachait son cœur sous son armure.","ipa":"/fˈas ˈo bˈɛl avɑ̃tˈyʁ ˈɛl kaʃˈɛ sˈɔ̃ kˈœʁ sˈu sˈɔ̃ aʁmˈyʁ/","zh":"面对美好的际遇，她把心藏在铠甲之下。","en":"Facing beautiful adventures, she hid her heart beneath her armor.","note":"推定修订"},{"id":"la-dame-aux-camelias-01-019","lineIndex":19,"sourceLineIndex":19,"speaker":"","original":"Âme déchue qui nous sauve de nos vices.","ipa":"/ˈaːm deʃˈy kˈi nˈu sˈov dˈə- nˈo vˈis/","zh":"一个堕落的灵魂将我们从恶习中拯救出来。","en":"A fallen soul who saves us from our vices.","note":"推定修订"},{"id":"la-dame-aux-camelias-01-020","lineIndex":20,"sourceLineIndex":20,"speaker":"","original":"En demeurant loyale, loin des feux d’artifice.","ipa":"/ˈɑ̃ dəmøʁˈɑ̃ lwajˈal lwˈɛ̃ dˈe- fˈø daʁtifˈis/","zh":"依然忠诚，远离烟火喧嚣。","en":"By remaining loyal, far from fireworks.","note":"推定修订"},{"id":"la-dame-aux-camelias-01-021","lineIndex":21,"sourceLineIndex":21,"speaker":"","original":"Sous l’amitié, nos cœurs se déchirent.","ipa":"/sˈu lamitjˈe nˈo kˈœʁ sˈə- deʃˈiʁ/","zh":"友情之下，我们的心彼此撕裂。","en":"Beneath friendship, our hearts tear apart.","note":"推定修订"},{"id":"la-dame-aux-camelias-01-022","lineIndex":22,"sourceLineIndex":22,"speaker":"","original":"L’hypocrisie reste la norme dans la conquête.","ipa":"/lipɔkʁizˈi ʁˈɛst lˈa- nˈɔʁm dˈɑ̃ lˈa- kɔ̃kˈɛt/","zh":"在这场追逐中，虚伪仍是常态。","en":"Hypocrisy remains the norm in the pursuit.","note":"推定修订"},{"id":"la-dame-aux-camelias-01-023","lineIndex":23,"sourceLineIndex":23,"speaker":"","original":"À Paris, cité des amours éphémères.","ipa":"/ˈa paʁˈi sitˈe dˈe- amˈuʁ efemˈɛʁ/","zh":"在巴黎，这座短暂爱情之城。","en":"In Paris, city of fleeting loves.","note":"推定修订"},{"id":"la-dame-aux-camelias-01-024","lineIndex":24,"sourceLineIndex":24,"speaker":"","original":"Où les passions naissent et meurent en un soir.","ipa":"/ˈu lˈe- pasjˈɔ̃ nˈɛs ˈe mˈœʁ ˈɑ̃ ˈœ̃ swˈaʁ/","zh":"激情在这里一夜之间诞生，又一夜之间消亡。","en":"Where passions are born and die in a single night.","note":"推定修订"},{"id":"la-dame-aux-camelias-01-025","lineIndex":25,"sourceLineIndex":25,"speaker":"","original":"Camélia fanée, cœur brisé en miettes.","ipa":"/kameljˈa fanˈe kˈœʁ bʁizˈe ˈɑ̃ mjˈɛt/","zh":"茶花凋零，心碎成片。","en":"Withered camellia, a heart broken to pieces.","note":"推定修订"},{"id":"la-dame-aux-camelias-01-026","lineIndex":26,"sourceLineIndex":26,"speaker":"","original":"L’amour est un jeu, mais la mort est la reine.","ipa":"/lamˈuʁ ˈɛ ˈœ̃ ʒˈø mˈɛ lˈa- mˈɔʁ ˈɛ lˈa- ʁˈɛn/","zh":"爱情是一场游戏，但死亡才是女王。","en":"Love is a game, but death is the queen.","note":"推定修订"},{"id":"la-dame-aux-camelias-01-027","lineIndex":27,"sourceLineIndex":27,"speaker":"","original":"J’ai tant craint pour mon fils et pour notre honneur.","ipa":"/ʒˈe tˈɑ̃ kʁˈɛ̃ pˈuʁ mˈɔ̃ fˈil ˈe pˈuʁ nˈotʁ ɔnˈœʁ/","zh":"我如此担忧儿子，也担忧我们的名誉。","en":"I feared so much for my son and for our honor.","note":"推定修订"},{"id":"la-dame-aux-camelias-01-028","lineIndex":28,"sourceLineIndex":28,"speaker":"","original":"Voyant son amour, son caprice comme une marque de grandeur.","ipa":"/vwajˈɑ̃ sˈɔ̃ amˈuʁ sˈɔ̃ kapʁˈis kˈɔm ˈyn mˈaʁk dˈə- ɡʁɑ̃dˈœʁ/","zh":"看着他的爱情、他的任性，被当作荣耀的标记。","en":"Seeing his love, his whim as a mark of greatness.","note":"推定修订"},{"id":"la-dame-aux-camelias-01-029","lineIndex":29,"sourceLineIndex":29,"speaker":"","original":"Trophée brûlant qui flatte mon envie de posséder.","ipa":"/tʁofˈe bʁylˈɑ̃ kˈi flˈat mˈɔ̃ ɑ̃vˈi dˈə- pɔsedˈe/","zh":"一座炽热的奖杯，满足我占有的欲望。","en":"A burning trophy that flatters my desire to possess.","note":"推定修订"},{"id":"la-dame-aux-camelias-01-030","lineIndex":30,"sourceLineIndex":30,"speaker":"","original":"J’ai préféré sa mort lente plutôt que de l’aider.","ipa":"/ʒˈe pʁefeʁˈe sˈa- mˈɔʁ lˈɑ̃t plytˈoː kˈə dˈə- lɛdˈe/","zh":"我宁愿看她慢慢死去，也不愿帮助她。","en":"I chose her slow death rather than help her.","note":"推定修订"},{"id":"la-dame-aux-camelias-01-031","lineIndex":31,"sourceLineIndex":31,"speaker":"","original":"Décor de ma richesse et garante de mon rang.","ipa":"/dekˈɔʁ dˈə- mˈa- ʁiʃˈɛs ˈe ɡaʁˈɑ̃t dˈə- mˈɔ̃ ʁˈɑ̃/","zh":"她是我财富的装点，也是我地位的保障。","en":"A display of my wealth and guarantor of my status.","note":"推定修订"},{"id":"la-dame-aux-camelias-01-032","lineIndex":32,"sourceLineIndex":32,"speaker":"","original":"Trop lâche pour l’aimer, j’ai fui en l’ignorant.","ipa":"/tʁˈo lˈaːʃ pˈuʁ lɛmˈe ʒˈe fyˈi ˈɑ̃ linjoʁˈɑ̃/","zh":"我懦弱得不敢爱她，只能逃开并对她不闻不问。","en":"Too cowardly to love her, I fled by ignoring her.","note":"推定修订"},{"id":"la-dame-aux-camelias-01-033","lineIndex":33,"sourceLineIndex":33,"speaker":"","original":"Modèle de beauté que tout homme désire.","ipa":"/modˈɛl dˈə- botˈe kˈə tˈu ˈɔm dezˈiʁ/","zh":"她是所有男人都渴望的美丽典范。","en":"A model of beauty desired by every man.","note":"推定修订"},{"id":"la-dame-aux-camelias-01-034","lineIndex":34,"sourceLineIndex":34,"speaker":"","original":"Mon cœur se fait de pierre et mon âme soupire.","ipa":"/mˈɔ̃ kˈœʁ sˈə- fˈɛ dˈə- pjˈɛʁ ˈe mˈɔ̃ ˈaːm supˈiʁ/","zh":"我的心化作石头，我的灵魂发出叹息。","en":"My heart turns to stone, and my soul sighs.","note":"推定修订"},{"id":"la-dame-aux-camelias-01-035","lineIndex":35,"sourceLineIndex":35,"speaker":"","original":"Elle avait ce pouvoir d’aimer que je n’ai jamais eu.","ipa":"/ˈɛl avˈɛ sˈə- puvwˈaʁ dɛmˈe kˈə ʒˈə- nˈe ʒamˈɛ ˈy/","zh":"她拥有爱的能力，而我从未拥有。","en":"She had the power to love that I never had.","note":"推定修订"},{"id":"la-dame-aux-camelias-01-036","lineIndex":36,"sourceLineIndex":36,"speaker":"","original":"Sa mort m’aura donné la gloire que j’ai tant attendue.","ipa":"/sˈa- mˈɔʁ moʁˈa dɔnˈe lˈa- ɡlwˈaʁ kˈə ʒˈe tˈɑ̃ atɑ̃dˈy/","zh":"她的死终将带给我期盼已久的荣耀。","en":"Her death will have given me the glory I waited so long for.","note":"推定修订"},{"id":"la-dame-aux-camelias-01-037","lineIndex":37,"sourceLineIndex":37,"speaker":"","original":"À Paris, si tu es des amours éphémères.","ipa":"/ˈa paʁˈi sˈi tˈy ˈɛ dˈe- amˈuʁ efemˈɛʁ/","zh":"在巴黎，若你也属于那些短暂的爱情。","en":"In Paris, if you are among the fleeting loves.","note":"推定修订"},{"id":"la-dame-aux-camelias-01-038","lineIndex":38,"sourceLineIndex":38,"speaker":"","original":"Où les passions naissent et meurent en un soir.","ipa":"/ˈu lˈe- pasjˈɔ̃ nˈɛs ˈe mˈœʁ ˈɑ̃ ˈœ̃ swˈaʁ/","zh":"激情在这里一夜之间诞生，又一夜之间消亡。","en":"Where passions are born and die in a single night.","note":"推定修订"},{"id":"la-dame-aux-camelias-01-039","lineIndex":39,"sourceLineIndex":39,"speaker":"","original":"Car il y a pas des cœurs brisés en miettes.","ipa":"/kˈaʁ ˈil iɡʁˈɛk ˈa pˈa dˈe- kˈœʁ bʁizˈe ˈɑ̃ mjˈɛt/","zh":"因为没有心碎成片。","en":"Because there are no hearts broken to pieces.","note":"推定修订"},{"id":"la-dame-aux-camelias-01-040","lineIndex":40,"sourceLineIndex":40,"speaker":"","original":"L’amour est un jeu de l’amour et la haine.","ipa":"/lamˈuʁ ˈɛ ˈœ̃ ʒˈø dˈə- lamˈuʁ ˈe lˈa- ˈɛn/","zh":"爱情是一场由爱与恨构成的游戏。","en":"Love is a game of love and hatred.","note":"推定修订"},{"id":"la-dame-aux-camelias-01-041","lineIndex":41,"sourceLineIndex":41,"speaker":"","original":"Le titre passage qui se vend et n’a pas de prix.","ipa":"/lˈə- tˈitʁ pasˈaʒ kˈi sˈə- vˈɑ̃ ˈe nˈa pˈa dˈə- pʁˈi/","zh":"这段名为 passage、可以售卖却无价的内容。","en":"The title passage that sells and has no price.","note":"推定修订"},{"id":"la-dame-aux-camelias-01-042","lineIndex":42,"sourceLineIndex":42,"speaker":"","original":"Légendes et amours qui ne peuvent pas mourir.","ipa":"/leʒˈɑ̃d ˈe amˈuʁ kˈi nˈə- pˈøv pˈa muʁˈiʁ/","zh":"不朽的传奇与爱情。","en":"Legends and loves that cannot die.","note":"推定修订"},{"id":"la-dame-aux-camelias-01-043","lineIndex":43,"sourceLineIndex":43,"speaker":"","original":"Découvrez le combat de la dame au camélia.","ipa":"/dekuvʁˈe lˈə- kɔ̃bˈa dˈə- lˈa- dˈam ˈo kameljˈa/","zh":"来了解这位茶花女的抗争。","en":"Discover the struggle of the lady with the camellia.","note":"推定修订"}],"sourceOrder":1,"displayOrder":1},{"order":2,"id":"02-je-joue-a-fond","title":"Je joue à fond","titleZh":"我全力出演","lines":[{"id":"la-dame-aux-camelias-02-092","lineIndex":1,"sourceLineIndex":1,"speaker":"","original":"Oh, oh.","ipa":"/ˈɔ ˈɔ/","zh":"哦，哦。","en":"Oh, oh.","note":"推定修订"},{"id":"la-dame-aux-camelias-02-003","lineIndex":2,"sourceLineIndex":2,"speaker":"","original":"On dit que je suis un petit gars de la haute.","ipa":"/ˈɔ̃ dˈi kˈə ʒˈə- syˈi ˈœ̃ pətˈi ɡˈa dˈə- lˈa- ˈot/","zh":"人们说我是个出身上流社会的小伙子。","en":"They say I am a little rich kid.","note":"推定修订"},{"id":"la-dame-aux-camelias-02-004","lineIndex":3,"sourceLineIndex":3,"speaker":"","original":"On me prend pour ce que je ne suis pas.","ipa":"/ˈɔ̃ mˈə- pʁˈɑ̃ pˈuʁ sˈə- kˈə ʒˈə- nˈə- syˈi pˈa/","zh":"人们把我当成一个并非真正的我。","en":"They take me for someone I am not.","note":"推定修订"},{"id":"la-dame-aux-camelias-02-005","lineIndex":4,"sourceLineIndex":4,"speaker":"","original":"On me prend pour un de ceux qui ont la cote.","ipa":"/ˈɔ̃ mˈə- pʁˈɑ̃ pˈuʁ ˈœ̃ dˈə- sˈø kˈi ˈɔ̃ lˈa- kˈɔt/","zh":"他们以为我是那些风头正盛的人之一。","en":"They take me for one of the popular crowd.","note":"推定修订"},{"id":"la-dame-aux-camelias-02-006","lineIndex":5,"sourceLineIndex":5,"speaker":"","original":"Pour un fils à papa.","ipa":"/pˈuʁ ˈœ̃ fˈil ˈa papˈa/","zh":"当我是个靠父亲的公子哥。","en":"For a daddy’s boy.","note":"推定修订"},{"id":"la-dame-aux-camelias-02-064","lineIndex":6,"sourceLineIndex":6,"speaker":"","original":"Je joue à fond, fond, fond, fond, la petite marionnette.","ipa":"/ʒˈə- ʒˈu ˈa fˈɔ̃ fˈɔ̃ fˈɔ̃ fˈɔ̃ lˈa- pətˈit maʁjɔnˈɛt/","zh":"我全力以赴、全力以赴、全力以赴、全力以赴，像个小木偶。","en":"I go all in, all in, all in, all in, the little puppet.","note":"推定修订"},{"id":"la-dame-aux-camelias-02-065","lineIndex":7,"sourceLineIndex":7,"speaker":"","original":"Fond, fond, fond, fond, comme il faut.","ipa":"/fˈɔ̃ fˈɔ̃ fˈɔ̃ fˈɔ̃ kˈɔm ˈil fˈo/","zh":"全力以赴、全力以赴、全力以赴、全力以赴，恰如其分。","en":"All in, all in, all in, all in, just as it should be.","note":"推定修订"},{"id":"la-dame-aux-camelias-02-066","lineIndex":8,"sourceLineIndex":8,"speaker":"","original":"Je joue à fond, fond, fond, fond, la petite marionnette.","ipa":"/ʒˈə- ʒˈu ˈa fˈɔ̃ fˈɔ̃ fˈɔ̃ fˈɔ̃ lˈa- pətˈit maʁjɔnˈɛt/","zh":"我全力以赴、全力以赴、全力以赴、全力以赴，像个小木偶。","en":"I go all in, all in, all in, all in, the little puppet.","note":"推定修订"},{"id":"la-dame-aux-camelias-02-067","lineIndex":9,"sourceLineIndex":9,"speaker":"","original":"Je joue à fond, fond, fond, fond.","ipa":"/ʒˈə- ʒˈu ˈa fˈɔ̃ fˈɔ̃ fˈɔ̃ fˈɔ̃/","zh":"我全力以赴、全力以赴、全力以赴、全力以赴。","en":"I go all in, all in, all in, all in.","note":"推定修订"},{"id":"la-dame-aux-camelias-02-068","lineIndex":10,"sourceLineIndex":10,"speaker":"","original":"Je serre un peu les dents.","ipa":"/ʒˈə- sˈɛʁ ˈœ̃ pˈø lˈe- dˈɑ̃/","zh":"我稍稍咬紧牙关。","en":"I grit my teeth a little.","note":"推定修订"},{"id":"la-dame-aux-camelias-02-069","lineIndex":11,"sourceLineIndex":11,"speaker":"","original":"J’attends le bon moment.","ipa":"/ʒatˈɑ̃ lˈə- bˈɔ̃ momˈɑ̃/","zh":"我在等待合适的时机。","en":"I’m waiting for the right moment.","note":"推定修订"},{"id":"la-dame-aux-camelias-02-070","lineIndex":12,"sourceLineIndex":12,"speaker":"","original":"Pour être vraiment moi.","ipa":"/pˈuʁ ˈɛtʁ vʁɛmˈɑ̃ mwˈa/","zh":"好真正做自己。","en":"To truly be myself.","note":"推定修订"},{"id":"la-dame-aux-camelias-02-071","lineIndex":13,"sourceLineIndex":13,"speaker":"","original":"On dit qu’j’suis un gars bien né.","ipa":"/ˈɔ̃ dˈi kwdʒsˈuːiz ˈœ̃ ɡˈa bjˈɛ̃ nˈe/","zh":"人们说我出身优越。","en":"They say I’m a well-born guy.","note":"推定修订"},{"id":"la-dame-aux-camelias-02-072","lineIndex":14,"sourceLineIndex":14,"speaker":"","original":"Et que c’est tout mérité.","ipa":"/ˈe kˈə sˈɛ tˈu meʁitˈe/","zh":"还说这一切都是我应得的。","en":"And that I’ve earned it all.","note":"推定修订"},{"id":"la-dame-aux-camelias-02-073","lineIndex":15,"sourceLineIndex":15,"speaker":"","original":"J’ai pas d’argent plein les doigts.","ipa":"/ʒˈe pˈa daʁʒˈɑ̃ plˈɛ̃ lˈe- dwˈa/","zh":"我手里并没有大把的钱。","en":"I don’t have money spilling through my fingers.","note":"推定修订"},{"id":"la-dame-aux-camelias-02-074","lineIndex":16,"sourceLineIndex":16,"speaker":"","original":"On me prend pour ce que je suis pas.","ipa":"/ˈɔ̃ mˈə- pʁˈɑ̃ pˈuʁ sˈə- kˈə ʒˈə- syˈi pˈa/","zh":"他们把我当成了并非如此的人。","en":"They take me for someone I am not.","note":"推定修订"},{"id":"la-dame-aux-camelias-02-075","lineIndex":17,"sourceLineIndex":17,"speaker":"","original":"Je joue à fond, fond, fond, fond.","ipa":"/ʒˈə- ʒˈu ˈa fˈɔ̃ fˈɔ̃ fˈɔ̃ fˈɔ̃/","zh":"我全力以赴、全力以赴、全力以赴、全力以赴。","en":"I go all in, all in, all in, all in.","note":"推定修订"},{"id":"la-dame-aux-camelias-02-009","lineIndex":18,"sourceLineIndex":18,"speaker":"","original":"La petite marionnette.","ipa":"/lˈa- pətˈit maʁjɔnˈɛt/","zh":"小木偶。","en":"The little puppet.","note":"推定修订"},{"id":"la-dame-aux-camelias-02-076","lineIndex":19,"sourceLineIndex":19,"speaker":"","original":"Fond, fond, fond, fond.","ipa":"/fˈɔ̃ fˈɔ̃ fˈɔ̃ fˈɔ̃/","zh":"全力以赴、全力以赴、全力以赴、全力以赴。","en":"All in, all in, all in, all in.","note":"推定修订"},{"id":"la-dame-aux-camelias-02-011","lineIndex":20,"sourceLineIndex":20,"speaker":"","original":"Comme il faut.","ipa":"/kˈɔm ˈil fˈo/","zh":"恰如其分。","en":"Just as it should be.","note":"推定修订"},{"id":"la-dame-aux-camelias-02-077","lineIndex":21,"sourceLineIndex":21,"speaker":"","original":"Fond, fond, fond, fond, la petite marionnette.","ipa":"/fˈɔ̃ fˈɔ̃ fˈɔ̃ fˈɔ̃ lˈa- pətˈit maʁjɔnˈɛt/","zh":"全力以赴、全力以赴、全力以赴、全力以赴，小木偶。","en":"All in, all in, all in, all in, the little puppet.","note":"推定修订"},{"id":"la-dame-aux-camelias-02-078","lineIndex":22,"sourceLineIndex":22,"speaker":"","original":"Je joue à fond, fond, fond, fond.","ipa":"/ʒˈə- ʒˈu ˈa fˈɔ̃ fˈɔ̃ fˈɔ̃ fˈɔ̃/","zh":"我全力以赴、全力以赴、全力以赴、全力以赴。","en":"I go all in, all in, all in, all in.","note":"推定修订"},{"id":"la-dame-aux-camelias-02-017","lineIndex":23,"sourceLineIndex":23,"speaker":"","original":"Je serre un peu les dents.","ipa":"/ʒˈə- sˈɛʁ ˈœ̃ pˈø lˈe- dˈɑ̃/","zh":"我稍稍咬紧牙关。","en":"I grit my teeth a little.","note":"推定修订"},{"id":"la-dame-aux-camelias-02-079","lineIndex":24,"sourceLineIndex":24,"speaker":"","original":"Wow, j’attends le bon moment.","ipa":"/wˈaʊ ʒatˈɑ̃ lˈə- bˈɔ̃ momˈɑ̃/","zh":"哇，我在等待合适的时机。","en":"Wow, I’m waiting for the right moment.","note":"推定修订"},{"id":"la-dame-aux-camelias-02-080","lineIndex":25,"sourceLineIndex":25,"speaker":"","original":"Wow, pour être vraiment moi.","ipa":"/wˈaʊ pˈuʁ ˈɛtʁ vʁɛmˈɑ̃ mwˈa/","zh":"哇，好真正做自己。","en":"Wow, to truly be myself.","note":"推定修订"},{"id":"la-dame-aux-camelias-02-081","lineIndex":26,"sourceLineIndex":26,"speaker":"","original":"Je suis né bourgeois.","ipa":"/ʒˈə- syˈi nˈe buʁʒwˈa/","zh":"我生来就是资产阶级出身。","en":"I was born bourgeois.","note":"推定修订"},{"id":"la-dame-aux-camelias-02-082","lineIndex":27,"sourceLineIndex":27,"speaker":"","original":"Oh, je sais, je sais, je n’en fais pas état.","ipa":"/ˈɔ ʒˈə- sˈɛ ʒˈə- sˈɛ ʒˈə- nˈɑ̃ fˈɛ pˈa etˈa/","zh":"哦，我知道，我知道；我并不拿这个张扬。","en":"Oh, I know, I know; I don’t make a show of it.","note":"推定修订"},{"id":"la-dame-aux-camelias-02-083","lineIndex":28,"sourceLineIndex":28,"speaker":"","original":"Je joue, je joue, je joue, j’ai pas le choix.","ipa":"/ʒˈə- ʒˈu ʒˈə- ʒˈu ʒˈə- ʒˈu ʒˈe pˈa lˈə- ʃwˈa/","zh":"我演，我演，我演；我别无选择。","en":"I play, I play, I play; I have no choice.","note":"推定修订"},{"id":"la-dame-aux-camelias-02-084","lineIndex":29,"sourceLineIndex":29,"speaker":"","original":"Je joue, je joue, je joue, je joue, j’ai pas le choix.","ipa":"/ʒˈə- ʒˈu ʒˈə- ʒˈu ʒˈə- ʒˈu ʒˈə- ʒˈu ʒˈe pˈa lˈə- ʃwˈa/","zh":"我演，我演，我演，我演；我别无选择。","en":"I play, I play, I play, I play; I have no choice.","note":"推定修订"},{"id":"la-dame-aux-camelias-02-085","lineIndex":30,"sourceLineIndex":30,"speaker":"","original":"Oh, je sais, je sais, je suis né comme ça.","ipa":"/ˈɔ ʒˈə- sˈɛ ʒˈə- sˈɛ ʒˈə- syˈi nˈe kˈɔm sˈa/","zh":"哦，我知道，我知道；我生来如此。","en":"Oh, I know, I know; I was born this way.","note":"推定修订"},{"id":"la-dame-aux-camelias-02-086","lineIndex":31,"sourceLineIndex":31,"speaker":"","original":"Je joue à fond, fond, fond, fond, la petite marionnette.","ipa":"/ʒˈə- ʒˈu ˈa fˈɔ̃ fˈɔ̃ fˈɔ̃ fˈɔ̃ lˈa- pətˈit maʁjɔnˈɛt/","zh":"我全力以赴、全力以赴、全力以赴、全力以赴，像个小木偶。","en":"I go all in, all in, all in, all in, the little puppet.","note":"推定修订"},{"id":"la-dame-aux-camelias-02-087","lineIndex":32,"sourceLineIndex":32,"speaker":"","original":"J’joue à fond, fond, fond, comme il faut.","ipa":"/ʒʒˈu ˈa fˈɔ̃ fˈɔ̃ fˈɔ̃ kˈɔm ˈil fˈo/","zh":"我全力以赴、全力以赴、全力以赴，恰如其分。","en":"I go all in, all in, all in, as I should.","note":"推定修订"},{"id":"la-dame-aux-camelias-02-088","lineIndex":33,"sourceLineIndex":33,"speaker":"","original":"Je joue à fond, fond, fond, fond, la petite marionnette.","ipa":"/ʒˈə- ʒˈu ˈa fˈɔ̃ fˈɔ̃ fˈɔ̃ fˈɔ̃ lˈa- pətˈit maʁjɔnˈɛt/","zh":"我全力以赴、全力以赴、全力以赴、全力以赴，像个小木偶。","en":"I go all in, all in, all in, all in, the little puppet.","note":"推定修订"},{"id":"la-dame-aux-camelias-02-089","lineIndex":34,"sourceLineIndex":34,"speaker":"","original":"Je joue à fond, fond, fond, fond.","ipa":"/ʒˈə- ʒˈu ˈa fˈɔ̃ fˈɔ̃ fˈɔ̃ fˈɔ̃/","zh":"我全力以赴、全力以赴、全力以赴、全力以赴。","en":"I go all in, all in, all in, all in.","note":"推定修订"},{"id":"la-dame-aux-camelias-02-036","lineIndex":35,"sourceLineIndex":35,"speaker":"","original":"Je serre un peu les dents.","ipa":"/ʒˈə- sˈɛʁ ˈœ̃ pˈø lˈe- dˈɑ̃/","zh":"我稍稍咬紧牙关。","en":"I grit my teeth a little.","note":"推定修订"},{"id":"la-dame-aux-camelias-02-090","lineIndex":36,"sourceLineIndex":36,"speaker":"","original":"Wow, j’attends le bon moment.","ipa":"/wˈaʊ ʒatˈɑ̃ lˈə- bˈɔ̃ momˈɑ̃/","zh":"哇，我在等待合适的时机。","en":"Wow, I’m waiting for the right moment.","note":"推定修订"},{"id":"la-dame-aux-camelias-02-091","lineIndex":37,"sourceLineIndex":37,"speaker":"","original":"Wow, pour être vraiment moi.","ipa":"/wˈaʊ pˈuʁ ˈɛtʁ vʁɛmˈɑ̃ mwˈa/","zh":"哇，好真正做自己。","en":"Wow, to truly be myself.","note":"推定修订"}],"sourceOrder":2,"displayOrder":2},{"order":3,"id":"03-reine-de-paris","title":"Reine de Paris","titleZh":"巴黎女王","lines":[{"id":"la-dame-aux-camelias-03-045","lineIndex":1,"sourceLineIndex":1,"speaker":"","original":"Ah, ah, ah, ah, ah, ah, ah, ah, ah, ah, ah, ah, ah.","ipa":"/ˈa ˈa ˈa ˈa ˈa ˈa ˈa ˈa ˈa ˈa ˈa ˈa ˈa/","zh":"啊，啊，啊，啊，啊，啊，啊，啊，啊，啊，啊，啊，啊。","en":"Ah, ah, ah, ah, ah, ah, ah, ah, ah, ah, ah, ah, ah.","note":"推定修订"},{"id":"la-dame-aux-camelias-03-001","lineIndex":2,"sourceLineIndex":2,"speaker":"","original":"Regardez-moi, je tombe du ciel.","ipa":"/ʁəɡaʁdˈemwˈa ʒˈə- tˈɔ̃b dˈy- sjˈɛl/","zh":"看着我，我从天而降。","en":"Look at me, I am falling from the sky.","note":"推定修订"},{"id":"la-dame-aux-camelias-03-002","lineIndex":3,"sourceLineIndex":3,"speaker":"","original":"Un ange de soie, un goût de miel.","ipa":"/ˈœ̃ ˈɑ̃ʒ dˈə- swˈa ˈœ̃ ɡˈu dˈə- mjˈɛl/","zh":"丝绸般的天使，蜜糖般的滋味。","en":"An angel of silk, a taste of honey.","note":"推定修订"},{"id":"la-dame-aux-camelias-03-003","lineIndex":4,"sourceLineIndex":4,"speaker":"","original":"Suspendue entre deux éclats.","ipa":"/syspɑ̃dˈy ˈɑ̃tʁ dˈø eklˈa/","zh":"悬在两束光芒之间。","en":"Suspended between two flashes of light.","note":"推定修订"},{"id":"la-dame-aux-camelias-03-004","lineIndex":5,"sourceLineIndex":5,"speaker":"","original":"Le monde s’arrête où je pose mes pas.","ipa":"/lˈə- mˈɔ̃d saʁˈɛt ˈu ʒˈə- pˈɔz mˈe- pˈa/","zh":"我踏足之处，世界便停下。","en":"The world stops wherever I set my feet.","note":"推定修订"},{"id":"la-dame-aux-camelias-03-046","lineIndex":6,"sourceLineIndex":6,"speaker":"","original":"Camélia blanche sur mon cœur qui bat.","ipa":"/kameljˈa blˈɑ̃ʃ sˈyʁ mˈɔ̃ kˈœʁ kˈi bˈa/","zh":"一朵白茶花，落在我跳动的心上。","en":"A white camellia over my beating heart.","note":"推定修订"},{"id":"la-dame-aux-camelias-03-006","lineIndex":7,"sourceLineIndex":7,"speaker":"","original":"Je suis le rêve qu’on n’atteint pas.","ipa":"/ʒˈə- syˈi lˈə- ʁˈɛv kˈɔ̃ natˈɛ̃ pˈa/","zh":"我是一个无人能够企及的梦。","en":"I am the dream no one can attain.","note":"推定修订"},{"id":"la-dame-aux-camelias-03-047","lineIndex":8,"sourceLineIndex":8,"speaker":"","original":"La foule s’amasse, elle veut sa part de sourire, de regard.","ipa":"/lˈa- fˈul samˈas ˈɛl vˈø sˈa- pˈaʁ dˈə- suʁˈiʁ dˈə- ʁəɡˈaʁ/","zh":"人群聚拢而来，想分得我的笑容与目光。","en":"The crowd gathers, wanting its share of smiles and glances.","note":"推定修订"},{"id":"la-dame-aux-camelias-03-048","lineIndex":9,"sourceLineIndex":9,"speaker":"","original":"Payez le prix, je vaux la peine. Vénérez-moi comme une reine.","ipa":"/pɛjˈe lˈə- pʁˈi ʒˈə- vˈo lˈa- pˈɛn veneʁˈemwˈa kˈɔm ˈyn ʁˈɛn/","zh":"付出代价吧，我值得。像女王一样敬仰我。","en":"Pay the price; I am worth it. Worship me like a queen.","note":"推定修订"},{"id":"la-dame-aux-camelias-03-011","lineIndex":10,"sourceLineIndex":10,"speaker":"","original":"Un souffle, une étincelle…","ipa":"/ˈœ̃ sˈufl ˈyn etɛ̃sˈɛl/","zh":"一缕气息，一点火花……","en":"A breath, a spark…","note":"推定修订"},{"id":"la-dame-aux-camelias-03-049","lineIndex":11,"sourceLineIndex":11,"speaker":"","original":"Je suis la fièvre, je suis l’éclat, votre seul sacre, votre seul combat.","ipa":"/ʒˈə- syˈi lˈa- fjˈɛvʁ ʒˈə- syˈi leklˈa vˈotʁ sˈœl sˈakʁ vˈotʁ sˈœl kɔ̃bˈa/","zh":"我是热病，是光芒，是你唯一的加冕、唯一的战斗。","en":"I am the fever, I am the brilliance, your one coronation, your one battle.","note":"推定修订"},{"id":"la-dame-aux-camelias-03-050","lineIndex":12,"sourceLineIndex":12,"speaker":"","original":"Je brûle vos nuits, déchire le noir. Je suis l’image dans le miroir.","ipa":"/ʒˈə- bʁˈyːl vˈo nyˈi deʃˈiʁ lˈə- nwˈaʁ ʒˈə- syˈi limˈaʒ dˈɑ̃ lˈə- miʁwˈaʁ/","zh":"我燃亮你们的长夜，撕开黑暗。我就是镜中的影像。","en":"I burn through your nights, tear through the dark. I am the image in the mirror.","note":"推定修订"},{"id":"la-dame-aux-camelias-03-051","lineIndex":13,"sourceLineIndex":13,"speaker":"","original":"Provocante, éternelle.","ipa":"/pʁovokˈɑ̃t etɛʁnˈɛl/","zh":"挑逗而永恒。","en":"Provocative, eternal.","note":"推定修订"},{"id":"la-dame-aux-camelias-03-017","lineIndex":14,"sourceLineIndex":14,"speaker":"","original":"Sous les velours, je reste rebelle.","ipa":"/sˈu lˈe- vəlˈuʁ ʒˈə- ʁˈɛst ʁəbˈɛl/","zh":"在丝绒之下，我依然叛逆。","en":"Beneath the velvet, I remain rebellious.","note":"推定修订"},{"id":"la-dame-aux-camelias-03-018","lineIndex":15,"sourceLineIndex":15,"speaker":"","original":"Mon nom circule dans les salons.","ipa":"/mˈɔ̃ nˈɔ̃ siʁkˈyl dˈɑ̃ lˈe- salˈɔ̃/","zh":"我的名字在沙龙间流传。","en":"My name is spoken in the salons.","note":"推定修订"},{"id":"la-dame-aux-camelias-03-052","lineIndex":16,"sourceLineIndex":16,"speaker":"","original":"Je suis la prière des ambitions.","ipa":"/ʒˈə- syˈi lˈa- pʁiˈɛʁ dˈe- ɑ̃bisjˈɔ̃/","zh":"我是野心者的祈愿。","en":"I am the prayer of ambition.","note":"推定修订"},{"id":"la-dame-aux-camelias-03-053","lineIndex":17,"sourceLineIndex":17,"speaker":"","original":"De l’Opéra jusqu’au boulevard.","ipa":"/dˈə- lopeʁˈa ʒˈysko bulvˈaʁ/","zh":"从歌剧院一路到林荫大道。","en":"From the Opera to the boulevard.","note":"推定修订"},{"id":"la-dame-aux-camelias-03-021","lineIndex":18,"sourceLineIndex":18,"speaker":"","original":"Je sème le trouble, je suis à part.","ipa":"/ʒˈə- sˈɛm lˈə- tʁˈubl ʒˈə- syˈi ˈa pˈaʁ/","zh":"我搅动风波，自成一派。","en":"I stir up trouble; I stand apart.","note":"推定修订"},{"id":"la-dame-aux-camelias-03-022","lineIndex":19,"sourceLineIndex":19,"speaker":"","original":"On m’achète un soir, on m’espère toujours.","ipa":"/ˈɔ̃ maʃˈɛt ˈœ̃ swˈaʁ ˈɔ̃ mɛspˈɛʁ tuʒˈuʁ/","zh":"他们买我一夜，却总对我抱有期望。","en":"They buy me for one night, yet always hope for me.","note":"推定修订"},{"id":"la-dame-aux-camelias-03-023","lineIndex":20,"sourceLineIndex":20,"speaker":"","original":"Je suis l’emblème des faux amours.","ipa":"/ʒˈə- syˈi lɑ̃blˈɛm dˈe- fˈo amˈuʁ/","zh":"我是虚假爱情的象征。","en":"I am the emblem of false love.","note":"推定修订"},{"id":"la-dame-aux-camelias-03-054","lineIndex":21,"sourceLineIndex":21,"speaker":"","original":"Je suis la fièvre, je suis l’éclat. Votre seul sacre, votre seul combat.","ipa":"/ʒˈə- syˈi lˈa- fjˈɛvʁ ʒˈə- syˈi leklˈa vˈotʁ sˈœl sˈakʁ vˈotʁ sˈœl kɔ̃bˈa/","zh":"我是热病，是光芒。你唯一的加冕，唯一的战斗。","en":"I am the fever, I am the brilliance. Your one coronation, your one battle.","note":"推定修订"},{"id":"la-dame-aux-camelias-03-055","lineIndex":22,"sourceLineIndex":22,"speaker":"","original":"Je brûle vos nuits, déchire le noir. Je suis l’image dans le miroir.","ipa":"/ʒˈə- bʁˈyːl vˈo nyˈi deʃˈiʁ lˈə- nwˈaʁ ʒˈə- syˈi limˈaʒ dˈɑ̃ lˈə- miʁwˈaʁ/","zh":"我燃亮你们的长夜，撕开黑暗。我就是镜中的影像。","en":"I burn through your nights, tear through the dark. I am the image in the mirror.","note":"推定修订"},{"id":"la-dame-aux-camelias-03-056","lineIndex":23,"sourceLineIndex":23,"speaker":"","original":"Magnifique, provocante, éternelle. Sous les velours, je reste rebelle.","ipa":"/maɲifˈik pʁovokˈɑ̃t etɛʁnˈɛl sˈu lˈe- vəlˈuʁ ʒˈə- ʁˈɛst ʁəbˈɛl/","zh":"光彩夺目、挑逗而永恒。在丝绒之下，我依然叛逆。","en":"Magnificent, provocative, eternal. Beneath the velvet, I remain rebellious.","note":"推定修订"},{"id":"la-dame-aux-camelias-03-057","lineIndex":24,"sourceLineIndex":24,"speaker":"","original":"Admirez le luxe, comptez l’or fin. Je suis la coupe, je suis le vent.","ipa":"/admiʁˈe lˈə- lˈyks kɔ̃tˈe lˈɔʁ fˈɛ̃ ʒˈə- syˈi lˈa- kˈup ʒˈə- syˈi lˈə- vˈɑ̃/","zh":"欣赏奢华，数一数纯金。我是酒杯，也是风。","en":"Admire the luxury, count the fine gold. I am the cup; I am the wind.","note":"推定修订"},{"id":"la-dame-aux-camelias-03-058","lineIndex":25,"sourceLineIndex":25,"speaker":"","original":"Courtisane ? Non, souveraine. Je brise les codes, je romps les chaînes.","ipa":"/kuʁtizˈan nˈɔ̃ suvʁˈɛn ʒˈə- bʁˈiz lˈe- kˈod ʒˈə- ʁˈɔ̃ lˈe- ʃˈɛn/","zh":"我是交际花？不，我是女王。我打破规矩，挣断枷锁。","en":"Courtesan? No, sovereign. I break the codes; I snap the chains.","note":"推定修订"},{"id":"la-dame-aux-camelias-03-034","lineIndex":26,"sourceLineIndex":26,"speaker":"","original":"Je suis la fleur.","ipa":"/ʒˈə- syˈi lˈa- flˈœʁ/","zh":"我就是那朵花。","en":"I am the flower.","note":"推定修订"},{"id":"la-dame-aux-camelias-03-035","lineIndex":27,"sourceLineIndex":27,"speaker":"","original":"Je suis la fièvre, je suis l’éclat.","ipa":"/ʒˈə- syˈi lˈa- fjˈɛvʁ ʒˈə- syˈi leklˈa/","zh":"我是热病，是光芒。","en":"I am the fever, I am the brilliance.","note":"推定修订"},{"id":"la-dame-aux-camelias-03-036","lineIndex":28,"sourceLineIndex":28,"speaker":"","original":"Votre seul sacre, votre seul combat.","ipa":"/vˈotʁ sˈœl sˈakʁ vˈotʁ sˈœl kɔ̃bˈa/","zh":"你唯一的加冕，唯一的战斗。","en":"Your one coronation, your one battle.","note":"推定修订"},{"id":"la-dame-aux-camelias-03-037","lineIndex":29,"sourceLineIndex":29,"speaker":"","original":"Je brûle vos nuits, je déchire le noir.","ipa":"/ʒˈə- bʁˈyːl vˈo nyˈi ʒˈə- deʃˈiʁ lˈə- nwˈaʁ/","zh":"我燃亮你们的长夜，撕开黑暗。","en":"I burn through your nights; I tear through the dark.","note":"推定修订"},{"id":"la-dame-aux-camelias-03-038","lineIndex":30,"sourceLineIndex":30,"speaker":"","original":"Je suis l’image dans le miroir.","ipa":"/ʒˈə- syˈi limˈaʒ dˈɑ̃ lˈə- miʁwˈaʁ/","zh":"我就是镜中的影像。","en":"I am the image in the mirror.","note":"推定修订"},{"id":"la-dame-aux-camelias-03-059","lineIndex":31,"sourceLineIndex":31,"speaker":"","original":"C’est la vie, c’est la mort.","ipa":"/sˈɛ lˈa- vˈi sˈɛ lˈa- mˈɔʁ/","zh":"这就是生，这就是死。","en":"It is life; it is death.","note":"推定修订"},{"id":"la-dame-aux-camelias-03-060","lineIndex":32,"sourceLineIndex":32,"speaker":"","original":"C’est la vie, c’est la mort.","ipa":"/sˈɛ lˈa- vˈi sˈɛ lˈa- mˈɔʁ/","zh":"这就是生，这就是死。","en":"It is life; it is death.","note":"推定修订"},{"id":"la-dame-aux-camelias-03-061","lineIndex":33,"sourceLineIndex":33,"speaker":"","original":"C’est la vie, c’est la mort.","ipa":"/sˈɛ lˈa- vˈi sˈɛ lˈa- mˈɔʁ/","zh":"这就是生，这就是死。","en":"It is life; it is death.","note":"推定修订"},{"id":"la-dame-aux-camelias-03-062","lineIndex":34,"sourceLineIndex":34,"speaker":"","original":"Magnifique, étonnée.","ipa":"/maɲifˈik etɔnˈe/","zh":"光彩夺目，满怀惊异。","en":"Magnificent, astonished.","note":"推定修订"},{"id":"la-dame-aux-camelias-03-063","lineIndex":35,"sourceLineIndex":35,"speaker":"","original":"Magnifique, étonnée.","ipa":"/maɲifˈik etɔnˈe/","zh":"光彩夺目，满怀惊异。","en":"Magnificent, astonished.","note":"推定修订"},{"id":"la-dame-aux-camelias-03-043","lineIndex":36,"sourceLineIndex":36,"speaker":"","original":"Je suis la Dame aux Camélias.","ipa":"/ʒˈə- syˈi lˈa- dˈam ˈo kameljˈa/","zh":"我就是茶花女。","en":"I am the Lady of the Camellias.","note":"推定修订"},{"id":"la-dame-aux-camelias-03-044","lineIndex":37,"sourceLineIndex":37,"speaker":"","original":"Et Paris m’appartient.","ipa":"/ˈe paʁˈi mapaʁtjˈɛ̃/","zh":"巴黎也属于我。","en":"And Paris belongs to me.","note":"推定修订"}],"sourceOrder":3,"displayOrder":3},{"order":5,"id":"05-vivre","title":"Vivre","titleZh":"生活","lines":[{"id":"la-dame-aux-camelias-05-010","lineIndex":1,"sourceLineIndex":1,"speaker":"","original":"Trinquons à la joie !","ipa":"/tʁɛ̃kˈɔ̃ ˈa lˈa- ʒwˈa/","zh":"为欢乐举杯！","en":"Let us toast to joy!","note":"推定修订"},{"id":"la-dame-aux-camelias-05-011","lineIndex":2,"sourceLineIndex":2,"speaker":"","original":"À l’avenir, au destin que ce vin va me prédire.","ipa":"/ˈa lavnˈiʁ ˈo dɛstˈɛ̃ kˈə sˈə- vˈɛ̃ vˈa mˈə- pʁedˈiʁ/","zh":"敬未来，敬这杯酒将为我预言的命运。","en":"To the future, to the fate that this wine will foretell.","note":"推定修订"},{"id":"la-dame-aux-camelias-05-012","lineIndex":3,"sourceLineIndex":3,"speaker":"","original":"À ce grand mirage, ce doux voyage.","ipa":"/ˈa sˈə- ɡʁˈɑ̃ miʁˈaʒ sˈə- dˈu vwajˈaʒ/","zh":"为这场宏大的幻梦、这段甜美的旅程。","en":"To this great mirage, this sweet journey.","note":"推定修订"},{"id":"la-dame-aux-camelias-05-013","lineIndex":4,"sourceLineIndex":4,"speaker":"","original":"Lentement, que s’ouvre la porte de ma cage.","ipa":"/lɑ̃tmˈɑ̃ kˈə sˈuvʁ lˈa- pˈɔʁt dˈə- mˈa- kˈaʒ/","zh":"愿我囚笼的门缓缓开启。","en":"Slowly, may the door of my cage open.","note":"推定修订"},{"id":"la-dame-aux-camelias-05-014","lineIndex":5,"sourceLineIndex":5,"speaker":"","original":"Danser dans son sens, elle cherche l’ivresse, en levant nos verres vers le ciel.","ipa":"/dɑ̃sˈe dˈɑ̃ sˈɔ̃ sˈɑ̃s ˈɛl ʃˈɛʁʃ livʁˈɛs ˈɑ̃ ləvˈɑ̃ nˈo vˈɛʁ vˈɛʁ lˈə- sjˈɛl/","zh":"她循着那方向起舞，寻求迷醉，并举起我们的酒杯向天。","en":"Dancing in that direction, she seeks abandon, raising our glasses to the sky.","note":"推定修订"},{"id":"la-dame-aux-camelias-05-015","lineIndex":6,"sourceLineIndex":6,"speaker":"","original":"À ma vie, à ma jeunesse !","ipa":"/ˈa mˈa- vˈi ˈa mˈa- ʒønˈɛs/","zh":"为我的人生，为我的青春举杯！","en":"To my life, to my youth!","note":"推定修订"},{"id":"la-dame-aux-camelias-05-016","lineIndex":7,"sourceLineIndex":7,"speaker":"","original":"Pour pouvoir vivre, être libre, faut d’un plus que tout, les livres et les bureaux…","ipa":"/pˈuʁ puvwˈaʁ vˈivʁ ˈɛtʁ lˈibʁ fˈo dˈœ̃ plˈy kˈə tˈu lˈe- lˈivʁ ˈe lˈe- byʁˈo/","zh":"为了活下去，为了自由，还需要最重要的东西——书本和办公室……","en":"To be able to live, to be free; it takes something above all, books and offices…","note":"推定修订"},{"id":"la-dame-aux-camelias-05-007","lineIndex":8,"sourceLineIndex":8,"speaker":"","original":"Et bien plus que de devoir bien se tenir.","ipa":"/ˈe bjˈɛ̃ plˈy kˈə dˈə- dəvwˈaʁ bjˈɛ̃ sˈə- tənˈiʁ/","zh":"也远胜于不得不举止得体。","en":"And far more than having to behave properly.","note":"推定修订"},{"id":"la-dame-aux-camelias-05-017","lineIndex":9,"sourceLineIndex":9,"speaker":"","original":"À ma santé, boire est une prière.","ipa":"/ˈa mˈa- sɑ̃tˈe bwˈaʁ ˈɛ ˈyn pʁiˈɛʁ/","zh":"为我的健康举杯，饮酒也是一种祈祷。","en":"To my health: drinking is a prayer.","note":"推定修订"},{"id":"la-dame-aux-camelias-05-018","lineIndex":10,"sourceLineIndex":10,"speaker":"","original":"Je vois la lumière au fond de nos verres.","ipa":"/ʒˈə- vwˈa lˈa- lymjˈɛʁ ˈo fˈɔ̃ dˈə- nˈo vˈɛʁ/","zh":"我看见杯底闪烁的光。","en":"I see the light at the bottom of our glasses.","note":"推定修订"},{"id":"la-dame-aux-camelias-05-019","lineIndex":11,"sourceLineIndex":11,"speaker":"","original":"La vie est pleine de plaies, le monde entier…","ipa":"/lˈa- vˈi ˈɛ plˈɛn dˈə- plˈɛ lˈə- mˈɔ̃d ɑ̃tjˈe/","zh":"生活满是伤痕，整个世界……","en":"Life is full of wounds, the whole world…","note":"推定修订"},{"id":"la-dame-aux-camelias-05-020","lineIndex":12,"sourceLineIndex":12,"speaker":"","original":"Rester sans bêtise, gagnant des fortunes…","ipa":"/ʁɛstˈe sˈɑ̃ bɛtˈiz ɡanjˈɑ̃ dˈe- fɔʁtˈyn/","zh":"不犯傻地留下，赢得财富……","en":"Stay without foolishness, winning fortunes…","note":"推定修订"},{"id":"la-dame-aux-camelias-05-021","lineIndex":13,"sourceLineIndex":13,"speaker":"","original":"Et puis nous viendrons sur les têtes…","ipa":"/ˈe pyˈi nˈu vjɛ̃dʁˈɔ̃ sˈyʁ lˈe- tˈɛt/","zh":"然后我们会来到那些头顶之上……","en":"And then we will come upon the heads…","note":"推定修订"},{"id":"la-dame-aux-camelias-05-022","lineIndex":14,"sourceLineIndex":14,"speaker":"","original":"Pour pouvoir vivre, être libre, pourtant…","ipa":"/pˈuʁ puvwˈaʁ vˈivʁ ˈɛtʁ lˈibʁ puʁtˈɑ̃/","zh":"为了活下去，为了自由，可是……","en":"To be able to live, to be free, and yet…","note":"推定修订"},{"id":"la-dame-aux-camelias-05-023","lineIndex":15,"sourceLineIndex":15,"speaker":"","original":"Plus que tous les livres.","ipa":"/plˈy kˈə tˈus lˈe- lˈivʁ/","zh":"胜过所有书卷。","en":"More than all the books.","note":"推定修订"},{"id":"la-dame-aux-camelias-05-024","lineIndex":16,"sourceLineIndex":16,"speaker":"","original":"Et bien plus que de devoir bien se tenir.","ipa":"/ˈe bjˈɛ̃ plˈy kˈə dˈə- dəvwˈaʁ bjˈɛ̃ sˈə- tənˈiʁ/","zh":"也远胜于不得不举止得体。","en":"And far more than having to behave properly.","note":"推定修订"},{"id":"la-dame-aux-camelias-05-025","lineIndex":17,"sourceLineIndex":17,"speaker":"","original":"On vit la vérité dans l’ébriété.","ipa":"/ˈɔ̃ vˈi lˈa- veʁitˈe dˈɑ̃ lebʁietˈe/","zh":"我们在醉意之中体验真实。","en":"We live the truth in a drunken haze.","note":"推定修订"},{"id":"la-dame-aux-camelias-05-026","lineIndex":18,"sourceLineIndex":18,"speaker":"","original":"Comme une bouteille à la mer que l’on aurait jetée.","ipa":"/kˈɔm ˈyn butˈɛj ˈa lˈa- mˈɛʁ kˈə lˈɔ̃ oʁˈɛ ʒətˈe/","zh":"像一只被抛入海中的漂流瓶。","en":"Like a message in a bottle one might have thrown into the sea.","note":"推定修订"},{"id":"la-dame-aux-camelias-05-027","lineIndex":19,"sourceLineIndex":19,"speaker":"","original":"L’âme espère dans son sommeil trouver la liberté, un nouveau chemin qui puisse enfin le mener loin de toute critique, dans un rêve éthylique.","ipa":"/lˈaːm ɛspˈɛʁ dˈɑ̃ sˈɔ̃ sɔmˈɛj tʁuvˈe lˈa- libɛʁtˈe ˈœ̃ nuvˈo ʃəmˈɛ̃ kˈi pyˈis ɑ̃fˈɛ̃ lˈə- mənˈe lwˈɛ̃ dˈə- tˈut kʁitˈik dˈɑ̃ ˈœ̃ ʁˈɛv ɪθɪlˈiːk/","zh":"灵魂在沉睡中盼望找到自由：一条最终能引领他远离一切指责、走入醉梦的新路。","en":"In its sleep, the soul hopes to find freedom: a new path that might at last lead him far from all criticism, into a drunken dream.","note":"推定修订"},{"id":"la-dame-aux-camelias-05-030","lineIndex":20,"sourceLineIndex":20,"speaker":"","original":"Ivre d’être aimée.","ipa":"/ˈivʁ dˈɛtʁ ɛmˈe/","zh":"沉醉于被爱的感觉。","en":"Intoxicated by being loved.","note":"推定修订"},{"id":"la-dame-aux-camelias-05-031","lineIndex":21,"sourceLineIndex":21,"speaker":"","original":"Obligée de sourire.","ipa":"/ɔbliʒˈe dˈə- suʁˈiʁ/","zh":"被迫微笑。","en":"Forced to smile.","note":"推定修订"},{"id":"la-dame-aux-camelias-05-032","lineIndex":22,"sourceLineIndex":22,"speaker":"","original":"Mon cœur s’améliore.","ipa":"/mˈɔ̃ kˈœʁ sameljˈɔʁ/","zh":"我的心正在好转。","en":"My heart is getting better.","note":"推定修订"},{"id":"la-dame-aux-camelias-05-033","lineIndex":23,"sourceLineIndex":23,"speaker":"","original":"Aux délivrances…","ipa":"/ˈo delivʁˈɑ̃s/","zh":"走向解脱……","en":"To deliverances…","note":"推定修订"},{"id":"la-dame-aux-camelias-05-034","lineIndex":24,"sourceLineIndex":24,"speaker":"","original":"Pour pouvoir vivre, être libre…","ipa":"/pˈuʁ puvwˈaʁ vˈivʁ ˈɛtʁ lˈibʁ/","zh":"为了活下去，为了自由……","en":"To be able to live, to be free…","note":"推定修订"},{"id":"la-dame-aux-camelias-05-035","lineIndex":25,"sourceLineIndex":25,"speaker":"","original":"Jusque tout est libre…","ipa":"/ʒˈysk tˈu ˈɛ lˈibʁ/","zh":"直到一切都自由……","en":"Until everything is free…","note":"推定修订"},{"id":"la-dame-aux-camelias-05-036","lineIndex":26,"sourceLineIndex":26,"speaker":"","original":"Et bien plus que de devoir bien se tenir.","ipa":"/ˈe bjˈɛ̃ plˈy kˈə dˈə- dəvwˈaʁ bjˈɛ̃ sˈə- tənˈiʁ/","zh":"也远胜于不得不举止得体。","en":"And far more than having to behave properly.","note":"推定修订"},{"id":"la-dame-aux-camelias-05-037","lineIndex":27,"sourceLineIndex":27,"speaker":"","original":"Dans ce monde qui me noie déjà.","ipa":"/dˈɑ̃ sˈə- mˈɔ̃d kˈi mˈə- nwˈa deʒˈa/","zh":"在这个早已将我淹没的世界里。","en":"In this world that is already drowning me.","note":"推定修订"},{"id":"la-dame-aux-camelias-05-038","lineIndex":28,"sourceLineIndex":28,"speaker":"","original":"Quand vais-je ressentir au moins une seule fois…","ipa":"/kˈɑ̃ vˈɛʒ ʁəsɑ̃tˈiʁ ˈo mwˈɛ̃ ˈyn sˈœl fwˈa/","zh":"我何时才能至少有一次感受到……","en":"When will I feel, at least once…","note":"推定修订"},{"id":"la-dame-aux-camelias-05-039","lineIndex":29,"sourceLineIndex":29,"speaker":"","original":"Tout au fond de moi…","ipa":"/tˈu ˈo fˈɔ̃ dˈə- mwˈa/","zh":"在我内心深处……","en":"Deep inside me…","note":"推定修订"},{"id":"la-dame-aux-camelias-05-040","lineIndex":30,"sourceLineIndex":30,"speaker":"","original":"Mon cœur qui bat.","ipa":"/mˈɔ̃ kˈœʁ kˈi bˈa/","zh":"我那颗跳动的心。","en":"My heart beating.","note":"推定修订"}],"sourceOrder":5,"displayOrder":5},{"order":6,"id":"06-oh-paris","title":"Oh Paris","titleZh":"噢，巴黎","lines":[{"id":"la-dame-aux-camelias-06-039","lineIndex":1,"sourceLineIndex":1,"speaker":"","original":"Sous les toits de zinc, les pigeons bavardaient.","ipa":"/sˈu lˈe- twˈa dˈə- zˈɛ̃ɡ lˈe- piʒˈɔ̃ bavaʁdˈɛ/","zh":"在锌皮屋顶下，鸽子叽叽喳喳。","en":"Beneath the zinc rooftops, the pigeons chatted.","note":"推定修订"},{"id":"la-dame-aux-camelias-06-040","lineIndex":2,"sourceLineIndex":2,"speaker":"","original":"Des nouvelles de Balzac, d’autres à propos de monnaie.","ipa":"/dˈe- nuvˈɛl dˈə- balzˈak dˈotʁ ˈa pʁopˈo dˈə- mɔnˈɛ/","zh":"有人谈巴尔扎克，也有人谈钱。","en":"News of Balzac, and other talk about money.","note":"推定修订"},{"id":"la-dame-aux-camelias-06-041","lineIndex":3,"sourceLineIndex":3,"speaker":"","original":"Sous les boulevards, il n’y avait pas de vélo partout.","ipa":"/sˈu lˈe- bulvˈaʁ ˈil nˈi avˈɛ pˈa dˈə- velˈo paʁtˈu/","zh":"在林荫大道下，自行车还没有到处可见。","en":"Beneath the boulevards, bicycles were not everywhere.","note":"推定修订"},{"id":"la-dame-aux-camelias-06-042","lineIndex":4,"sourceLineIndex":4,"speaker":"","original":"Des trottoirs encombrés par des snacks de tofu.","ipa":"/dˈe- tʁɔtwˈaʁ ɑ̃kɔ̃bʁˈe pˈaʁ dˈe- snˈak dˈə- tofˈy/","zh":"人行道上挤满了豆腐小吃。","en":"Sidewalks crowded with tofu snacks.","note":"推定修订"},{"id":"la-dame-aux-camelias-06-005","lineIndex":5,"sourceLineIndex":5,"speaker":"","original":"À l’époque, le Moulin Rouge rayonnait pour tous les passants.","ipa":"/ˈa lepˈok lˈə- mulˈɛ̃ ʁˈuʒ ʁɛjɔnˈɛ pˈuʁ tˈus lˈe- pasˈɑ̃/","zh":"那时，红磨坊在每个路人眼中都熠熠生辉。","en":"Back then, the Moulin Rouge shone for every passerby.","note":"推定修订"},{"id":"la-dame-aux-camelias-06-006","lineIndex":6,"sourceLineIndex":6,"speaker":"","original":"Tous les grands cabarets, dans la nuit, s’affichaient fiers comme des paons.","ipa":"/tˈus lˈe- ɡʁˈɑ̃ kabaʁˈɛ dˈɑ̃ lˈa- nyˈi safiʃˈɛ fjˈɛʁ kˈɔm dˈe- pˈɑ̃/","zh":"夜色中，所有大歌舞厅都像孔雀般骄傲地亮相。","en":"All the grand cabarets proudly displayed themselves at night, like peacocks.","note":"推定修订"},{"id":"la-dame-aux-camelias-06-043","lineIndex":7,"sourceLineIndex":7,"speaker":"","original":"De la Seine jusqu’au Louvre, aujourd’hui, tout est pareil ou presque sous les pluies de selfies. Y a des fils qui défilent à Paris.","ipa":"/dˈə- lˈa- sˈɛn ʒˈysko lˈuvʁ oʒuʁdyˈi tˈu ˈɛ paʁˈɛj ˈu pʁˈɛskə sˈu lˈe- plyˈi dˈə- sɛlfˈi iɡʁˈɛk ˈa dˈe- fˈil kˈi defˈil ˈa paʁˈi/","zh":"从塞纳河到卢浮宫，如今一切几乎未变，只是自拍如雨。人潮排成队伍，穿行在巴黎。","en":"From the Seine to the Louvre, today everything is much the same, beneath showers of selfies. Lines stream through Paris.","note":"推定修订"},{"id":"la-dame-aux-camelias-06-044","lineIndex":8,"sourceLineIndex":8,"speaker":"","original":"Oh Paris !","ipa":"/ˈɔ paʁˈi/","zh":"哦，巴黎！","en":"Oh Paris!","note":"推定修订"},{"id":"la-dame-aux-camelias-06-045","lineIndex":9,"sourceLineIndex":9,"speaker":"","original":"D’hier et d’aujourd’hui, le même cirque, c’est Paris.","ipa":"/djˈɛʁ ˈe dˈɔːdʒədhjˌuːi lˈə- mˈɛm sˈiʁk sˈɛ paʁˈi/","zh":"无论昨日还是今日，巴黎都是同一场马戏。","en":"Yesterday and today, it is the same circus: Paris.","note":"推定修订"},{"id":"la-dame-aux-camelias-06-046","lineIndex":10,"sourceLineIndex":10,"speaker":"","original":"Des baguettes et des artistes très excentriques, de Montmartre jusqu’aux Champs-Élysées.","ipa":"/dˈe- baɡˈɛt ˈe dˈe- aʁtˈist tʁˈɛ ɛksɑ̃tʁˈik dˈə- mɔ̃mˈaʁtʁ ʒˈysko ʃˈɑ̃elizˈe/","zh":"法棍与古怪不羁的艺人，从蒙马特一路到香榭丽舍。","en":"Baguettes and wildly eccentric artists, from Montmartre to the Champs-Élysées.","note":"推定修订"},{"id":"la-dame-aux-camelias-06-047","lineIndex":11,"sourceLineIndex":11,"speaker":"","original":"Contre un coup passé, pour s’amuser.","ipa":"/kˈɔ̃tʁ ˈœ̃ kˈu pasˈe pˈuʁ samyzˈe/","zh":"为了消遣，抵挡一次过去的打击。","en":"Against a past blow, just for fun.","note":"推定修订"},{"id":"la-dame-aux-camelias-06-048","lineIndex":12,"sourceLineIndex":12,"speaker":"","original":"Mais la vie change sous nos doigts, le temps file si vite.","ipa":"/mˈɛ lˈa- vˈi ʃˈɑ̃ʒ sˈu nˈo dwˈa lˈə- tˈɑ̃ fˈil sˈi vˈit/","zh":"可生活在指尖流转，时光飞逝。","en":"But life changes beneath our fingers; time flies so fast.","note":"推定修订"},{"id":"la-dame-aux-camelias-06-016","lineIndex":13,"sourceLineIndex":13,"speaker":"","original":"Les souvenirs se mélangent au désir.","ipa":"/lˈe- suvnˈiʁ sˈə- melˈɑ̃ʒ ˈo dezˈiʁ/","zh":"回忆与欲望交织。","en":"Memories mingle with desire.","note":"推定修订"},{"id":"la-dame-aux-camelias-06-049","lineIndex":14,"sourceLineIndex":14,"speaker":"","original":"Paris éternel en devenir.","ipa":"/paʁˈi etɛʁnˈɛl ˈɑ̃ dəvnˈiʁ/","zh":"巴黎，永恒而不断新生。","en":"Paris, eternal and ever becoming.","note":"推定修订"},{"id":"la-dame-aux-camelias-06-018","lineIndex":15,"sourceLineIndex":15,"speaker":"","original":"Même si le temps te transforme encore.","ipa":"/mˈɛm sˈi lˈə- tˈɑ̃ tˈə- tʁɑ̃sfˈɔʁm ɑ̃kˈɔʁ/","zh":"即使时光仍在改变你。","en":"Even as time transforms you again.","note":"推定修订"},{"id":"la-dame-aux-camelias-06-050","lineIndex":16,"sourceLineIndex":16,"speaker":"","original":"Ton charme reste conforme.","ipa":"/tˈɔ̃ ʃˈaʁm ʁˈɛst kɔ̃fˈɔʁm/","zh":"你的魅力依旧如故。","en":"Your charm remains true to form.","note":"推定修订"},{"id":"la-dame-aux-camelias-06-051","lineIndex":17,"sourceLineIndex":17,"speaker":"","original":"Oh là là ! De la bohème à l’ère du scroll.","ipa":"/ˈɔ lˈa lˈa dˈə- lˈa- boˈɛm ˈa lˈɛʁ dˈy- skɹˈəʊl/","zh":"哦啦啦！从波希米亚时代走到刷屏年代。","en":"Oh là là! From bohemia to the age of scrolling.","note":"推定修订"},{"id":"la-dame-aux-camelias-06-052","lineIndex":18,"sourceLineIndex":18,"speaker":"","original":"Paris, tu es là. Tu changes, mais restes drôle.","ipa":"/paʁˈi tˈy ˈɛ lˈa tˈy ʃˈɑ̃ʒ mˈɛ ʁˈɛst dʁˈoːl/","zh":"巴黎，你就在这里。你不断变化，却依旧有趣。","en":"Paris, you are here. You change, yet remain amusing.","note":"推定修订"},{"id":"la-dame-aux-camelias-06-023","lineIndex":19,"sourceLineIndex":19,"speaker":"","original":"Oh, oh, oh !","ipa":"/ˈɔ ˈɔ ˈɔ/","zh":"哦，哦，哦！","en":"Oh, oh, oh!","note":"推定修订"},{"id":"la-dame-aux-camelias-06-053","lineIndex":20,"sourceLineIndex":20,"speaker":"","original":"Mais la ville change sous nos doigts, le temps file si vite.","ipa":"/mˈɛ lˈa- vˈil ʃˈɑ̃ʒ sˈu nˈo dwˈa lˈə- tˈɑ̃ fˈil sˈi vˈit/","zh":"可城市在指尖流转，时光飞逝。","en":"But the city changes beneath our fingers; time flies so fast.","note":"推定修订"},{"id":"la-dame-aux-camelias-06-025","lineIndex":21,"sourceLineIndex":21,"speaker":"","original":"Les souvenirs se mélangent au désir.","ipa":"/lˈe- suvnˈiʁ sˈə- melˈɑ̃ʒ ˈo dezˈiʁ/","zh":"回忆与欲望交织。","en":"Memories mingle with desire.","note":"推定修订"},{"id":"la-dame-aux-camelias-06-026","lineIndex":22,"sourceLineIndex":22,"speaker":"","original":"Que ce soit dans le bronze ou bien l’or.","ipa":"/kˈə sˈə- swˈa dˈɑ̃ lˈə- bʁˈɔ̃z ˈu bjˈɛ̃ lˈɔʁ/","zh":"无论青铜还是黄金。","en":"Whether in bronze or in gold.","note":"推定修订"},{"id":"la-dame-aux-camelias-06-027","lineIndex":23,"sourceLineIndex":23,"speaker":"","original":"L’homme ne change pas en fonction du décor.","ipa":"/lˈɔm nˈə- ʃˈɑ̃ʒ pˈa ˈɑ̃ fɔ̃ksjˈɔ̃ dˈy- dekˈɔʁ/","zh":"人不会因环境改变本性。","en":"A man does not change with the scenery.","note":"推定修订"},{"id":"la-dame-aux-camelias-06-054","lineIndex":24,"sourceLineIndex":24,"speaker":"","original":"Même des fausses ou d’autres normes.","ipa":"/mˈɛm dˈe- fˈos ˈu dˈotʁ nˈɔʁm/","zh":"即便是虚假的，或是其他规范。","en":"Even false ones or other norms.","note":"推定修订"},{"id":"la-dame-aux-camelias-06-055","lineIndex":25,"sourceLineIndex":25,"speaker":"","original":"Oh là là !","ipa":"/ˈɔ lˈa lˈa/","zh":"哦啦啦！","en":"Oh là là!","note":"推定修订"},{"id":"la-dame-aux-camelias-06-029","lineIndex":26,"sourceLineIndex":26,"speaker":"","original":"Dans le vieux Paris, on savait encore dire bonjour.","ipa":"/dˈɑ̃ lˈə- vjˈø paʁˈi ˈɔ̃ savˈɛ ɑ̃kˈɔʁ dˈiʁ bɔ̃ʒˈuʁ/","zh":"在旧巴黎，人们还懂得问候。","en":"In old Paris, people still knew how to say hello.","note":"推定修订"},{"id":"la-dame-aux-camelias-06-056","lineIndex":27,"sourceLineIndex":27,"speaker":"","original":"Des messieurs en redingote en plein jour.","ipa":"/dˈe- mesjˈø ˈɑ̃ ʁədɛ̃ɡˈɔt ˈɑ̃ plˈɛ̃ ʒˈuʁ/","zh":"大白天里，绅士们身穿燕尾服。","en":"Gentlemen in frock coats in broad daylight.","note":"推定修订"},{"id":"la-dame-aux-camelias-06-057","lineIndex":28,"sourceLineIndex":28,"speaker":"","original":"La galanterie aujourd’hui, c’est un swipe de la droite vers la gauche.","ipa":"/lˈa- ɡalɑ̃tʁˈi oʒuʁdyˈi sˈɛ ˈœ̃ swˈip dˈə- lˈa- dʁwˈat vˈɛʁ lˈa- ɡˈoʃ/","zh":"如今的殷勤，只是从右向左滑一下。","en":"Today, courtship is a swipe from right to left.","note":"推定修订"},{"id":"la-dame-aux-camelias-06-058","lineIndex":29,"sourceLineIndex":29,"speaker":"","original":"C’est l’heure de la débauche.","ipa":"/sˈɛ lˈœʁ dˈə- lˈa- debˈoʃ/","zh":"纵情放浪的时刻到了。","en":"It is the hour of debauchery.","note":"推定修订"},{"id":"la-dame-aux-camelias-06-059","lineIndex":30,"sourceLineIndex":30,"speaker":"","original":"Oh là là ! À Paris, d’hier et d’aujourd’hui, le même succès, Paris !","ipa":"/ˈɔ lˈa lˈa ˈa paʁˈi djˈɛʁ ˈe dˈɔːdʒədhjˌuːi lˈə- mˈɛm syksˈɛ paʁˈi/","zh":"哦啦啦！在巴黎，无论昨日今日，成功的仍是巴黎！","en":"Oh là là! In Paris, yesterday and today, the same success: Paris!","note":"推定修订"},{"id":"la-dame-aux-camelias-06-060","lineIndex":31,"sourceLineIndex":31,"speaker":"","original":"Des baguettes et des artistes très excentriques, de Montmartre jusqu’aux Champs-Élysées.","ipa":"/dˈe- baɡˈɛt ˈe dˈe- aʁtˈist tʁˈɛ ɛksɑ̃tʁˈik dˈə- mɔ̃mˈaʁtʁ ʒˈysko ʃˈɑ̃elizˈe/","zh":"法棍与古怪不羁的艺人，从蒙马特一路到香榭丽舍。","en":"Baguettes and wildly eccentric artists, from Montmartre to the Champs-Élysées.","note":"推定修订"},{"id":"la-dame-aux-camelias-06-061","lineIndex":32,"sourceLineIndex":32,"speaker":"","original":"Autant qu’au passé.","ipa":"/otˈɑ̃ kˈo pasˈe/","zh":"一如从前。","en":"As much as in the past.","note":"推定修订"},{"id":"la-dame-aux-camelias-06-038","lineIndex":33,"sourceLineIndex":33,"speaker":"","original":"L’homme ne change pas en fonction du décor.","ipa":"/lˈɔm nˈə- ʃˈɑ̃ʒ pˈa ˈɑ̃ fɔ̃ksjˈɔ̃ dˈy- dekˈɔʁ/","zh":"人不会因环境改变本性。","en":"A man does not change with the scenery.","note":"推定修订"}],"sourceOrder":6,"displayOrder":6},{"order":7,"id":"07-fuis-moi-suis-moi","title":"Fuis-moi suis-moi","titleZh":"逃离我，追逐我","lines":[{"id":"la-dame-aux-camelias-07-077","lineIndex":1,"sourceLineIndex":1,"speaker":"","original":"Pure logique, tu veux qu’un homme s’intéresse.","ipa":"/pˈyʁ loʒˈik tˈy vˈø kˈœ̃ ˈɔm sɛ̃teʁˈɛs/","zh":"纯粹的逻辑：你希望一个男人对你感兴趣。","en":"Pure logic: you want a man to take an interest.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-078","lineIndex":2,"sourceLineIndex":2,"speaker":"","original":"Ignore-le, il te tend sa laisse.","ipa":"/injˈɔʁlˈə- ˈil tˈə- tˈɑ̃ sˈa- lˈɛs/","zh":"不理他，他就会把牵绳交到你手里。","en":"Ignore him, and he hands you his leash.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-079","lineIndex":3,"sourceLineIndex":3,"speaker":"","original":"Classique, s’il sent que tu files entre ses doigts, comme par magie, il sera tout à toi.","ipa":"/klasˈik sˈil sˈɑ̃ kˈə tˈy fˈil ˈɑ̃tʁ sˈe- dwˈa kˈɔm pˈaʁ maʒˈi ˈil səʁˈa tˈu ˈa twˈa/","zh":"经典套路：只要他感觉你正从指间溜走，他就会魔法般地完全属于你。","en":"Classic: if he feels you slipping through his fingers, as if by magic, he’ll be all yours.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-080","lineIndex":4,"sourceLineIndex":4,"speaker":"","original":"Pour moi, l’amour, c’est de l’argent.","ipa":"/pˈuʁ mwˈa lamˈuʁ sˈɛ dˈə- laʁʒˈɑ̃/","zh":"对我来说，爱情就是金钱。","en":"To me, love is money.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-081","lineIndex":5,"sourceLineIndex":5,"speaker":"","original":"Mes sentiments sont comme les diamants.","ipa":"/mˈe- sɑ̃timˈɑ̃ sˈɔ̃ kˈɔm lˈe- djamˈɑ̃/","zh":"我的感情如钻石般珍贵。","en":"My feelings are like diamonds.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-082","lineIndex":6,"sourceLineIndex":6,"speaker":"","original":"Une romance imaginaire.","ipa":"/ˈyn ʁomˈɑ̃s imaʒinˈɛʁ/","zh":"一段虚构的恋情。","en":"An imaginary romance.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-083","lineIndex":7,"sourceLineIndex":7,"speaker":"","original":"Pour elle, je peux bien leur plaire.","ipa":"/pˈuʁ ˈɛl ʒˈə- pˈø bjˈɛ̃ lˈœʁ plˈɛʁ/","zh":"为了她，我当然能讨他们喜欢。","en":"For her, I can certainly please them.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-034","lineIndex":8,"sourceLineIndex":8,"speaker":"","original":"Fuis-moi, suis-moi, il en est de l’amour.","ipa":"/fyˈimwˈa syˈimwˈa ˈil ˈɑ̃ ˈɛ dˈə- lamˈuʁ/","zh":"逃离我，追逐我，爱情就是如此。","en":"Run from me, follow me; that is how love goes.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-035","lineIndex":9,"sourceLineIndex":9,"speaker":"","original":"Quand on part, c’est la queue du sacre.","ipa":"/kˈɑ̃ ˈɔ̃ pˈaʁ sˈɛ lˈa- kˈø dˈy- sˈakʁ/","zh":"当人离开时，这便是加冕仪式的尾声。","en":"When one leaves, it is the tail of the coronation.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-036","lineIndex":10,"sourceLineIndex":10,"speaker":"","original":"On ne se lasse pas de cette danse-là.","ipa":"/ˈɔ̃ nˈə- sˈə- lˈas pˈa dˈə- sˈɛt dˈɑ̃slˈa/","zh":"这场舞，我们总也跳不厌。","en":"We never tire of this dance.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-037","lineIndex":11,"sourceLineIndex":11,"speaker":"","original":"Quand il s’accroche, c’est là qu’on s’en va.","ipa":"/kˈɑ̃ ˈil sakʁˈɔʃ sˈɛ lˈa kˈɔ̃ sˈɑ̃ vˈa/","zh":"当他紧抓不放，我们便不在乎。","en":"When he clings on, that is when we do not care.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-038","lineIndex":12,"sourceLineIndex":12,"speaker":"","original":"L’Oscar en main, ma passion devient lassitude.","ipa":"/lɔskˈaʁ ˈɑ̃ mˈɛ̃ mˈa- pasjˈɔ̃ dəvjˈɛ̃ lasitˈyd/","zh":"奥斯卡奖在手，我的热情变成倦怠。","en":"Oscar in hand, my passion turns to weariness.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-039","lineIndex":13,"sourceLineIndex":13,"speaker":"","original":"Je joue la comédie par habitude.","ipa":"/ʒˈə- ʒˈu lˈa- komedˈi pˈaʁ abitˈyd/","zh":"我习惯性地演戏。","en":"I act out of habit.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-040","lineIndex":14,"sourceLineIndex":14,"speaker":"","original":"Je vous explique pourquoi eux nous sommes inaccessibles.","ipa":"/ʒˈə- vˈu ɛksplˈik puʁkwˈa ˈø nˈu sˈɔm inaksɛsˈibl/","zh":"我来解释为什么我们对他们遥不可及。","en":"I’ll explain why we are inaccessible to them.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-041","lineIndex":15,"sourceLineIndex":15,"speaker":"","original":"Leur défi pour nous, ils feront leur possible.","ipa":"/lˈœʁ defˈi pˈuʁ nˈu ˈil fəʁˈɔ̃ lˈœʁ pɔsˈibl/","zh":"他们向我们发起挑战，会尽其所能。","en":"Their challenge for us: they will do what they can.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-042","lineIndex":16,"sourceLineIndex":16,"speaker":"","original":"Aimer, c’est pour ceux qui veulent y croire.","ipa":"/ɛmˈe sˈɛ pˈuʁ sˈø kˈi vˈœl iɡʁˈɛk kʁwˈaʁ/","zh":"爱情属于那些愿意相信它的人。","en":"Love is for those who want to believe in it.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-043","lineIndex":17,"sourceLineIndex":17,"speaker":"","original":"Moi, je vise le luxe et le pouvoir.","ipa":"/mwˈa ʒˈə- vˈiz lˈə- lˈyks ˈe lˈə- puvwˈaʁ/","zh":"我追求奢华与权力。","en":"I aim for luxury and power.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-044","lineIndex":18,"sourceLineIndex":18,"speaker":"","original":"Le cœur est trop incertain.","ipa":"/lˈə- kˈœʁ ˈɛ tʁˈo ɛ̃sɛʁtˈɛ̃/","zh":"人心太难捉摸。","en":"The heart is too uncertain.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-045","lineIndex":19,"sourceLineIndex":19,"speaker":"","original":"Moi, je veux l’or, rien de plus, rien de moins.","ipa":"/mwˈa ʒˈə- vˈø lˈɔʁ ʁiˈɛ̃ dˈə- plˈy ʁiˈɛ̃ dˈə- mwˈɛ̃/","zh":"我只要黄金，不多也不少。","en":"I want gold, nothing more, nothing less.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-046","lineIndex":20,"sourceLineIndex":20,"speaker":"","original":"Fuis-moi, suis-moi, il en est de l’amour.","ipa":"/fyˈimwˈa syˈimwˈa ˈil ˈɑ̃ ˈɛ dˈə- lamˈuʁ/","zh":"逃离我，追逐我，爱情就是如此。","en":"Run from me, follow me; that is how love goes.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-047","lineIndex":21,"sourceLineIndex":21,"speaker":"","original":"Quand on part, c’est la queue du sacre.","ipa":"/kˈɑ̃ ˈɔ̃ pˈaʁ sˈɛ lˈa- kˈø dˈy- sˈakʁ/","zh":"当人离开时，这便是加冕仪式的尾声。","en":"When one leaves, it is the tail of the coronation.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-048","lineIndex":22,"sourceLineIndex":22,"speaker":"","original":"On ne se lasse pas de cette danse-là.","ipa":"/ˈɔ̃ nˈə- sˈə- lˈas pˈa dˈə- sˈɛt dˈɑ̃slˈa/","zh":"这场舞，我们总也跳不厌。","en":"We never tire of this dance.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-049","lineIndex":23,"sourceLineIndex":23,"speaker":"","original":"Quand il s’accroche, c’est là qu’on s’en va.","ipa":"/kˈɑ̃ ˈil sakʁˈɔʃ sˈɛ lˈa kˈɔ̃ sˈɑ̃ vˈa/","zh":"当他紧抓不放，我们便在那时离开。","en":"When he clings on, that is when we leave.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-050","lineIndex":24,"sourceLineIndex":24,"speaker":"","original":"Tu penses que j’ai le cœur froissé.","ipa":"/tˈy pˈɑ̃s kˈə ʒˈe lˈə- kˈœʁ fʁwasˈe/","zh":"你以为我的心受了伤。","en":"You think my heart is bruised.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-051","lineIndex":25,"sourceLineIndex":25,"speaker":"","original":"Moi, ce que je veux, c’est être couronné.","ipa":"/mwˈa sˈə- kˈə ʒˈə- vˈø sˈɛ ˈɛtʁ kuʁɔnˈe/","zh":"我想要的，是加冕。","en":"What I want is to be crowned.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-052","lineIndex":26,"sourceLineIndex":26,"speaker":"","original":"Voir sur eux un verre de sourire.","ipa":"/vwˈaʁ sˈyʁ ˈø ˈœ̃ vˈɛʁ dˈə- suʁˈiʁ/","zh":"看见他们身上有一杯微笑。","en":"To see on them a glass of smile.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-053","lineIndex":27,"sourceLineIndex":27,"speaker":"","original":"Quand ils s’achètent mes soupirs.","ipa":"/kˈɑ̃ ˈil saʃˈɛt mˈe- supˈiʁ/","zh":"当他们买下我的叹息。","en":"When they buy my sighs.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-054","lineIndex":28,"sourceLineIndex":28,"speaker":"","original":"Aimer, c’est juste une transaction.","ipa":"/ɛmˈe sˈɛ ʒˈyst ˈyn tʁɑ̃zaksjˈɔ̃/","zh":"爱情不过是一场交易。","en":"Love is just a transaction.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-055","lineIndex":29,"sourceLineIndex":29,"speaker":"","original":"Moi, je manipule leur mental.","ipa":"/mwˈa ʒˈə- manipˈyl lˈœʁ mɑ̃tˈal/","zh":"我操纵他们的心智。","en":"I manipulate their minds.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-056","lineIndex":30,"sourceLineIndex":30,"speaker":"","original":"L’amour, ce n’est qu’une distraction.","ipa":"/lamˈuʁ sˈə- nˈɛ kˈyn distʁaksjˈɔ̃/","zh":"爱情不过是消遣。","en":"Love is nothing but a distraction.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-057","lineIndex":31,"sourceLineIndex":31,"speaker":"","original":"Je les encense, je les sers.","ipa":"/ʒˈə- lˈe- ɑ̃sˈɑ̃s ʒˈə- lˈe- sˈɛʁ/","zh":"我对他们极尽赞美，为他们效劳。","en":"I praise them to the skies; I serve them.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-058","lineIndex":32,"sourceLineIndex":32,"speaker":"","original":"Pourquoi miser dans l’émotion ?","ipa":"/puʁkwˈa mizˈe dˈɑ̃ lemosjˈɔ̃/","zh":"为什么要把赌注押在情感上？","en":"Why wager on emotion?","note":"推定修订"},{"id":"la-dame-aux-camelias-07-059","lineIndex":33,"sourceLineIndex":33,"speaker":"","original":"Pour mieux les briser, c’est fatal.","ipa":"/pˈuʁ mjˈø lˈe- bʁizˈe sˈɛ fatˈal/","zh":"为了更彻底地击碎他们，这注定如此。","en":"To break them better; it is fatal.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-060","lineIndex":34,"sourceLineIndex":34,"speaker":"","original":"Quand l’argent offre satisfaction.","ipa":"/kˈɑ̃ laʁʒˈɑ̃ ˈɔfʁ satisfaksjˈɔ̃/","zh":"当金钱带来满足。","en":"When money offers satisfaction.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-061","lineIndex":35,"sourceLineIndex":35,"speaker":"","original":"Un ego, ça détruit aussi.","ipa":"/ˈœ̃ eɡˈo sˈa detʁyˈi osˈi/","zh":"自我也会摧毁一切。","en":"An ego destroys too.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-062","lineIndex":36,"sourceLineIndex":36,"speaker":"","original":"Le content, c’est ma vocation.","ipa":"/lˈə- kɔ̃tˈɑ̃ sˈɛ mˈa- vokasjˈɔ̃/","zh":"满足是我的使命。","en":"Contentment is my calling.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-063","lineIndex":37,"sourceLineIndex":37,"speaker":"","original":"Je flatte le roi, je crée le génie.","ipa":"/ʒˈə- flˈat lˈə- ʁwˈa ʒˈə- kʁˈe lˈə- ʒenˈi/","zh":"我奉承国王，我创造天才。","en":"I flatter the king; I create genius.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-064","lineIndex":38,"sourceLineIndex":38,"speaker":"","original":"Le cœur, c’est son nom et l’art.","ipa":"/lˈə- kˈœʁ sˈɛ sˈɔ̃ nˈɔ̃ ˈe lˈaʁ/","zh":"心，是它的名字与艺术。","en":"The heart is its name and art.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-065","lineIndex":39,"sourceLineIndex":39,"speaker":"","original":"Et puis je le rabaisse, je le crée.","ipa":"/ˈe pyˈi ʒˈə- lˈə- ʁabˈɛs ʒˈə- lˈə- kʁˈe/","zh":"然后我贬低它，又创造它。","en":"And then I put it down; I create it.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-066","lineIndex":40,"sourceLineIndex":40,"speaker":"","original":"L’amour fait les comptes bien.","ipa":"/lamˈuʁ fˈɛ lˈe- kˈɔ̃t bjˈɛ̃/","zh":"爱情把账算得清楚。","en":"Love does the accounting well.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-067","lineIndex":41,"sourceLineIndex":41,"speaker":"","original":"La fierté s’écroule en un brin de lilas.","ipa":"/lˈa- fjɛʁtˈe sekʁˈul ˈɑ̃ ˈœ̃ bʁˈɛ̃ dˈə- lilˈa/","zh":"骄傲在一枝丁香中崩塌。","en":"Pride crumbles in a sprig of lilac.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-068","lineIndex":42,"sourceLineIndex":42,"speaker":"","original":"Mais là, je sais la seule relation.","ipa":"/mˈɛ lˈa ʒˈə- sˈɛ lˈa- sˈœl ʁəlasjˈɔ̃/","zh":"但在那里，我知道唯一的关系。","en":"But there, I know the only relationship.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-069","lineIndex":43,"sourceLineIndex":43,"speaker":"","original":"Mon emblème, c’est un portefeuille.","ipa":"/mˈɔ̃ ɑ̃blˈɛm sˈɛ ˈœ̃ pɔʁtəfˈœj/","zh":"我的标志，就是一只钱夹。","en":"My emblem is a wallet.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-070","lineIndex":44,"sourceLineIndex":44,"speaker":"","original":"Le cœur est trop incertain.","ipa":"/lˈə- kˈœʁ ˈɛ tʁˈo ɛ̃sɛʁtˈɛ̃/","zh":"人心太难捉摸。","en":"The heart is too uncertain.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-071","lineIndex":45,"sourceLineIndex":45,"speaker":"","original":"On connaît bien le refrain.","ipa":"/ˈɔ̃ kɔnˈɛ bjˈɛ̃ lˈə- ʁəfʁˈɛ̃/","zh":"我们熟知这段副歌。","en":"We know the refrain well.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-006","lineIndex":46,"sourceLineIndex":46,"speaker":"","original":"Fuis-moi, suis-moi.","ipa":"/fyˈimwˈa syˈimwˈa/","zh":"逃离我，追逐我。","en":"Run from me, follow me.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-072","lineIndex":47,"sourceLineIndex":47,"speaker":"","original":"Il en est de l’amour quand on part ; c’est la queue du sacre.","ipa":"/ˈil ˈɑ̃ ˈɛ dˈə- lamˈuʁ kˈɑ̃ ˈɔ̃ pˈaʁ sˈɛ lˈa- kˈø dˈy- sˈakʁ/","zh":"离别时，爱情便是如此；这便是加冕仪式的尾声。","en":"That is how love goes when one leaves; it is the tail of the coronation.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-073","lineIndex":48,"sourceLineIndex":48,"speaker":"","original":"On ne se lasse pas de cette danse-là.","ipa":"/ˈɔ̃ nˈə- sˈə- lˈas pˈa dˈə- sˈɛt dˈɑ̃slˈa/","zh":"这场舞，我们总也跳不厌。","en":"We never tire of this dance.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-010","lineIndex":49,"sourceLineIndex":49,"speaker":"","original":"Quand il s’accroche, c’est là qu’on s’en va.","ipa":"/kˈɑ̃ ˈil sakʁˈɔʃ sˈɛ lˈa kˈɔ̃ sˈɑ̃ vˈa/","zh":"当他紧抓不放，我们便在那时离开。","en":"When he clings on, that is when we leave.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-074","lineIndex":50,"sourceLineIndex":50,"speaker":"","original":"Fuis-moi, suis-moi, il en est de l’amour quand on part.","ipa":"/fyˈimwˈa syˈimwˈa ˈil ˈɑ̃ ˈɛ dˈə- lamˈuʁ kˈɑ̃ ˈɔ̃ pˈaʁ/","zh":"逃离我，追逐我；离别时，爱情便是如此。","en":"Run from me, follow me; that is how love goes when one leaves.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-075","lineIndex":51,"sourceLineIndex":51,"speaker":"","original":"C’est la queue du sacre.","ipa":"/sˈɛ lˈa- kˈø dˈy- sˈakʁ/","zh":"这便是加冕仪式的尾声。","en":"It is the tail of the coronation.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-076","lineIndex":52,"sourceLineIndex":52,"speaker":"","original":"On ne se lasse pas de cette danse-là.","ipa":"/ˈɔ̃ nˈə- sˈə- lˈas pˈa dˈə- sˈɛt dˈɑ̃slˈa/","zh":"这场舞，我们总也跳不厌。","en":"We never tire of this dance.","note":"推定修订"},{"id":"la-dame-aux-camelias-07-023","lineIndex":53,"sourceLineIndex":53,"speaker":"","original":"Quand il s’accroche, c’est là qu’on s’en va.","ipa":"/kˈɑ̃ ˈil sakʁˈɔʃ sˈɛ lˈa kˈɔ̃ sˈɑ̃ vˈa/","zh":"当他紧抓不放，我们便在那时离开。","en":"When he clings on, that is when we leave.","note":"推定修订"}],"sourceOrder":7,"displayOrder":7},{"order":8,"id":"08-l-art-du-planning","title":"L'art du planning","titleZh":"规划的艺术","lines":[{"id":"la-dame-aux-camelias-08-001","lineIndex":1,"sourceLineIndex":1,"speaker":"","original":"L'art du planning.","ipa":"/lˈaʁ dˈy- plˈanɪŋ/","zh":"安排的艺术。","en":"The art of planning.","note":"推定修订"},{"id":"la-dame-aux-camelias-08-002","lineIndex":2,"sourceLineIndex":2,"speaker":"","original":"Mes amis, c'est tout un sport.","ipa":"/mˈe- amˈi sˈɛ tˈu ˈœ̃ spˈɔʁ/","zh":"朋友们，这简直是一项运动。","en":"My friends, it's a whole sport.","note":"推定修订"},{"id":"la-dame-aux-camelias-08-003","lineIndex":3,"sourceLineIndex":3,"speaker":"","original":"Clés qui se bousculent, amants dans le décor.","ipa":"/klˈe kˈi sˈə- buskˈyl amˈɑ̃ dˈɑ̃ lˈə- dekˈɔʁ/","zh":"钥匙挤作一团，情人们纷纷登场。","en":"Keys jostle together, lovers fill the scene.","note":"推定修订"},{"id":"la-dame-aux-camelias-08-004","lineIndex":4,"sourceLineIndex":4,"speaker":"","original":"Marguerite, ma chère, t'as trop de clients.","ipa":"/maʁɡəʁˈit mˈa- ʃˈɛʁ tˈa tʁˈo dˈə- kliˈɑ̃/","zh":"玛格丽特，亲爱的，你的客人太多了。","en":"Marguerite, my dear, you have too many clients.","note":"推定修订"},{"id":"la-dame-aux-camelias-08-005","lineIndex":5,"sourceLineIndex":5,"speaker":"","original":"Ton agenda, c'est le bal des imprudents.","ipa":"/tˈɔ̃ aʒɛ̃dˈa sˈɛ lˈə- bˈal dˈe- ɛ̃pʁydˈɑ̃/","zh":"你的日程表，简直成了莽撞者的舞会。","en":"Your calendar is a ball for the reckless.","note":"推定修订"},{"id":"la-dame-aux-camelias-08-006","lineIndex":6,"sourceLineIndex":6,"speaker":"","original":"Monsieur le baron, doucement, passez vite.","ipa":"/məsjˈø lˈə- baʁˈɔ̃ dusmˈɑ̃ pasˈe vˈit/","zh":"男爵先生，轻点，请快些过去。","en":"Monsieur le Baron, gently now, hurry through.","note":"推定修订"},{"id":"la-dame-aux-camelias-08-007","lineIndex":7,"sourceLineIndex":7,"speaker":"","original":"Vos bottes mouillées, elles glissent, les maudites.","ipa":"/vˈo bˈɔt mujˈe ˈɛl ɡlˈis lˈe- modˈit/","zh":"你那双湿靴子，真该死，滑得很。","en":"Your wet boots, the damn things are slipping.","note":"推定修订"},{"id":"la-dame-aux-camelias-08-008","lineIndex":8,"sourceLineIndex":8,"speaker":"","original":"Une clé par-ci,","ipa":"/ˈyn klˈe paʁsˈi/","zh":"这边一把钥匙，","en":"One key over here,","note":"推定修订"},{"id":"la-dame-aux-camelias-08-009","lineIndex":9,"sourceLineIndex":9,"speaker":"","original":"Une clé par-là, ce couloir, c'est le parcours du combattant.","ipa":"/ˈyn klˈe paʁlˈa sˈə- kulwˈaʁ sˈɛ lˈə- paʁkˈuʁ dˈy- kɔ̃batˈɑ̃/","zh":"那边一把钥匙；这条走廊简直像闯关赛道。","en":"One key over there; this hallway is an obstacle course.","note":"推定修订"},{"id":"la-dame-aux-camelias-08-010","lineIndex":10,"sourceLineIndex":10,"speaker":"","original":"Hélas.","ipa":"/elˈas/","zh":"唉。","en":"Alas.","note":"推定修订"},{"id":"la-dame-aux-camelias-08-011","lineIndex":11,"sourceLineIndex":11,"speaker":"","original":"L'art du planning, c'est tout un cirque.","ipa":"/lˈaʁ dˈy- plˈanɪŋ sˈɛ tˈu ˈœ̃ sˈiʁk/","zh":"安排的艺术，简直是一场马戏。","en":"The art of planning is a whole circus.","note":"推定修订"},{"id":"la-dame-aux-camelias-08-012","lineIndex":12,"sourceLineIndex":12,"speaker":"","original":"Les clés tournent, scénario dramatique.","ipa":"/lˈe- klˈe tˈuʁn senaʁjˈo dʁamatˈik/","zh":"钥匙不停轮转，剧情戏剧化。","en":"The keys turn: a dramatic scenario.","note":"推定修订"},{"id":"la-dame-aux-camelias-08-013","lineIndex":13,"sourceLineIndex":13,"speaker":"","original":"Un amant par porte, autre crise.","ipa":"/ˈœ̃ amˈɑ̃ pˈaʁ pˈɔʁt ˈotʁ kʁˈiz/","zh":"每扇门后一个情人，又一场危机。","en":"One lover per door, another crisis.","note":"推定修订"},{"id":"la-dame-aux-camelias-08-014","lineIndex":14,"sourceLineIndex":14,"speaker":"","original":"Chama et Marguerite, t'as le cœur plein.","ipa":"/ʃamˈa ˈe maʁɡəʁˈit tˈa lˈə- kˈœʁ plˈɛ̃/","zh":"查玛和玛格丽特，你心中满是情意。","en":"Chama and Marguerite, your heart is full.","note":"推定修订"},{"id":"la-dame-aux-camelias-08-015","lineIndex":15,"sourceLineIndex":15,"speaker":"","original":"Aïe, aïe, aïe, aïe, aïe.","ipa":"/ˈaj ˈaj ˈaj ˈaj ˈaj/","zh":"哎哟，哎哟，哎哟，哎哟，哎哟。","en":"Ow, ow, ow, ow, ow.","note":"推定修订"},{"id":"la-dame-aux-camelias-08-016","lineIndex":16,"sourceLineIndex":16,"speaker":"","original":"Le week-end ou la nuit, c'est pour les gros butins.","ipa":"/lˈə- wˈiːkˈɛnd ˈu lˈa- nyˈi sˈɛ pˈuʁ lˈe- ɡʁˈo bytˈɛ̃/","zh":"周末或夜晚，才是赚大钱的时候。","en":"The weekend or the night is for the big scores.","note":"推定修订"},{"id":"la-dame-aux-camelias-08-017","lineIndex":17,"sourceLineIndex":17,"speaker":"","original":"Ceux qui payent le plus cher ont tous les privilèges.","ipa":"/sˈø kˈi pˈɛj lˈə- plˈy ʃˈɛʁ ˈɔ̃ tˈus lˈe- pʁivilˈɛʒ/","zh":"出价最高的人享有所有特权。","en":"Those who pay the most have all the privileges.","note":"推定修订"},{"id":"la-dame-aux-camelias-08-018","lineIndex":18,"sourceLineIndex":18,"speaker":"","original":"Ils offrent les honneurs et les plus beaux décors.","ipa":"/ˈil ˈɔfʁ lˈe- ɔnˈœʁ ˈe lˈe- plˈy bˈo dekˈɔʁ/","zh":"他们献上荣耀与最华美的排场。","en":"They offer honors and the most splendid settings.","note":"推定修订"},{"id":"la-dame-aux-camelias-08-019","lineIndex":19,"sourceLineIndex":19,"speaker":"","original":"On se pousse au portillon, c'est le bazar.","ipa":"/ˈɔ̃ sˈə- pˈus ˈo pɔʁtijˈɔ̃ sˈɛ lˈə- bazˈaʁ/","zh":"大家挤在入口，乱成一团。","en":"Everyone crowds at the gate; it's a madhouse.","note":"推定修订"},{"id":"la-dame-aux-camelias-08-020","lineIndex":20,"sourceLineIndex":20,"speaker":"","original":"L'après-midi, c'est fait pour la petite monnaie.","ipa":"/lapʁˌɛmidˈi sˈɛ fˈɛ pˈuʁ lˈa- pətˈit mɔnˈɛ/","zh":"下午才是赚些小钱的时候。","en":"The afternoon is for the small change.","note":"推定修订"},{"id":"la-dame-aux-camelias-08-021","lineIndex":21,"sourceLineIndex":21,"speaker":"","original":"On discute, on flirte, on passe le temps d'après.","ipa":"/ˈɔ̃ diskˈyt ˈɔ̃ flˈœʁt ˈɔ̃ pˈas lˈə- tˈɑ̃ dapʁˈɛ/","zh":"我们聊天、调情，打发午后的时光。","en":"We talk, we flirt, we pass the afternoon.","note":"推定修订"},{"id":"la-dame-aux-camelias-08-022","lineIndex":22,"sourceLineIndex":22,"speaker":"","original":"Je garde la porte, je contrôle le tarmac.","ipa":"/ʒˈə- ɡˈaʁd lˈa- pˈɔʁt ʒˈə- kɔ̃tʁˈoːl lˈə- taʁmˈak/","zh":"我守着门，掌管这片停机坪。","en":"I guard the door; I control the tarmac.","note":"推定修订"},{"id":"la-dame-aux-camelias-08-023","lineIndex":23,"sourceLineIndex":23,"speaker":"","original":"Mais vos clés, messieurs, c’est le grand micmac.","ipa":"/mˈɛ vˈo klˈe mesjˈø sˈɛ lˈə- ɡʁˈɑ̃ mikmˈak/","zh":"可先生们，你们的钥匙把一切搅成了一团。","en":"But your keys, gentlemen, make one great muddle.","note":"推定修订"},{"id":"la-dame-aux-camelias-08-024","lineIndex":24,"sourceLineIndex":24,"speaker":"","original":"L'art du planning, c'est tout un cirque.","ipa":"/lˈaʁ dˈy- plˈanɪŋ sˈɛ tˈu ˈœ̃ sˈiʁk/","zh":"安排的艺术，简直是一场马戏。","en":"The art of planning is a whole circus.","note":"推定修订"},{"id":"la-dame-aux-camelias-08-025","lineIndex":25,"sourceLineIndex":25,"speaker":"","original":"Les clés tournent, scénario dramatique.","ipa":"/lˈe- klˈe tˈuʁn senaʁjˈo dʁamatˈik/","zh":"钥匙不停轮转，剧情戏剧化。","en":"The keys turn: a dramatic scenario.","note":"推定修订"},{"id":"la-dame-aux-camelias-08-026","lineIndex":26,"sourceLineIndex":26,"speaker":"","original":"Un amour par porte, autre crise.","ipa":"/ˈœ̃ amˈuʁ pˈaʁ pˈɔʁt ˈotʁ kʁˈiz/","zh":"每扇门后都有一段恋情，又一场危机。","en":"A love affair behind every door, another crisis.","note":"推定修订"},{"id":"la-dame-aux-camelias-08-027","lineIndex":27,"sourceLineIndex":27,"speaker":"","original":"Chama et Marguerite, t’as le cœur plein.","ipa":"/ʃamˈa ˈe maʁɡəʁˈit tˈa lˈə- kˈœʁ plˈɛ̃/","zh":"沙玛与玛格丽特，你心里满是情意。","en":"Chama and Marguerite, your heart is full.","note":"推定修订"},{"id":"la-dame-aux-camelias-08-028","lineIndex":28,"sourceLineIndex":28,"speaker":"","original":"Aïe, aïe, aïe, aïe, aïe.","ipa":"/ˈaj ˈaj ˈaj ˈaj ˈaj/","zh":"哎哟，哎哟，哎哟，哎哟，哎哟。","en":"Ow, ow, ow, ow, ow.","note":"推定修订"},{"id":"la-dame-aux-camelias-08-029","lineIndex":29,"sourceLineIndex":29,"speaker":"","original":"À minuit, en secret, j'ai son propre jardin.","ipa":"/ˈa minyˈi ˈɑ̃ səkʁˈɛ ʒˈe sˈɔ̃ pʁˈɔpʁ ʒaʁdˈɛ̃/","zh":"午夜时分，我秘密拥有他的私人花园。","en":"At midnight, in secret, I have his own garden.","note":"推定修订"},{"id":"la-dame-aux-camelias-08-030","lineIndex":30,"sourceLineIndex":30,"speaker":"","original":"Les jeunes hommes en ville s’aiment comme des gamins.","ipa":"/lˈe- ʒˈøn ˈɔm ˈɑ̃ vˈil sˈɛm kˈɔm dˈe- ɡamˈɛ̃/","zh":"城里的年轻男子，像孩子一样彼此相爱。","en":"Young men in town love one another like children.","note":"推定修订"},{"id":"la-dame-aux-camelias-08-031","lineIndex":31,"sourceLineIndex":31,"speaker":"","original":"Mais quand tout le monde a sa clé dans le sac,","ipa":"/mˈɛ kˈɑ̃ tˈu lˈə- mˈɔ̃d ˈa sˈa- klˈe dˈɑ̃ lˈə- sˈak/","zh":"可当每个人都把钥匙放进包里，","en":"But when everyone has their key in their bag,","note":"推定修订"},{"id":"la-dame-aux-camelias-08-032","lineIndex":32,"sourceLineIndex":32,"speaker":"","original":"Marguerite est cuite, c'est le grand couac.","ipa":"/maʁɡəʁˈit ˈɛ kyˈit sˈɛ lˈə- ɡʁˈɑ̃ kwˈak/","zh":"玛格丽特这下完了，真是一场大岔子。","en":"Marguerite is done for; it's a major mishap.","note":"推定修订"},{"id":"la-dame-aux-camelias-08-033","lineIndex":33,"sourceLineIndex":33,"speaker":"","original":"Je fais des miracles, je garde planning au clair.","ipa":"/ʒˈə- fˈɛ dˈe- miʁˈakl ʒˈə- ɡˈaʁd plˈanɪŋ ˈo klˈɛʁ/","zh":"我创造奇迹，让日程井井有条。","en":"I work miracles and keep the schedule clear.","note":"推定修订"},{"id":"la-dame-aux-camelias-08-034","lineIndex":34,"sourceLineIndex":34,"speaker":"","original":"Mais ces messieurs, ils ont tous le même horaire.","ipa":"/mˈɛ sˈe mesjˈø ˈil ˈɔ̃ tˈus lˈə- mˈɛm oʁˈɛʁ/","zh":"可这些先生们的时间表全都一样。","en":"But these gentlemen all have the same schedule.","note":"推定修订"},{"id":"la-dame-aux-camelias-08-035","lineIndex":35,"sourceLineIndex":35,"speaker":"","original":"Une porte, deux portes, trois clés au trousseau.","ipa":"/ˈyn pˈɔʁt dˈø pˈɔʁt tʁwˈa klˈe ˈo tʁusˈo/","zh":"一扇门，两扇门，钥匙串上三把钥匙。","en":"One door, two doors, three keys on the ring.","note":"推定修订"},{"id":"la-dame-aux-camelias-08-036","lineIndex":36,"sourceLineIndex":36,"speaker":"","original":"Le bal des amants, et moi, j’suis le chef d’orchestre.","ipa":"/lˈə- bˈal dˈe- amˈɑ̃ ˈe mwˈa ʒsyˈi lˈə- ʃˈɛf dɔʁkˈɛstʁ/","zh":"情人们的舞会，而我是这场演出的指挥。","en":"The lovers’ ball—and I am the conductor.","note":"推定修订"},{"id":"la-dame-aux-camelias-08-037","lineIndex":37,"sourceLineIndex":37,"speaker":"","original":"L'art du planning, c'est tout un cirque.","ipa":"/lˈaʁ dˈy- plˈanɪŋ sˈɛ tˈu ˈœ̃ sˈiʁk/","zh":"安排的艺术，简直是一场马戏。","en":"The art of planning is a whole circus.","note":"推定修订"},{"id":"la-dame-aux-camelias-08-038","lineIndex":38,"sourceLineIndex":38,"speaker":"","original":"Clé qui tourne, scénario dramatique.","ipa":"/klˈe kˈi tˈuʁn senaʁjˈo dʁamatˈik/","zh":"一把钥匙转动，剧情戏剧化。","en":"A key turns: a dramatic scenario.","note":"推定修订"},{"id":"la-dame-aux-camelias-08-039","lineIndex":39,"sourceLineIndex":39,"speaker":"","original":"Un amant par porte, autre crise.","ipa":"/ˈœ̃ amˈɑ̃ pˈaʁ pˈɔʁt ˈotʁ kʁˈiz/","zh":"每扇门后都有一段恋情，又一场危机。","en":"A love affair behind every door, another crisis.","note":"推定修订"},{"id":"la-dame-aux-camelias-08-040","lineIndex":40,"sourceLineIndex":40,"speaker":"","original":"Chama et Marguerite, t’as le cœur plein.","ipa":"/ʃamˈa ˈe maʁɡəʁˈit tˈa lˈə- kˈœʁ plˈɛ̃/","zh":"沙玛与玛格丽特，你心里满是情意。","en":"Chama and Marguerite, your heart is full.","note":"推定修订"},{"id":"la-dame-aux-camelias-08-041","lineIndex":41,"sourceLineIndex":41,"speaker":"","original":"Aïe, aïe, aïe, aïe, aïe.","ipa":"/ˈaj ˈaj ˈaj ˈaj ˈaj/","zh":"哎哟，哎哟，哎哟，哎哟，哎哟。","en":"Ow, ow, ow, ow, ow.","note":"推定修订"},{"id":"la-dame-aux-camelias-08-042","lineIndex":42,"sourceLineIndex":42,"speaker":"","original":"Oh, la reine de la nuit, c'est pas de la prose : trop de clés, trop de cœur, et tout est exposé.","ipa":"/ˈɔ lˈa- ʁˈɛn dˈə- lˈa- nyˈi sˈɛ pˈa dˈə- lˈa- pʁˈɔz tʁˈo dˈə- klˈe tʁˈo dˈə- kˈœʁ ˈe tˈu ˈɛ ɛkspozˈe/","zh":"哦，夜之女王，这可不是散文：钥匙太多，情意太浓，一切都暴露无遗。","en":"Oh, queen of the night, this isn't prose: too many keys, too much heart, and everything is exposed.","note":"推定修订"},{"id":"la-dame-aux-camelias-08-043","lineIndex":43,"sourceLineIndex":43,"speaker":"","original":"Marguerite, ma belle, fais gaffe à tes clés, ou ton bal d'amant va tout faire sauter.","ipa":"/maʁɡəʁˈit mˈa- bˈɛl fˈɛ ɡˈaf ˈa tˈe- klˈe ˈu tˈɔ̃ bˈal damˈɑ̃ vˈa tˈu fˈɛʁ sotˈe/","zh":"玛格丽特，亲爱的，看好你的钥匙，否则你的情人舞会会把一切都闹翻。","en":"Marguerite, my dear, watch your keys, or your lovers' ball will blow everything up.","note":"推定修订"}],"sourceOrder":8,"displayOrder":8},{"order":9,"id":"09-ma-ligne","title":"Ma ligne","titleZh":"我的底线","lines":[{"id":"la-dame-aux-camelias-09-046","lineIndex":1,"sourceLineIndex":1,"speaker":"","original":"Née dans le caniveau, élevée dans le noir. J’ai appris l’alphabet dans le creux d’un couloir.","ipa":"/nˈe dˈɑ̃ lˈə- kanivˈo elvˈe dˈɑ̃ lˈə- nwˈaʁ ʒˈe apʁˈi lalfabˈɛ dˈɑ̃ lˈə- kʁˈø dˈœ̃ kulwˈaʁ/","zh":"我生在阴沟，长在黑暗里。我在走廊的幽暗深处学会字母。","en":"Born in the gutter, raised in the dark. I learned the alphabet in the hollow of a hallway.","note":"推定修订"},{"id":"la-dame-aux-camelias-09-047","lineIndex":2,"sourceLineIndex":2,"speaker":"","original":"Les coups de ma mère, les mains de ce père. Chaque cicatrice a forgé mon empire de vers.","ipa":"/lˈe- kˈu dˈə- mˈa- mˈɛʁ lˈe- mˈɛ̃ dˈə- sˈə- pˈɛʁ ʃˈak sikatʁˈis ˈa fɔʁʒˈe mˈɔ̃ ɑ̃pˈiʁ dˈə- vˈɛʁ/","zh":"母亲的打骂，父亲的双手。每一道伤疤，都铸成我诗句的疆土。","en":"My mother’s blows, my father’s hands. Every scar forged my empire of verse.","note":"推定修订"},{"id":"la-dame-aux-camelias-09-048","lineIndex":3,"sourceLineIndex":3,"speaker":"","original":"J’ai griffé la terre pour sortir du néant.","ipa":"/ʒˈe ɡʁifˈe lˈa- tˈɛʁ pˈuʁ sɔʁtˈiʁ dˈy- neˈɑ̃/","zh":"我抓挠着大地，挣脱虚无。","en":"I clawed at the earth to escape nothingness.","note":"推定修订"},{"id":"la-dame-aux-camelias-09-049","lineIndex":4,"sourceLineIndex":4,"speaker":"","original":"J’ai dompté la honte, j’ai défié les géants.","ipa":"/ʒˈe dɔ̃ptˈe lˈa- ˈɔ̃t ʒˈe defjˈe lˈe- ʒeˈɑ̃/","zh":"我驯服羞耻，向巨人挑战。","en":"I tamed my shame; I defied the giants.","note":"推定修订"},{"id":"la-dame-aux-camelias-09-050","lineIndex":5,"sourceLineIndex":5,"speaker":"","original":"Regarde-moi bien sous mon masque de soie.","ipa":"/ʁəɡˈaʁdmwˈa bjˈɛ̃ sˈu mˈɔ̃ mˈask dˈə- swˈa/","zh":"透过我的丝绸面具，好好看着我。","en":"Look closely at me beneath my silk mask.","note":"推定修订"},{"id":"la-dame-aux-camelias-09-051","lineIndex":6,"sourceLineIndex":6,"speaker":"","original":"Je ne suis plus la proie, je dicte ma loi.","ipa":"/ʒˈə- nˈə- syˈi plˈy lˈa- pʁwˈa ʒˈə- dˈikt mˈa- lwˈa/","zh":"我不再是猎物，我要由我作主。","en":"I am no longer the prey; I make the rules.","note":"推定修订"},{"id":"la-dame-aux-camelias-09-052","lineIndex":7,"sourceLineIndex":7,"speaker":"","original":"L’illusion est parfaite, le vernis est brillant.","ipa":"/lilyzjˈɔ̃ ˈɛ paʁfˈɛt lˈə- vɛʁnˈi ˈɛ bʁijˈɑ̃/","zh":"幻象无懈可击，表面光鲜亮丽。","en":"The illusion is perfect; the polish shines.","note":"推定修订"},{"id":"la-dame-aux-camelias-09-053","lineIndex":8,"sourceLineIndex":8,"speaker":"","original":"Mais derrière la fête, il y a le cri et le son.","ipa":"/mˈɛ dɛʁjˈɛʁ lˈa- fˈɛt ˈil iɡʁˈɛk ˈa lˈə- kʁˈi ˈe lˈə- sˈɔ̃/","zh":"可在盛宴背后，有哭喊，也有声音。","en":"But behind the party, there is the cry and the sound.","note":"推定修订"},{"id":"la-dame-aux-camelias-09-054","lineIndex":9,"sourceLineIndex":9,"speaker":"","original":"Seigneur, je n’ai jamais plié.","ipa":"/sɛnjˈœʁ ʒˈə- nˈe ʒamˈɛ pliˈe/","zh":"上帝啊，我从未屈服。","en":"Lord, I have never bowed.","note":"推定修订"},{"id":"la-dame-aux-camelias-09-002","lineIndex":10,"sourceLineIndex":10,"speaker":"","original":"Le cœur en ruine, je l’ai sacrifié.","ipa":"/lˈə- kˈœʁ ˈɑ̃ ʁyˈin ʒˈə- lˈe sakʁifjˈe/","zh":"我将破碎的心献祭出去。","en":"My heart in ruins, I sacrificed it.","note":"推定修订"},{"id":"la-dame-aux-camelias-09-055","lineIndex":11,"sourceLineIndex":11,"speaker":"","original":"Je suis mon armure, je suis mon combat.","ipa":"/ʒˈə- syˈi mˈɔ̃ aʁmˈyʁ ʒˈə- syˈi mˈɔ̃ kɔ̃bˈa/","zh":"我就是自己的铠甲，我就是自己的战斗。","en":"I am my own armor; I am my own battle.","note":"推定修订"},{"id":"la-dame-aux-camelias-09-056","lineIndex":12,"sourceLineIndex":12,"speaker":"","original":"Le luxe, c’est une cure qui ne guérit pas.","ipa":"/lˈə- lˈyks sˈɛ ˈyn kˈyʁ kˈi nˈə- ɡeʁˈi pˈa/","zh":"奢华是一剂无法治愈的药。","en":"Luxury is a cure that does not heal.","note":"推定修订"},{"id":"la-dame-aux-camelias-09-057","lineIndex":13,"sourceLineIndex":13,"speaker":"","original":"Pas de place pour lui, pas de place pour nous.","ipa":"/pˈa dˈə- plˈas pˈuʁ lyˈi pˈa dˈə- plˈas pˈuʁ nˈu/","zh":"没有他的位置，也没有我们的位置。","en":"There is no place for him, no place for us.","note":"推定修订"},{"id":"la-dame-aux-camelias-09-058","lineIndex":14,"sourceLineIndex":14,"speaker":"","original":"Je reste debout, je tombe à genoux.","ipa":"/ʒˈə- ʁˈɛst dəbˈu ʒˈə- tˈɔ̃b ˈa ʒənˈu/","zh":"我仍然站着，却又跪倒在地。","en":"I stand tall; I fall to my knees.","note":"推定修订"},{"id":"la-dame-aux-camelias-09-012","lineIndex":15,"sourceLineIndex":15,"speaker":"","original":"J’ai troqué mes sabots contre des escarpins.","ipa":"/ʒˈe tʁokˈe mˈe- sabˈo kˈɔ̃tʁ dˈe- ɛskaʁpˈɛ̃/","zh":"我用木鞋换来了高跟鞋。","en":"I traded my clogs for high heels.","note":"推定修订"},{"id":"la-dame-aux-camelias-09-059","lineIndex":16,"sourceLineIndex":16,"speaker":"","original":"J’ai volé ma vie, j’ai forcé mon destin.","ipa":"/ʒˈe volˈe mˈa- vˈi ʒˈe fɔʁsˈe mˈɔ̃ dɛstˈɛ̃/","zh":"我夺回了自己的人生，强行改写命运。","en":"I stole my life; I forced my destiny.","note":"推定修订"},{"id":"la-dame-aux-camelias-09-016","lineIndex":17,"sourceLineIndex":17,"speaker":"","original":"Six ans en arrière, je n’étais personne.","ipa":"/sˈis ˈɑ̃ ˈɑ̃ aʁjˈɛʁ ʒˈə- netˈɛ pɛʁsˈɔn/","zh":"六年前，我还默默无闻。","en":"Six years ago, I was nobody.","note":"推定修订"},{"id":"la-dame-aux-camelias-09-060","lineIndex":18,"sourceLineIndex":18,"speaker":"","original":"Aujourd’hui, c’est mon nom que tout Paris chante.","ipa":"/oʒuʁdyˈi sˈɛ mˈɔ̃ nˈɔ̃ kˈə tˈu paʁˈi ʃˈɑ̃t/","zh":"如今，整个巴黎都在唱我的名字。","en":"Today, all Paris sings my name.","note":"推定修订"},{"id":"la-dame-aux-camelias-09-061","lineIndex":19,"sourceLineIndex":19,"speaker":"","original":"Mais ne crois pas au jeu, ne crois pas au décor.","ipa":"/mˈɛ nˈə- kʁwˈa pˈa ˈo ʒˈø nˈə- kʁwˈa pˈa ˈo dekˈɔʁ/","zh":"但别相信这场戏，也别相信这布景。","en":"But do not believe in the game; do not believe in the set.","note":"推定修订"},{"id":"la-dame-aux-camelias-09-022","lineIndex":20,"sourceLineIndex":20,"speaker":"","original":"L’amour est un piège qui demande ta mort.","ipa":"/lamˈuʁ ˈɛ ˈœ̃ pjˈɛʒ kˈi dəmˈɑ̃d tˈa- mˈɔʁ/","zh":"爱情是个索命的陷阱。","en":"Love is a trap that demands your death.","note":"推定修订"},{"id":"la-dame-aux-camelias-09-062","lineIndex":21,"sourceLineIndex":21,"speaker":"","original":"Et puis, y a lui… Armand, il croit m’aimer.","ipa":"/ˈe pyˈi iɡʁˈɛk ˈa lyˈi aʁmˈɑ̃ ˈil kʁwˈa mɛmˈe/","zh":"然后还有他……阿尔芒以为自己爱我。","en":"And then there is him… Armand thinks he loves me.","note":"推定修订"},{"id":"la-dame-aux-camelias-09-026","lineIndex":22,"sourceLineIndex":22,"speaker":"","original":"Quel enfantillage !","ipa":"/kˈɛl ɑ̃fɑ̃tijˈaʒ/","zh":"真幼稚！","en":"How childish!","note":"推定修订"},{"id":"la-dame-aux-camelias-09-027","lineIndex":23,"sourceLineIndex":23,"speaker":"","original":"Il veut briser les barreaux de ma cage.","ipa":"/ˈil vˈø bʁizˈe lˈe- baʁˈo dˈə- mˈa- kˈaʒ/","zh":"他想打断我牢笼的栏杆。","en":"He wants to break the bars of my cage.","note":"推定修订"},{"id":"la-dame-aux-camelias-09-028","lineIndex":24,"sourceLineIndex":24,"speaker":"","original":"Je me suis faite seule, à la force des bras.","ipa":"/ʒˈə- mˈə- syˈi fˈɛt sˈœl ˈa lˈa- fˈɔʁs dˈe- bʁˈa/","zh":"我靠自己的双手，造就了今天的自己。","en":"I made myself who I am, through sheer effort.","note":"推定修订"},{"id":"la-dame-aux-camelias-09-030","lineIndex":25,"sourceLineIndex":25,"speaker":"","original":"L’amour est un gouffre où je ne le suivrai pas.","ipa":"/lamˈuʁ ˈɛ ˈœ̃ ɡˈufʁ ˈu ʒˈə- nˈə- lˈə- syivʁˈe pˈa/","zh":"爱情是深渊，我不会跟他坠入其中。","en":"Love is an abyss; I will not follow him into it.","note":"推定修订"},{"id":"la-dame-aux-camelias-09-063","lineIndex":26,"sourceLineIndex":26,"speaker":"","original":"Seigneur, la nuit, ne jamais plier.","ipa":"/sɛnjˈœʁ lˈa- nyˈi nˈə- ʒamˈɛ pliˈe/","zh":"上帝啊，夜里也绝不屈服。","en":"Lord, at night, never to bend.","note":"推定修订"},{"id":"la-dame-aux-camelias-09-064","lineIndex":27,"sourceLineIndex":27,"speaker":"","original":"Le cœur en ruine, je l’ai sacrifié.","ipa":"/lˈə- kˈœʁ ˈɑ̃ ʁyˈin ʒˈə- lˈe sakʁifjˈe/","zh":"我的心已成废墟，而我把它献了出去。","en":"My heart is in ruins, and I sacrificed it.","note":"推定修订"},{"id":"la-dame-aux-camelias-09-065","lineIndex":28,"sourceLineIndex":28,"speaker":"","original":"Je suis mon armure, je suis mon combat.","ipa":"/ʒˈə- syˈi mˈɔ̃ aʁmˈyʁ ʒˈə- syˈi mˈɔ̃ kɔ̃bˈa/","zh":"我就是自己的铠甲，我就是自己的战斗。","en":"I am my own armor; I am my own battle.","note":"推定修订"},{"id":"la-dame-aux-camelias-09-066","lineIndex":29,"sourceLineIndex":29,"speaker":"","original":"Le luxe, c’est une cure qui ne guérit pas.","ipa":"/lˈə- lˈyks sˈɛ ˈyn kˈyʁ kˈi nˈə- ɡeʁˈi pˈa/","zh":"奢华是一剂无法治愈的药。","en":"Luxury is a cure that does not heal.","note":"推定修订"},{"id":"la-dame-aux-camelias-09-067","lineIndex":30,"sourceLineIndex":30,"speaker":"","original":"Pas de place pour lui, pas de place pour nous.","ipa":"/pˈa dˈə- plˈas pˈuʁ lyˈi pˈa dˈə- plˈas pˈuʁ nˈu/","zh":"没有他的位置，也没有我们的位置。","en":"There is no place for him, no place for us.","note":"推定修订"},{"id":"la-dame-aux-camelias-09-041","lineIndex":31,"sourceLineIndex":31,"speaker":"","original":"Je reste debout.","ipa":"/ʒˈə- ʁˈɛst dəbˈu/","zh":"我依然站着。","en":"I remain standing.","note":"推定修订"},{"id":"la-dame-aux-camelias-09-068","lineIndex":32,"sourceLineIndex":32,"speaker":"","original":"Oh, oh, oh, oh, oh, oh.","ipa":"/ˈɔ ˈɔ ˈɔ ˈɔ ˈɔ ˈɔ/","zh":"哦，哦，哦，哦，哦，哦。","en":"Oh, oh, oh, oh, oh, oh.","note":"推定修订"},{"id":"la-dame-aux-camelias-09-069","lineIndex":33,"sourceLineIndex":33,"speaker":"","original":"Oh, oh, oh, oh, oh, oh.","ipa":"/ˈɔ ˈɔ ˈɔ ˈɔ ˈɔ ˈɔ/","zh":"哦，哦，哦，哦，哦，哦。","en":"Oh, oh, oh, oh, oh, oh.","note":"推定修订"},{"id":"la-dame-aux-camelias-09-070","lineIndex":34,"sourceLineIndex":34,"speaker":"","original":"Oh, oh, oh, oh, oh.","ipa":"/ˈɔ ˈɔ ˈɔ ˈɔ ˈɔ/","zh":"哦，哦，哦，哦，哦。","en":"Oh, oh, oh, oh, oh.","note":"推定修订"},{"id":"la-dame-aux-camelias-09-071","lineIndex":35,"sourceLineIndex":35,"speaker":"","original":"Rougis tes lèvres, lisse tes traits.","ipa":"/ʁuʒˈi tˈe- lˈɛvʁ lˈis tˈe- tʁˈɛ/","zh":"染红嘴唇，抚平眉眼。","en":"Redden your lips, smooth your features.","note":"推定修订"},{"id":"la-dame-aux-camelias-09-044","lineIndex":36,"sourceLineIndex":36,"speaker":"","original":"Ne l’aime pas.","ipa":"/nˈə- lˈɛm pˈa/","zh":"不要爱他。","en":"Do not love him.","note":"推定修订"},{"id":"la-dame-aux-camelias-09-045","lineIndex":37,"sourceLineIndex":37,"speaker":"","original":"Jamais.","ipa":"/ʒamˈɛ/","zh":"永远不要。","en":"Never.","note":"推定修订"}],"sourceOrder":9,"displayOrder":9},{"order":10,"id":"10-l-amour-qu-on-s-interdit","title":"L’amour qu’on s’interdit","titleZh":"禁忌的爱","lines":[{"id":"la-dame-aux-camelias-10-001","lineIndex":1,"sourceLineIndex":1,"speaker":"","original":"Nos murmures ne sont que folie.","ipa":"/nˈo myʁmˈyʁ nˈə- sˈɔ̃ kˈə folˈi/","zh":"我们的低语不过是痴狂。","en":"Our whispers are nothing but madness.","note":"推定修订"},{"id":"la-dame-aux-camelias-10-002","lineIndex":2,"sourceLineIndex":2,"speaker":"","original":"Ils font tant de bruit.","ipa":"/ˈil fˈɔ̃ tˈɑ̃ dˈə- bʁyˈi/","zh":"它们掀起阵阵喧嚣。","en":"They make so much noise.","note":"推定修订"},{"id":"la-dame-aux-camelias-10-003","lineIndex":3,"sourceLineIndex":3,"speaker":"","original":"Nos âmes qui s'enlacent bravent l'interdit.","ipa":"/nˈo ˈaːm kˈi sɑ̃lˈas bʁˈav lɛ̃tɛʁdˈi/","zh":"我们交缠的灵魂，挑战着禁忌。","en":"Our entwined souls defy what is forbidden.","note":"推定修订"},{"id":"la-dame-aux-camelias-10-004","lineIndex":4,"sourceLineIndex":4,"speaker":"","original":"Un avenir dans le ciel se dessine.","ipa":"/ˈœ̃ avnˈiʁ dˈɑ̃ lˈə- sjˈɛl sˈə- dɛsˈin/","zh":"未来正在天际渐渐显现。","en":"A future is taking shape in the sky.","note":"推定修订"},{"id":"la-dame-aux-camelias-10-005","lineIndex":5,"sourceLineIndex":5,"speaker":"","original":"Est-ce que notre histoire commence ici ?","ipa":"/ˈɛs kˈə nˈotʁ istwˈaʁ kɔmˈɑ̃s isˈi/","zh":"我们的故事会从这里开始吗？","en":"Is this where our story begins?","note":"推定修订"},{"id":"la-dame-aux-camelias-10-006","lineIndex":6,"sourceLineIndex":6,"speaker":"","original":"L'amour qu'on s'interdit.","ipa":"/lamˈuʁ kˈɔ̃ sɛ̃tɛʁdˈi/","zh":"我们不敢拥有的爱。","en":"The love we deny ourselves.","note":"推定修订"},{"id":"la-dame-aux-camelias-10-007","lineIndex":7,"sourceLineIndex":7,"speaker":"","original":"Est-ce qu'on doit le fuir ?","ipa":"/ˈɛs kˈɔ̃ dwˈa lˈə- fyˈiʁ/","zh":"我们该逃离这份爱吗？","en":"Should we run away from it?","note":"推定修订"},{"id":"la-dame-aux-camelias-10-008","lineIndex":8,"sourceLineIndex":8,"speaker":"","original":"Ou faire tout ce qui ne se fait pas ?","ipa":"/ˈu fˈɛʁ tˈu sˈə- kˈi nˈə- sˈə- fˈɛ pˈa/","zh":"还是去做所有不该做的事？","en":"Or do everything one is not supposed to do?","note":"推定修订"},{"id":"la-dame-aux-camelias-10-042","lineIndex":9,"sourceLineIndex":9,"speaker":"","original":"Jusqu’où pourra-t-on résister au danger ?","ipa":"/ʒˈysku puʁˈatˈɔ̃ ʁezistˈe ˈo dɑ̃ʒˈe/","zh":"面对这危险，我们还能抵抗多久？","en":"How long can we resist the danger?","note":"推定修订"},{"id":"la-dame-aux-camelias-10-043","lineIndex":10,"sourceLineIndex":10,"speaker":"","original":"L’avenir nous le dira.","ipa":"/lavnˈiʁ nˈu lˈə- diʁˈa/","zh":"未来会告诉我们。","en":"The future will tell us.","note":"推定修订"},{"id":"la-dame-aux-camelias-10-044","lineIndex":11,"sourceLineIndex":11,"speaker":"","original":"Oh, yeah.","ipa":"/ˈɔ jˈɛh/","zh":"哦，耶。","en":"Oh, yeah.","note":"推定修订"},{"id":"la-dame-aux-camelias-10-045","lineIndex":12,"sourceLineIndex":12,"speaker":"","original":"Oh.","ipa":"/ˈɔ/","zh":"哦。","en":"Oh.","note":"推定修订"},{"id":"la-dame-aux-camelias-10-012","lineIndex":13,"sourceLineIndex":13,"speaker":"","original":"Je tente, l'avenir nous le dira.","ipa":"/ʒˈə- tˈɑ̃t lavnˈiʁ nˈu lˈə- diʁˈa/","zh":"我试着迈出这一步，答案留待未来揭晓。","en":"I dare to try; the future will tell us.","note":"推定修订"},{"id":"la-dame-aux-camelias-10-046","lineIndex":14,"sourceLineIndex":14,"speaker":"","original":"Oh, yeah.","ipa":"/ˈɔ jˈɛh/","zh":"哦，耶。","en":"Oh, yeah.","note":"推定修订"},{"id":"la-dame-aux-camelias-10-047","lineIndex":15,"sourceLineIndex":15,"speaker":"","original":"Oh.","ipa":"/ˈɔ/","zh":"哦。","en":"Oh.","note":"推定修订"},{"id":"la-dame-aux-camelias-10-014","lineIndex":16,"sourceLineIndex":16,"speaker":"","original":"J'ai fait un pas et je ne devrais pas.","ipa":"/ʒˈe fˈɛ ˈœ̃ pˈa ˈe ʒˈə- nˈə- dəvʁˈɛ pˈa/","zh":"我迈出了一步，本不该如此。","en":"I took a step, though I shouldn't have.","note":"推定修订"},{"id":"la-dame-aux-camelias-10-015","lineIndex":17,"sourceLineIndex":17,"speaker":"","original":"Mais quand tu t'approches de moi,","ipa":"/mˈɛ kˈɑ̃ tˈy tapʁˈoʃ dˈə- mwˈa/","zh":"可当你靠近我时，","en":"But when you come close to me,","note":"推定修订"},{"id":"la-dame-aux-camelias-10-016","lineIndex":18,"sourceLineIndex":18,"speaker":"","original":"Ai-je vraiment le choix ?","ipa":"/ˈɛʒ vʁɛmˈɑ̃ lˈə- ʃwˈa/","zh":"我真的有选择吗？","en":"Do I really have a choice?","note":"推定修订"},{"id":"la-dame-aux-camelias-10-017","lineIndex":19,"sourceLineIndex":19,"speaker":"","original":"Mais qu'avons-nous là qu'on ne nomme pas ?","ipa":"/mˈɛ kavˈɔ̃nˈu lˈa kˈɔ̃ nˈə- nˈɔm pˈa/","zh":"可我们之间这份不曾言明的情愫，究竟是什么？","en":"But what is this between us that we don't name?","note":"推定修订"},{"id":"la-dame-aux-camelias-10-048","lineIndex":20,"sourceLineIndex":20,"speaker":"","original":"Derrière tant de règles, on s'en oublie parfois.","ipa":"/dɛʁjˈɛʁ tˈɑ̃ dˈə- ʁˈɛɡl ˈɔ̃ sˈɑ̃ ublˈi paʁfwˈa/","zh":"在重重规矩之下，我们有时会忘了自己。","en":"Behind so many rules, sometimes we forget ourselves.","note":"推定修订"},{"id":"la-dame-aux-camelias-10-049","lineIndex":21,"sourceLineIndex":21,"speaker":"","original":"Doit-on fuir loin de l'autre vers une autre prise ?","ipa":"/dwˈatˈɔ̃ fyˈiʁ lwˈɛ̃ dˈə- lˈotʁ vˈɛʁ ˈyn ˈotʁ pʁˈiz/","zh":"我们是否要远远逃离彼此，走向另一种尝试？","en":"Should we flee far from each other toward another take?","note":"推定修订"},{"id":"la-dame-aux-camelias-10-050","lineIndex":22,"sourceLineIndex":22,"speaker":"","original":"Nous voir chanter une autre mélodie ?","ipa":"/nˈu vwˈaʁ ʃɑ̃tˈe ˈyn ˈotʁ melodˈi/","zh":"看着我们唱起另一支旋律？","en":"To see us sing another melody?","note":"推定修订"},{"id":"la-dame-aux-camelias-10-021","lineIndex":23,"sourceLineIndex":23,"speaker":"","original":"Un merveilleux destin se profile.","ipa":"/ˈœ̃ mɛʁvɛjˈø dɛstˈɛ̃ sˈə- pʁofˈil/","zh":"一段美好的命运正渐渐展开。","en":"A wonderful destiny is taking shape.","note":"推定修订"},{"id":"la-dame-aux-camelias-10-022","lineIndex":24,"sourceLineIndex":24,"speaker":"","original":"Est-ce que notre amour commence ici ?","ipa":"/ˈɛs kˈə nˈotʁ amˈuʁ kɔmˈɑ̃s isˈi/","zh":"我们的爱会在这里开始吗？","en":"Could our love begin here?","note":"推定修订"},{"id":"la-dame-aux-camelias-10-023","lineIndex":25,"sourceLineIndex":25,"speaker":"","original":"L'amour qu'on s'interdit.","ipa":"/lamˈuʁ kˈɔ̃ sɛ̃tɛʁdˈi/","zh":"我们禁止自己去爱的这份爱。","en":"The love we forbid ourselves.","note":"推定修订"},{"id":"la-dame-aux-camelias-10-024","lineIndex":26,"sourceLineIndex":26,"speaker":"","original":"Est-ce qu'on doit le fuir ?","ipa":"/ˈɛs kˈɔ̃ dwˈa lˈə- fyˈiʁ/","zh":"我们该逃离这份爱吗？","en":"Should we run away from it?","note":"推定修订"},{"id":"la-dame-aux-camelias-10-025","lineIndex":27,"sourceLineIndex":27,"speaker":"","original":"Ou faire tout ce qui ne se fait pas ?","ipa":"/ˈu fˈɛʁ tˈu sˈə- kˈi nˈə- sˈə- fˈɛ pˈa/","zh":"还是去做所有不该做的事？","en":"Or do everything one is not supposed to do?","note":"推定修订"},{"id":"la-dame-aux-camelias-10-051","lineIndex":28,"sourceLineIndex":28,"speaker":"","original":"Jusqu’où pourra-t-on résister au danger ?","ipa":"/ʒˈysku puʁˈatˈɔ̃ ʁezistˈe ˈo dɑ̃ʒˈe/","zh":"面对这危险，我们还能抵抗多久？","en":"How long can we resist the danger?","note":"推定修订"},{"id":"la-dame-aux-camelias-10-052","lineIndex":29,"sourceLineIndex":29,"speaker":"","original":"L’avenir nous le dira.","ipa":"/lavnˈiʁ nˈu lˈə- diʁˈa/","zh":"未来会告诉我们。","en":"The future will tell us.","note":"推定修订"},{"id":"la-dame-aux-camelias-10-028","lineIndex":30,"sourceLineIndex":30,"speaker":"","original":"Oh, yeah, oh.","ipa":"/ˈɔ jˈɛh ˈɔ/","zh":"哦，耶，哦。","en":"Oh, yeah, oh.","note":"推定修订"},{"id":"la-dame-aux-camelias-10-029","lineIndex":31,"sourceLineIndex":31,"speaker":"","original":"Je tente, l'avenir nous le dira.","ipa":"/ʒˈə- tˈɑ̃t lavnˈiʁ nˈu lˈə- diʁˈa/","zh":"我试着迈出这一步，答案留待未来揭晓。","en":"I dare to try; the future will tell us.","note":"推定修订"},{"id":"la-dame-aux-camelias-10-030","lineIndex":32,"sourceLineIndex":32,"speaker":"","original":"Oh, yeah, oh.","ipa":"/ˈɔ jˈɛh ˈɔ/","zh":"哦，耶，哦。","en":"Oh, yeah, oh.","note":"推定修订"},{"id":"la-dame-aux-camelias-10-053","lineIndex":33,"sourceLineIndex":33,"speaker":"","original":"Que je veux en toi, que je n'admets pas,","ipa":"/kˈə ʒˈə- vˈø ˈɑ̃ twˈa kˈə ʒˈə- nadmˈɛ pˈa/","zh":"我在你身上渴望、却不肯承认的，","en":"What I want in you but won't admit,","note":"推定修订"},{"id":"la-dame-aux-camelias-10-032","lineIndex":34,"sourceLineIndex":34,"speaker":"","original":"Qui se dessine là ?","ipa":"/kˈi sˈə- dɛsˈin lˈa/","zh":"那渐渐显露的是什么？","en":"What is taking shape there?","note":"推定修订"},{"id":"la-dame-aux-camelias-10-033","lineIndex":35,"sourceLineIndex":35,"speaker":"","original":"Serait-ce un remède ou un autre combat ?","ipa":"/səʁˈɛs ˈœ̃ ʁəmˈɛd ˈu ˈœ̃ ˈotʁ kɔ̃bˈa/","zh":"那会是解药，还是另一场争斗？","en":"Could it be a cure, or another battle?","note":"推定修订"},{"id":"la-dame-aux-camelias-10-035","lineIndex":36,"sourceLineIndex":36,"speaker":"","original":"Faire tout ce qui ne se fait pas.","ipa":"/fˈɛʁ tˈu sˈə- kˈi nˈə- sˈə- fˈɛ pˈa/","zh":"去做所有不该做的事。","en":"Do everything one is not supposed to do.","note":"推定修订"},{"id":"la-dame-aux-camelias-10-054","lineIndex":37,"sourceLineIndex":37,"speaker":"","original":"Jusqu’où pourra-t-on résister au danger ?","ipa":"/ʒˈysku puʁˈatˈɔ̃ ʁezistˈe ˈo dɑ̃ʒˈe/","zh":"面对这危险，我们还能抵抗多久？","en":"How long can we resist the danger?","note":"推定修订"},{"id":"la-dame-aux-camelias-10-055","lineIndex":38,"sourceLineIndex":38,"speaker":"","original":"L’avenir nous le dira.","ipa":"/lavnˈiʁ nˈu lˈə- diʁˈa/","zh":"未来会告诉我们。","en":"The future will tell us.","note":"推定修订"},{"id":"la-dame-aux-camelias-10-056","lineIndex":39,"sourceLineIndex":39,"speaker":"","original":"Je tente, l’avenir nous le dira.","ipa":"/ʒˈə- tˈɑ̃t lavnˈiʁ nˈu lˈə- diʁˈa/","zh":"我试着去做，未来会告诉我们。","en":"I’ll try; the future will tell us.","note":"推定修订"},{"id":"la-dame-aux-camelias-10-039","lineIndex":40,"sourceLineIndex":40,"speaker":"","original":"Faire tout ce qui ne se fait pas.","ipa":"/fˈɛʁ tˈu sˈə- kˈi nˈə- sˈə- fˈɛ pˈa/","zh":"去做所有不该做的事。","en":"Do everything one is not supposed to do.","note":"推定修订"},{"id":"la-dame-aux-camelias-10-057","lineIndex":41,"sourceLineIndex":41,"speaker":"","original":"Jusqu’où pourra-t-on résister au danger ?","ipa":"/ʒˈysku puʁˈatˈɔ̃ ʁezistˈe ˈo dɑ̃ʒˈe/","zh":"面对这危险，我们还能抵抗多久？","en":"How long can we resist the danger?","note":"推定修订"},{"id":"la-dame-aux-camelias-10-058","lineIndex":42,"sourceLineIndex":42,"speaker":"","original":"Elle le dira de nous.","ipa":"/ˈɛl lˈə- diʁˈa dˈə- nˈu/","zh":"她会谈起我们的事。","en":"She'll tell it about us.","note":"推定修订"}],"sourceOrder":10,"displayOrder":10},{"order":11,"id":"11-baron-noir","title":"Baron noir","titleZh":"黑男爵","lines":[{"id":"la-dame-aux-camelias-11-048","lineIndex":1,"sourceLineIndex":1,"speaker":"","original":"Je fais les cent pas dans Paris endormi.","ipa":"/ʒˈə- fˈɛ lˈe- sˈɑ̃ pˈa dˈɑ̃ paʁˈi ɑ̃dɔʁmˈi/","zh":"我在沉睡的巴黎来回踱步。","en":"I pace back and forth through sleeping Paris.","note":"推定修订"},{"id":"la-dame-aux-camelias-11-049","lineIndex":2,"sourceLineIndex":2,"speaker":"","original":"J’ai vu entrer l’ombre de mon ennemi.","ipa":"/ʒˈe vˈy ɑ̃tʁˈe lˈɔ̃bʁ dˈə- mˈɔ̃ ɛnmˈi/","zh":"我看见情敌的身影走了进来。","en":"I saw the shadow of my enemy come in.","note":"推定修订"},{"id":"la-dame-aux-camelias-11-050","lineIndex":3,"sourceLineIndex":3,"speaker":"","original":"J’ai l’or en mal, mais le regard noircit.","ipa":"/ʒˈe lˈɔʁ ˈɑ̃ mˈal mˈɛ lˈə- ʁəɡˈaʁ nwaʁsˈi/","zh":"我为金钱所困，目光却已黯淡。","en":"I have gold in distress, but my gaze has darkened.","note":"推定修订"},{"id":"la-dame-aux-camelias-11-004","lineIndex":4,"sourceLineIndex":4,"speaker":"","original":"Ton rire est à lui, je le sais aussi.","ipa":"/tˈɔ̃ ʁˈiʁ ˈɛ ˈa lyˈi ʒˈə- lˈə- sˈɛ osˈi/","zh":"你的笑声属于他，这一点我也知道。","en":"Your laughter belongs to him; I know it too.","note":"推定修订"},{"id":"la-dame-aux-camelias-11-005","lineIndex":5,"sourceLineIndex":5,"speaker":"","original":"Je paie tes dettes, tes robes, ton silence.","ipa":"/ʒˈə- pˈɛ tˈe- dˈɛt tˈe- ʁˈob tˈɔ̃ silˈɑ̃s/","zh":"我替你偿还债务，买下你的衣裙，也买下你的沉默。","en":"I pay your debts, your dresses, your silence.","note":"推定修订"},{"id":"la-dame-aux-camelias-11-051","lineIndex":6,"sourceLineIndex":6,"speaker":"","original":"Je signe en bas des traites de vengeance.","ipa":"/ʒˈə- sˈiɲ ˈɑ̃ bˈa dˈe- tʁˈɛt dˈə- vɑ̃ʒˈɑ̃s/","zh":"我在复仇的欠据末尾签下名字。","en":"I sign at the bottom of the bills of vengeance.","note":"推定修订"},{"id":"la-dame-aux-camelias-11-052","lineIndex":7,"sourceLineIndex":7,"speaker":"","original":"Tes froids mercis sont autant d’insolence.","ipa":"/tˈe- fʁwˈa mɛʁsˈi sˈɔ̃ otˈɑ̃ dɛ̃solˈɑ̃s/","zh":"你冷淡的道谢，一句句都是无礼。","en":"Your cold thank-yous are each an act of insolence.","note":"推定修订"},{"id":"la-dame-aux-camelias-11-053","lineIndex":8,"sourceLineIndex":8,"speaker":"","original":"Mais chaque sou me donne de l’espérance.","ipa":"/mˈɛ ʃˈak sˈu mˈə- dˈɔn dˈə- lɛspeʁˈɑ̃s/","zh":"但每一枚铜板都给我希望。","en":"But every penny gives me hope.","note":"推定修订"},{"id":"la-dame-aux-camelias-11-009","lineIndex":9,"sourceLineIndex":9,"speaker":"","original":"On dit que l’or fait plier les destinées.","ipa":"/ˈɔ̃ dˈi kˈə lˈɔʁ fˈɛ pliˈe lˈe- dɛstinˈe/","zh":"人们说，黄金能扭转命运。","en":"They say gold can bend the course of fate.","note":"推定修订"},{"id":"la-dame-aux-camelias-11-010","lineIndex":10,"sourceLineIndex":10,"speaker":"","original":"Mais il n’achète pas tes yeux fatigués.","ipa":"/mˈɛ ˈil naʃˈɛt pˈa tˈe- jˈø fatiɡˈe/","zh":"可它买不来你疲惫的双眼。","en":"But it cannot buy your tired eyes.","note":"推定修订"},{"id":"la-dame-aux-camelias-11-011","lineIndex":11,"sourceLineIndex":11,"speaker":"","original":"J’offre le ciel et les nuits enrubannées.","ipa":"/ʒˈɔfʁ lˈə- sjˈɛl ˈe lˈe- nyˈi ɑ̃ʁybanˈe/","zh":"我献上天空与缀满缎带的夜晚。","en":"I offer the sky and ribbon-adorned nights.","note":"推定修订"},{"id":"la-dame-aux-camelias-11-054","lineIndex":12,"sourceLineIndex":12,"speaker":"","original":"Tu lui préfères l’étreinte d’un gamin fauché.","ipa":"/tˈy lyˈi pʁefˈɛʁ letʁˈɛ̃t dˈœ̃ ɡamˈɛ̃ foʃˈe/","zh":"你却更愿投入一个穷小子的怀抱。","en":"Yet you prefer the embrace of a penniless boy.","note":"推定修订"},{"id":"la-dame-aux-camelias-11-055","lineIndex":13,"sourceLineIndex":13,"speaker":"","original":"Baron noir, baron noir, je règne sur des salons sans chaleur.","ipa":"/baʁˈɔ̃ nwˈaʁ baʁˈɔ̃ nwˈaʁ ʒˈə- ʁˈɛɲ sˈyʁ dˈe- salˈɔ̃ sˈɑ̃ ʃalˈœʁ/","zh":"黑男爵，黑男爵，我统治着没有温情的沙龙。","en":"Black Baron, Black Baron, I rule over salons without warmth.","note":"推定修订"},{"id":"la-dame-aux-camelias-11-056","lineIndex":14,"sourceLineIndex":14,"speaker":"","original":"Baron noir, baron noir, baron noir, baron noir, baron noir.","ipa":"/baʁˈɔ̃ nwˈaʁ baʁˈɔ̃ nwˈaʁ baʁˈɔ̃ nwˈaʁ baʁˈɔ̃ nwˈaʁ baʁˈɔ̃ nwˈaʁ/","zh":"黑男爵，黑男爵，黑男爵，黑男爵，黑男爵。","en":"Black Baron, Black Baron, Black Baron, Black Baron, Black Baron.","note":"推定修订"},{"id":"la-dame-aux-camelias-11-057","lineIndex":15,"sourceLineIndex":15,"speaker":"","original":"Mon amour est un bonheur, un malheur, je t’aime à en crever de douleur.","ipa":"/mˈɔ̃ amˈuʁ ˈɛ ˈœ̃ bɔnˈœʁ ˈœ̃ malˈœʁ ʒˈə- tˈɛm ˈa ˈɑ̃ kʁəvˈe dˈə- dulˈœʁ/","zh":"我的爱既是幸福也是痛苦；我爱你，爱得痛彻心扉。","en":"My love is both joy and sorrow; I love you until I could die of pain.","note":"推定修订"},{"id":"la-dame-aux-camelias-11-058","lineIndex":16,"sourceLineIndex":16,"speaker":"","original":"Dans mes rêves, c’est ton ombre que je vois ; les miroirs te reflètent sans que tu sois là.","ipa":"/dˈɑ̃ mˈe- ʁˈɛv sˈɛ tˈɔ̃ ˈɔ̃bʁ kˈə ʒˈə- vwˈa lˈe- miʁwˈaʁ tˈə- ʁəflˈɛt sˈɑ̃ kˈə tˈy swˈa lˈa/","zh":"在梦里，我看见的是你的影子；即使你不在，镜子仍映出你。","en":"In my dreams, it is your shadow I see; the mirrors reflect you even when you are not there.","note":"推定修订"},{"id":"la-dame-aux-camelias-11-059","lineIndex":17,"sourceLineIndex":17,"speaker":"","original":"Je hurle ton nom, les murs me le renvoient. En écho, mon cœur éclate dans un fracas.","ipa":"/ʒˈə- ˈyʁl tˈɔ̃ nˈɔ̃ lˈe- mˈyʁ mˈə- lˈə- ʁɑ̃vwˈa ˈɑ̃ ekˈo mˈɔ̃ kˈœʁ eklˈat dˈɑ̃ ˈœ̃ fʁakˈa/","zh":"我呼喊你的名字，墙壁将它回掷给我；在回声中，我的心轰然碎裂。","en":"I cry out your name; the walls throw it back to me. In the echo, my heart bursts with a crash.","note":"推定修订"},{"id":"la-dame-aux-camelias-11-060","lineIndex":18,"sourceLineIndex":18,"speaker":"","original":"Je brûle mes lettres avant de les lire. Les flammes dansent la valse d’autrefois.","ipa":"/ʒˈə- bʁˈyːl mˈe- lˈɛtʁ avˈɑ̃ dˈə- lˈe- lˈiʁ lˈe- flˈam dˈɑ̃s lˈa- vˈals dotʁəfwˈa/","zh":"我还没读信就将它们烧掉。火焰跳着昔日的圆舞曲。","en":"I burn my letters before reading them. The flames dance the waltz of days gone by.","note":"推定修订"},{"id":"la-dame-aux-camelias-11-061","lineIndex":19,"sourceLineIndex":19,"speaker":"","original":"Je reste assis, vieux roi sans empire, à nettoyer les cendres sur mes doigts.","ipa":"/ʒˈə- ʁˈɛst asˈi vjˈø ʁwˈa sˈɑ̃ ɑ̃pˈiʁ ˈa nɛtwajˈe lˈe- sˈɑ̃dʁ sˈyʁ mˈe- dwˈa/","zh":"我仍坐在那里，像个失去帝国的老国王，拂去指尖的灰烬。","en":"I remain seated, an old king without an empire, cleaning the ashes from my fingers.","note":"推定修订"},{"id":"la-dame-aux-camelias-11-062","lineIndex":20,"sourceLineIndex":20,"speaker":"","original":"Je t’ai ouvert la porte de la haute société.","ipa":"/ʒˈə- tˈe uvˈɛʁ lˈa- pˈɔʁt dˈə- lˈa- ˈot sosjetˈe/","zh":"是我为你打开了上流社会的大门。","en":"I opened the door to high society for you.","note":"推定修订"},{"id":"la-dame-aux-camelias-11-063","lineIndex":21,"sourceLineIndex":21,"speaker":"","original":"Je t’ai appris comment les nobles se comportent.","ipa":"/ʒˈə- tˈe apʁˈi kɔmˈɑ̃ lˈe- nˈɔbl sˈə- kɔ̃pˈɔʁt/","zh":"是我教会你贵族如何举止行事。","en":"I taught you how the nobles behave.","note":"推定修订"},{"id":"la-dame-aux-camelias-11-064","lineIndex":22,"sourceLineIndex":22,"speaker":"","original":"J’ai souri, payé, j’ai tout signé.","ipa":"/ʒˈe suʁˈi pɛjˈe ʒˈe tˈu sinjˈe/","zh":"我微笑、付钱，把一切都签了下来。","en":"I smiled, paid, and signed everything.","note":"推定修订"},{"id":"la-dame-aux-camelias-11-065","lineIndex":23,"sourceLineIndex":23,"speaker":"","original":"Et là, j’attends qu’un autre que moi t’emporte.","ipa":"/ˈe lˈa ʒatˈɑ̃ kˈœ̃ ˈotʁ kˈə mwˈa tɑ̃pˈɔʁt/","zh":"而如今，我等着另一个人把你带走。","en":"And now I wait for someone other than me to carry you away.","note":"推定修订"},{"id":"la-dame-aux-camelias-11-013","lineIndex":24,"sourceLineIndex":24,"speaker":"","original":"Baron noir, baron noir.","ipa":"/baʁˈɔ̃ nwˈaʁ baʁˈɔ̃ nwˈaʁ/","zh":"黑男爵，黑男爵。","en":"Black Baron, Black Baron.","note":"推定修订"},{"id":"la-dame-aux-camelias-11-014","lineIndex":25,"sourceLineIndex":25,"speaker":"","original":"Je règne sur des salons sans chaleur.","ipa":"/ʒˈə- ʁˈɛɲ sˈyʁ dˈe- salˈɔ̃ sˈɑ̃ ʃalˈœʁ/","zh":"我统治着没有温情的沙龙。","en":"I rule over salons without warmth.","note":"推定修订"},{"id":"la-dame-aux-camelias-11-066","lineIndex":26,"sourceLineIndex":26,"speaker":"","original":"Baron noir, baron noir, baron noir.","ipa":"/baʁˈɔ̃ nwˈaʁ baʁˈɔ̃ nwˈaʁ baʁˈɔ̃ nwˈaʁ/","zh":"黑男爵，黑男爵，黑男爵。","en":"Black Baron, Black Baron, Black Baron.","note":"推定修订"},{"id":"la-dame-aux-camelias-11-015","lineIndex":27,"sourceLineIndex":27,"speaker":"","original":"Baron noir, baron noir.","ipa":"/baʁˈɔ̃ nwˈaʁ baʁˈɔ̃ nwˈaʁ/","zh":"黑男爵，黑男爵。","en":"Black Baron, Black Baron.","note":"推定修订"},{"id":"la-dame-aux-camelias-11-067","lineIndex":28,"sourceLineIndex":28,"speaker":"","original":"Mon amour est un bonheur, un malheur.","ipa":"/mˈɔ̃ amˈuʁ ˈɛ ˈœ̃ bɔnˈœʁ ˈœ̃ malˈœʁ/","zh":"我的爱既是幸福也是痛苦。","en":"My love is both joy and sorrow.","note":"推定修订"},{"id":"la-dame-aux-camelias-11-018","lineIndex":29,"sourceLineIndex":29,"speaker":"","original":"Je t’aime à en crever de douleur.","ipa":"/ʒˈə- tˈɛm ˈa ˈɑ̃ kʁəvˈe dˈə- dulˈœʁ/","zh":"我爱你，爱得痛彻心扉。","en":"I love you until I could die of pain.","note":"推定修订"},{"id":"la-dame-aux-camelias-11-068","lineIndex":30,"sourceLineIndex":30,"speaker":"","original":"Un jour, tu frapperas ma porte, pâle et tremblante.","ipa":"/ˈœ̃ ʒˈuʁ tˈy fʁapʁˈa mˈa- pˈɔʁt pˈaːl ˈe tʁɑ̃blˈɑ̃t/","zh":"有一天，你会苍白而颤抖地敲响我的门。","en":"One day you will knock on my door, pale and trembling.","note":"推定修订"},{"id":"la-dame-aux-camelias-11-038","lineIndex":31,"sourceLineIndex":31,"speaker":"","original":"La maladie aura gagné la partie.","ipa":"/lˈa- maladˈi oʁˈa ɡanjˈe lˈa- paʁtˈi/","zh":"疾病终将赢下这场较量。","en":"Illness will have won the game.","note":"推定修订"},{"id":"la-dame-aux-camelias-11-039","lineIndex":32,"sourceLineIndex":32,"speaker":"","original":"Je pleurerai comme un enfant en silence.","ipa":"/ʒˈə- pløʁʁˈe kˈɔm ˈœ̃ ɑ̃fˈɑ̃ ˈɑ̃ silˈɑ̃s/","zh":"我会像孩子一样默默哭泣。","en":"I will weep silently like a child.","note":"推定修订"},{"id":"la-dame-aux-camelias-11-040","lineIndex":33,"sourceLineIndex":33,"speaker":"","original":"Mais libéré de ton indifférence.","ipa":"/mˈɛ libeʁˈe dˈə- tˈɔ̃ ɛ̃difeʁˈɑ̃s/","zh":"但终于摆脱你的冷漠。","en":"But freed from your indifference.","note":"推定修订"},{"id":"la-dame-aux-camelias-11-041","lineIndex":34,"sourceLineIndex":34,"speaker":"","original":"Baron noir, Baron noir.","ipa":"/baʁˈɔ̃ nwˈaʁ baʁˈɔ̃ nwˈaʁ/","zh":"黑男爵，黑男爵。","en":"Black Baron, Black Baron.","note":"推定修订"},{"id":"la-dame-aux-camelias-11-042","lineIndex":35,"sourceLineIndex":35,"speaker":"","original":"Enterre-moi sous tes camélias blancs.","ipa":"/ɑ̃tˈɛʁmwˈa sˈu tˈe- kameljˈa blˈɑ̃/","zh":"把我埋在你的白茶花之下。","en":"Bury me beneath your white camellias.","note":"推定修订"},{"id":"la-dame-aux-camelias-11-043","lineIndex":36,"sourceLineIndex":36,"speaker":"","original":"Baron noir, Baron noir.","ipa":"/baʁˈɔ̃ nwˈaʁ baʁˈɔ̃ nwˈaʁ/","zh":"黑男爵，黑男爵。","en":"Black Baron, Black Baron.","note":"推定修订"},{"id":"la-dame-aux-camelias-11-069","lineIndex":37,"sourceLineIndex":37,"speaker":"","original":"Ton seul bourreau était ton amant.","ipa":"/tˈɔ̃ sˈœl buʁˈo etˈɛ tˈɔ̃ amˈɑ̃/","zh":"你唯一的折磨者，曾是你的情人。","en":"Your only tormentor was your lover.","note":"推定修订"},{"id":"la-dame-aux-camelias-11-046","lineIndex":38,"sourceLineIndex":38,"speaker":"","original":"Tout est deuil, même les fleurs sont mortes.","ipa":"/tˈu ˈɛ dˈœj mˈɛm lˈe- flˈœʁ sˈɔ̃ mˈɔʁt/","zh":"一切都成了哀悼，连花朵也已枯死。","en":"Everything is mourning; even the flowers are dead.","note":"推定修订"}],"sourceOrder":11,"displayOrder":11},{"order":12,"id":"12-la-valse-des-conseils","title":"La valse des conseils","titleZh":"忠告圆舞曲","lines":[{"id":"la-dame-aux-camelias-12-001","lineIndex":1,"sourceLineIndex":1,"speaker":"","original":"Un vent nouveau souffle sur mon cœur.","ipa":"/ˈœ̃ vˈɑ̃ nuvˈo sˈufl sˈyʁ mˈɔ̃ kˈœʁ/","zh":"一阵新的风吹拂着我的心。","en":"A new wind is blowing over my heart.","note":"推定修订"},{"id":"la-dame-aux-camelias-12-002","lineIndex":2,"sourceLineIndex":2,"speaker":"","original":"Je veux fuir loin des rumeurs.","ipa":"/ʒˈə- vˈø fyˈiʁ lwˈɛ̃ dˈe- ʁymˈœʁ/","zh":"我想远离流言蜚语。","en":"I want to flee far from the rumors.","note":"推定修订"},{"id":"la-dame-aux-camelias-12-003","lineIndex":3,"sourceLineIndex":3,"speaker":"","original":"Mais vos voix me font douter.","ipa":"/mˈɛ vˈo vwˈa mˈə- fˈɔ̃ dutˈe/","zh":"可你们的声音让我犹疑。","en":"But your voices make me doubt.","note":"推定修订"},{"id":"la-dame-aux-camelias-12-004","lineIndex":4,"sourceLineIndex":4,"speaker":"","original":"Paris ou l'amour, quoi écouter ?","ipa":"/paʁˈi ˈu lamˈuʁ kwˈa ekutˈe/","zh":"巴黎还是爱情，我该听从哪一边？","en":"Paris or love—which should I listen to?","note":"推定修订"},{"id":"la-dame-aux-camelias-12-005","lineIndex":5,"sourceLineIndex":5,"speaker":"","original":"La campagne, quelle faute de chansons.","ipa":"/lˈa- kɑ̃pˈaɲ kˈɛl fˈot dˈə- ʃɑ̃sˈɔ̃/","zh":"乡间，歌曲竟如此匮乏。","en":"The countryside—what a shortage of songs.","note":"推定修订"},{"id":"la-dame-aux-camelias-12-006","lineIndex":6,"sourceLineIndex":6,"speaker":"","original":"Pas de salon, pas de frissons.","ipa":"/pˈa dˈə- salˈɔ̃ pˈa dˈə- fʁisˈɔ̃/","zh":"没有沙龙，也没有心动。","en":"No salon, no thrills.","note":"推定修订"},{"id":"la-dame-aux-camelias-12-007","lineIndex":7,"sourceLineIndex":7,"speaker":"","original":"Paris pulse, la vie pétille.","ipa":"/paʁˈi pˈyls lˈa- vˈi petˈij/","zh":"巴黎脉动，生活闪闪发亮。","en":"Paris pulses; life sparkles.","note":"推定修订"},{"id":"la-dame-aux-camelias-12-008","lineIndex":8,"sourceLineIndex":8,"speaker":"","original":"Reste ici, là où tout brille.","ipa":"/ʁˈɛst isˈi lˈa ˈu tˈu bʁˈij/","zh":"留在这里，留在万物闪耀的地方。","en":"Stay here, where everything shines.","note":"推定修订"},{"id":"la-dame-aux-camelias-12-009","lineIndex":9,"sourceLineIndex":9,"speaker":"","original":"Paris est toujours si cruel.","ipa":"/paʁˈi ˈɛ tuʒˈuʁ sˈi kʁyˈɛl/","zh":"巴黎总是如此无情。","en":"Paris is always so cruel.","note":"推定修订"},{"id":"la-dame-aux-camelias-12-010","lineIndex":10,"sourceLineIndex":10,"speaker":"","original":"La campagne et le bonheur m'appellent.","ipa":"/lˈa- kɑ̃pˈaɲ ˈe lˈə- bɔnˈœʁ mapˈɛl/","zh":"乡间与幸福正呼唤着我。","en":"The countryside and happiness are calling me.","note":"推定修订"},{"id":"la-dame-aux-camelias-12-011","lineIndex":11,"sourceLineIndex":11,"speaker":"","original":"Marguerite, choisis ton destin : la vie ou l'amour clandestin.","ipa":"/maʁɡəʁˈit ʃwazˈi tˈɔ̃ dɛstˈɛ̃ lˈa- vˈi ˈu lamˈuʁ klɑ̃dɛstˈɛ̃/","zh":"玛格丽特，选择你的命运：生活，还是秘密的爱情。","en":"Marguerite, choose your fate: life or forbidden love.","note":"推定修订"},{"id":"la-dame-aux-camelias-12-012","lineIndex":12,"sourceLineIndex":12,"speaker":"","original":"Pense à l'argent, à mes dépenses, et méfie-toi de la concurrence.","ipa":"/pˈɑ̃s ˈa laʁʒˈɑ̃ ˈa mˈe- depˈɑ̃s ˈe mefˈitwˈa dˈə- lˈa- kɔ̃kyʁˈɑ̃s/","zh":"想想钱，也想想我的开销，还要提防竞争者。","en":"Think of the money, of my expenses, and beware the competition.","note":"推定修订"},{"id":"la-dame-aux-camelias-12-013","lineIndex":13,"sourceLineIndex":13,"speaker":"","original":"Reste à Paris, où tout se vend. La campagne, c'est si décevant.","ipa":"/ʁˈɛst ˈa paʁˈi ˈu tˈu sˈə- vˈɑ̃ lˈa- kɑ̃pˈaɲ sˈɛ sˈi desəvˈɑ̃/","zh":"留在巴黎吧，那里什么都能买到。乡间实在令人失望。","en":"Stay in Paris, where everything is for sale. The countryside is so disappointing.","note":"推定修订"},{"id":"la-dame-aux-camelias-12-014","lineIndex":14,"sourceLineIndex":14,"speaker":"","original":"Paris est toujours si cruel ; la campagne et le bonheur m'appellent.","ipa":"/paʁˈi ˈɛ tuʒˈuʁ sˈi kʁyˈɛl lˈa- kɑ̃pˈaɲ ˈe lˈə- bɔnˈœʁ mapˈɛl/","zh":"巴黎总是如此无情；乡间与幸福正呼唤着我。","en":"Paris is always so cruel; the countryside and happiness are calling me.","note":"推定修订"},{"id":"la-dame-aux-camelias-12-015","lineIndex":15,"sourceLineIndex":15,"speaker":"","original":"Marguerite, choisis ton destin : la vie ou l'amour clandestin.","ipa":"/maʁɡəʁˈit ʃwazˈi tˈɔ̃ dɛstˈɛ̃ lˈa- vˈi ˈu lamˈuʁ klɑ̃dɛstˈɛ̃/","zh":"玛格丽特，选择你的命运：生活，还是秘密的爱情。","en":"Marguerite, choose your fate: life or forbidden love.","note":"推定修订"},{"id":"la-dame-aux-camelias-12-016","lineIndex":16,"sourceLineIndex":16,"speaker":"","original":"Quitte Paris, prends ton amant. Laisse-moi la ville et ses élans.","ipa":"/kˈit paʁˈi pʁˈɑ̃ tˈɔ̃ amˈɑ̃ lˈɛsmwˈa lˈa- vˈil ˈe sˈe- elˈɑ̃/","zh":"离开巴黎，带上你的情人。把这座城和它的激情留给我。","en":"Leave Paris, take your lover. Leave me the city and its passions.","note":"推定修订"},{"id":"la-dame-aux-camelias-12-017","lineIndex":17,"sourceLineIndex":17,"speaker":"","original":"Je règne, seule, en reine des passions, pour assouvir mes ambitions.","ipa":"/ʒˈə- ʁˈɛɲ sˈœl ˈɑ̃ ʁˈɛn dˈe- pasjˈɔ̃ pˈuʁ asuvˈiʁ mˈe- ɑ̃bisjˈɔ̃/","zh":"我独自统领情欲，化身激情女王，实现我的野心。","en":"I reign alone as queen of passions, to fulfill my ambitions.","note":"推定修订"},{"id":"la-dame-aux-camelias-12-018","lineIndex":18,"sourceLineIndex":18,"speaker":"","original":"Paris est toujours si cruel ; la campagne et le bonheur m'appellent.","ipa":"/paʁˈi ˈɛ tuʒˈuʁ sˈi kʁyˈɛl lˈa- kɑ̃pˈaɲ ˈe lˈə- bɔnˈœʁ mapˈɛl/","zh":"巴黎总是如此无情；幸福的乡间正呼唤着我。","en":"Paris is always so cruel; the countryside of happiness is calling me.","note":"推定修订"},{"id":"la-dame-aux-camelias-12-019","lineIndex":19,"sourceLineIndex":19,"speaker":"","original":"Marguerite, choisis ton destin : la vie ou l'amour clandestin.","ipa":"/maʁɡəʁˈit ʃwazˈi tˈɔ̃ dɛstˈɛ̃ lˈa- vˈi ˈu lamˈuʁ klɑ̃dɛstˈɛ̃/","zh":"玛格丽特，选择你的命运：生活，还是秘密的爱情。","en":"Marguerite, choose your fate: life or forbidden love.","note":"推定修订"},{"id":"la-dame-aux-camelias-12-020","lineIndex":20,"sourceLineIndex":20,"speaker":"","original":"Un espoir se pose sur mon cœur ; Armand est là, loin des rumeurs.","ipa":"/ˈœ̃ ɛspwˈaʁ sˈə- pˈɔz sˈyʁ mˈɔ̃ kˈœʁ aʁmˈɑ̃ ˈɛ lˈa lwˈɛ̃ dˈe- ʁymˈœʁ/","zh":"希望落在我的心上；阿尔芒就在这里，远离流言。","en":"A hope settles on my heart; Armand is here, far from the rumors.","note":"推定修订"},{"id":"la-dame-aux-camelias-12-021","lineIndex":21,"sourceLineIndex":21,"speaker":"","original":"Plus rien, plus rien ne me fait douter ; Paris ou l'amour, mon choix est fait.","ipa":"/plˈy ʁiˈɛ̃ plˈy ʁiˈɛ̃ nˈə- mˈə- fˈɛ dutˈe paʁˈi ˈu lamˈuʁ mˈɔ̃ ʃwˈa ˈɛ fˈɛ/","zh":"再没有什么能让我犹疑；巴黎还是爱情，我已经作出选择。","en":"Nothing, nothing makes me doubt anymore; Paris or love, my choice is made.","note":"推定修订"},{"id":"la-dame-aux-camelias-12-022","lineIndex":22,"sourceLineIndex":22,"speaker":"","original":"Nos voies mêlées sont celles de cœurs trop contrariés.","ipa":"/nˈo vwˈa mɛlˈe sˈɔ̃ sˈɛl dˈə- kˈœʁ tʁˈo kɔ̃tʁaʁjˈe/","zh":"我们交织的道路，属于太多矛盾交织的心。","en":"Our intertwined paths belong to hearts too conflicted.","note":"推定修订"},{"id":"la-dame-aux-camelias-12-023","lineIndex":23,"sourceLineIndex":23,"speaker":"","original":"Paris sera toujours là pour nous consoler.","ipa":"/paʁˈi səʁˈa tuʒˈuʁ lˈa pˈuʁ nˈu kɔ̃solˈe/","zh":"巴黎永远会在那里安慰我们。","en":"Paris will always be there to console us.","note":"推定修订"},{"id":"la-dame-aux-camelias-12-024","lineIndex":24,"sourceLineIndex":24,"speaker":"","original":"La vie est souvent si cruelle, mais j'entends une ritournelle dont chaque note est un appel vers une aventure nouvelle.","ipa":"/lˈa- vˈi ˈɛ suvˈɑ̃ sˈi kʁyˈɛl mˈɛ ʒɑ̃tˈɑ̃ ˈyn ʁituʁnˈɛl dˈɔ̃ ʃˈak nˈɔt ˈɛ ˈœ̃ apˈɛl vˈɛʁ ˈyn avɑ̃tˈyʁ nuvˈɛl/","zh":"生活常常如此残酷，但我听见一支反复的旋律，每个音符都在召唤一场新的冒险。","en":"Life is often so cruel, but I hear a refrain, each note calling toward a new adventure.","note":"推定修订"},{"id":"la-dame-aux-camelias-12-025","lineIndex":25,"sourceLineIndex":25,"speaker":"","original":"Marguerite, choisis ton destin : la vie ou l'amour clandestin.","ipa":"/maʁɡəʁˈit ʃwazˈi tˈɔ̃ dɛstˈɛ̃ lˈa- vˈi ˈu lamˈuʁ klɑ̃dɛstˈɛ̃/","zh":"玛格丽特，选择你的命运：生活，还是秘密的爱情。","en":"Marguerite, choose your fate: life or forbidden love.","note":"推定修订"},{"id":"la-dame-aux-camelias-12-026","lineIndex":26,"sourceLineIndex":26,"speaker":"","original":"Adieu, Paris, adieu les nuits qui ensorcellent.","ipa":"/adjˈø paʁˈi adjˈø lˈe- nyˈi kˈi ɑ̃sɔʁsˈɛl/","zh":"再见，巴黎；再见，那些令人沉醉的夜晚。","en":"Farewell, Paris; farewell, enchanting nights.","note":"推定修订"},{"id":"la-dame-aux-camelias-12-027","lineIndex":27,"sourceLineIndex":27,"speaker":"","original":"La campagne et le bonheur m'appellent.","ipa":"/lˈa- kɑ̃pˈaɲ ˈe lˈə- bɔnˈœʁ mapˈɛl/","zh":"乡间与幸福正呼唤着我。","en":"The countryside and happiness are calling me.","note":"推定修订"}],"sourceOrder":12,"displayOrder":12},{"order":15,"id":"15-reset","title":"Reset","titleZh":"重启","lines":[{"id":"la-dame-aux-camelias-15-053","lineIndex":1,"sourceLineIndex":1,"speaker":"","original":"J’ai laissé ma voix traîner un peu partout, un peu partout.","ipa":"/ʒˈe lɛsˈe mˈa- vwˈa tʁɛnˈe ˈœ̃ pˈø paʁtˈu ˈœ̃ pˈø paʁtˈu/","zh":"我让自己的声音四处游荡，四处游荡。","en":"I let my voice wander everywhere, everywhere.","note":"推定修订"},{"id":"la-dame-aux-camelias-15-054","lineIndex":2,"sourceLineIndex":2,"speaker":"","original":"J’ai laissé mes pas traîner un peu partout, un peu partout.","ipa":"/ʒˈe lɛsˈe mˈe- pˈa tʁɛnˈe ˈœ̃ pˈø paʁtˈu ˈœ̃ pˈø paʁtˈu/","zh":"我让自己的脚步四处游荡，四处游荡。","en":"I let my footsteps wander everywhere, everywhere.","note":"推定修订"},{"id":"la-dame-aux-camelias-15-055","lineIndex":3,"sourceLineIndex":3,"speaker":"","original":"Et j’ai laissé mes yeux poser, j’ai laissé mes mains oser.","ipa":"/ˈe ʒˈe lɛsˈe mˈe- jˈø pozˈe ʒˈe lɛsˈe mˈe- mˈɛ̃ ozˈe/","zh":"我让目光停驻，也让双手大胆起来。","en":"And I let my eyes settle; I let my hands dare.","note":"推定修订"},{"id":"la-dame-aux-camelias-15-056","lineIndex":4,"sourceLineIndex":4,"speaker":"","original":"J’ai laissé mon corps traîner un peu partout.","ipa":"/ʒˈe lɛsˈe mˈɔ̃ kˈɔʁ tʁɛnˈe ˈœ̃ pˈø paʁtˈu/","zh":"我让身体四处游荡。","en":"I let my body wander everywhere.","note":"推定修订"},{"id":"la-dame-aux-camelias-15-057","lineIndex":5,"sourceLineIndex":5,"speaker":"","original":"Je fais risette, j’ai la recette risette.","ipa":"/ʒˈə- fˈɛ ʁizˈɛt ʒˈe lˈa- ʁəsˈɛt ʁizˈɛt/","zh":"我露出浅浅的笑，自有微笑的秘诀。","en":"I smile; I have the recipe for a little smile.","note":"推定修订"},{"id":"la-dame-aux-camelias-15-058","lineIndex":6,"sourceLineIndex":6,"speaker":"","original":"Pour toi, j’accepte risette.","ipa":"/pˈuʁ twˈa ʒaksˈɛpt ʁizˈɛt/","zh":"为了你，我接受这浅浅一笑。","en":"For you, I accept a little smile.","note":"推定修订"},{"id":"la-dame-aux-camelias-15-059","lineIndex":7,"sourceLineIndex":7,"speaker":"","original":"De mon âme, de mon corps, je laisse…","ipa":"/dˈə- mˈɔ̃ ˈaːm dˈə- mˈɔ̃ kˈɔʁ ʒˈə- lˈɛs/","zh":"我的灵魂，我的身体，都交付出去……","en":"From my soul, from my body, I leave…","note":"推定修订"},{"id":"la-dame-aux-camelias-15-060","lineIndex":8,"sourceLineIndex":8,"speaker":"","original":"Je fais risette.","ipa":"/ʒˈə- fˈɛ ʁizˈɛt/","zh":"我浅浅一笑。","en":"I smile a little.","note":"推定修订"},{"id":"la-dame-aux-camelias-15-061","lineIndex":9,"sourceLineIndex":9,"speaker":"","original":"Pour toi, j’accepte risette.","ipa":"/pˈuʁ twˈa ʒaksˈɛpt ʁizˈɛt/","zh":"为了你，我接受这浅浅一笑。","en":"For you, I accept a little smile.","note":"推定修订"},{"id":"la-dame-aux-camelias-15-015","lineIndex":10,"sourceLineIndex":10,"speaker":"","original":"Pour toi, j’accepte…","ipa":"/pˈuʁ twˈa ʒaksˈɛpt/","zh":"为了你，我接受……","en":"For you, I accept…","note":"推定修订"},{"id":"la-dame-aux-camelias-15-016","lineIndex":11,"sourceLineIndex":11,"speaker":"","original":"Pour toi, je reste.","ipa":"/pˈuʁ twˈa ʒˈə- ʁˈɛst/","zh":"为了你，我留下。","en":"For you, I stay.","note":"推定修订"},{"id":"la-dame-aux-camelias-15-017","lineIndex":12,"sourceLineIndex":12,"speaker":"","original":"Je vois l’amour, enfin, et je le teste.","ipa":"/ʒˈə- vwˈa lamˈuʁ ɑ̃fˈɛ̃ ˈe ʒˈə- lˈə- tˈɛst/","zh":"终于，我看见了爱情，也试着检验它。","en":"At last I see love, and I test it.","note":"推定修订"},{"id":"la-dame-aux-camelias-15-062","lineIndex":13,"sourceLineIndex":13,"speaker":"","original":"J’ai laissé mes rêves planer, un peu partout, un peu partout.","ipa":"/ʒˈe lɛsˈe mˈe- ʁˈɛv planˈe ˈœ̃ pˈø paʁtˈu ˈœ̃ pˈø paʁtˈu/","zh":"我让梦想四处飘荡，四处飘荡。","en":"I let my dreams drift everywhere, everywhere.","note":"推定修订"},{"id":"la-dame-aux-camelias-15-063","lineIndex":14,"sourceLineIndex":14,"speaker":"","original":"J’ai laissé mes lèvres traîner, un peu partout, un peu partout.","ipa":"/ʒˈe lɛsˈe mˈe- lˈɛvʁ tʁɛnˈe ˈœ̃ pˈø paʁtˈu ˈœ̃ pˈø paʁtˈu/","zh":"我让双唇四处流连，四处流连。","en":"I let my lips linger everywhere, everywhere.","note":"推定修订"},{"id":"la-dame-aux-camelias-15-064","lineIndex":15,"sourceLineIndex":15,"speaker":"","original":"J’ai laissé mes doigts glisser, j’ai laissé mes reins danser.","ipa":"/ʒˈe lɛsˈe mˈe- dwˈa ɡlisˈe ʒˈe lɛsˈe mˈe- ʁˈɛ̃ dɑ̃sˈe/","zh":"我让手指滑过，也让腰肢起舞。","en":"I let my fingers glide; I let my hips dance.","note":"推定修订"},{"id":"la-dame-aux-camelias-15-065","lineIndex":16,"sourceLineIndex":16,"speaker":"","original":"On va couler un peu partout.","ipa":"/ˈɔ̃ vˈa kulˈe ˈœ̃ pˈø paʁtˈu/","zh":"我们要四处流淌。","en":"We will flow everywhere.","note":"推定修订"},{"id":"la-dame-aux-camelias-15-066","lineIndex":17,"sourceLineIndex":17,"speaker":"","original":"Je fais risette, j’ai la recette.","ipa":"/ʒˈə- fˈɛ ʁizˈɛt ʒˈe lˈa- ʁəsˈɛt/","zh":"我浅浅一笑，自有秘诀。","en":"I smile; I have the recipe.","note":"推定修订"},{"id":"la-dame-aux-camelias-15-067","lineIndex":18,"sourceLineIndex":18,"speaker":"","original":"Risette, pour toi, j’accepte.","ipa":"/ʁizˈɛt pˈuʁ twˈa ʒaksˈɛpt/","zh":"浅浅一笑；为了你，我接受。","en":"A little smile; for you, I accept.","note":"推定修订"},{"id":"la-dame-aux-camelias-15-068","lineIndex":19,"sourceLineIndex":19,"speaker":"","original":"Risette de mon âme, de mon corps.","ipa":"/ʁizˈɛt dˈə- mˈɔ̃ ˈaːm dˈə- mˈɔ̃ kˈɔʁ/","zh":"浅浅一笑，来自我的灵魂与身体。","en":"A little smile from my soul, from my body.","note":"推定修订"},{"id":"la-dame-aux-camelias-15-069","lineIndex":20,"sourceLineIndex":20,"speaker":"","original":"Je laisse, je fais risette.","ipa":"/ʒˈə- lˈɛs ʒˈə- fˈɛ ʁizˈɛt/","zh":"我放手，露出浅浅的笑。","en":"I let go; I smile a little.","note":"推定修订"},{"id":"la-dame-aux-camelias-15-070","lineIndex":21,"sourceLineIndex":21,"speaker":"","original":"Pour toi, j’accepte, risette.","ipa":"/pˈuʁ twˈa ʒaksˈɛpt ʁizˈɛt/","zh":"为了你，我接受这抹浅笑。","en":"For you, I accept this little smile.","note":"推定修订"},{"id":"la-dame-aux-camelias-15-071","lineIndex":22,"sourceLineIndex":22,"speaker":"","original":"Pour toi, j’accepte, pour toi, je reste.","ipa":"/pˈuʁ twˈa ʒaksˈɛpt pˈuʁ twˈa ʒˈə- ʁˈɛst/","zh":"为了你，我接受；为了你，我留下。","en":"For you, I accept; for you, I stay.","note":"推定修订"},{"id":"la-dame-aux-camelias-15-034","lineIndex":23,"sourceLineIndex":23,"speaker":"","original":"Je vois l’amour, enfin, et je le teste.","ipa":"/ʒˈə- vwˈa lamˈuʁ ɑ̃fˈɛ̃ ˈe ʒˈə- lˈə- tˈɛst/","zh":"终于，我看见了爱情，也试着检验它。","en":"At last I see love, and I test it.","note":"推定修订"},{"id":"la-dame-aux-camelias-15-072","lineIndex":24,"sourceLineIndex":24,"speaker":"","original":"Une fois pour la pensée, une fois pour le corps.","ipa":"/ˈyn fwˈa pˈuʁ lˈa- pɑ̃sˈe ˈyn fwˈa pˈuʁ lˈə- kˈɔʁ/","zh":"一次为了思想，一次为了身体。","en":"Once for the mind, once for the body.","note":"推定修订"},{"id":"la-dame-aux-camelias-15-073","lineIndex":25,"sourceLineIndex":25,"speaker":"","original":"Depuis que je t’ai rencontré, j’ai changé de décor.","ipa":"/dəpyˈi kˈə ʒˈə- tˈe ʁɑ̃kɔ̃tʁˈe ʒˈe ʃɑ̃ʒˈe dˈə- dekˈɔʁ/","zh":"自从遇见你，我便换了生活场景。","en":"Since I met you, I have changed my scenery.","note":"推定修订"},{"id":"la-dame-aux-camelias-15-039","lineIndex":26,"sourceLineIndex":26,"speaker":"","original":"Je veux un reset.","ipa":"/ʒˈə- vˈø ˈœ̃ ʁəzˈɛ/","zh":"我想要一次重置。","en":"I want a reset.","note":"推定修订"},{"id":"la-dame-aux-camelias-15-074","lineIndex":27,"sourceLineIndex":27,"speaker":"","original":"Je fais risette, j’ai la recette risette.","ipa":"/ʒˈə- fˈɛ ʁizˈɛt ʒˈe lˈa- ʁəsˈɛt ʁizˈɛt/","zh":"我露出浅浅的笑，自有微笑的秘诀。","en":"I smile; I have the recipe for a little smile.","note":"推定修订"},{"id":"la-dame-aux-camelias-15-075","lineIndex":28,"sourceLineIndex":28,"speaker":"","original":"Pour toi, j’ai cette risette.","ipa":"/pˈuʁ twˈa ʒˈe sˈɛt ʁizˈɛt/","zh":"为了你，我有这抹浅笑。","en":"For you, I have this little smile.","note":"推定修订"},{"id":"la-dame-aux-camelias-15-076","lineIndex":29,"sourceLineIndex":29,"speaker":"","original":"De mon âme, de mon corps, je laisse…","ipa":"/dˈə- mˈɔ̃ ˈaːm dˈə- mˈɔ̃ kˈɔʁ ʒˈə- lˈɛs/","zh":"我的灵魂，我的身体，都交付出去……","en":"From my soul, from my body, I leave…","note":"推定修订"},{"id":"la-dame-aux-camelias-15-077","lineIndex":30,"sourceLineIndex":30,"speaker":"","original":"Je fais risette, toi…","ipa":"/ʒˈə- fˈɛ ʁizˈɛt twˈa/","zh":"我浅浅一笑，你……","en":"I smile a little, you…","note":"推定修订"},{"id":"la-dame-aux-camelias-15-078","lineIndex":31,"sourceLineIndex":31,"speaker":"","original":"Pour toi, j’ai cette risette.","ipa":"/pˈuʁ twˈa ʒˈe sˈɛt ʁizˈɛt/","zh":"为了你，我有这抹浅笑。","en":"For you, I have this little smile.","note":"推定修订"},{"id":"la-dame-aux-camelias-15-079","lineIndex":32,"sourceLineIndex":32,"speaker":"","original":"Recours, reset, pour toi j’accepte, pour toi je reste.","ipa":"/ʁəkˈuʁ ʁəzˈɛ pˈuʁ twˈa ʒaksˈɛpt pˈuʁ twˈa ʒˈə- ʁˈɛst/","zh":"求助，重置；为了你我接受，为了你我留下。","en":"Recourse, reset; for you I accept, for you I stay.","note":"推定修订"},{"id":"la-dame-aux-camelias-15-080","lineIndex":33,"sourceLineIndex":33,"speaker":"","original":"Je vois l’amour, enfin, les jeunes testent.","ipa":"/ʒˈə- vwˈa lamˈuʁ ɑ̃fˈɛ̃ lˈe- ʒˈøn tˈɛst/","zh":"终于我看见了爱情，年轻人正在试探它。","en":"At last I see love; the young ones test it.","note":"推定修订"}],"sourceOrder":15,"displayOrder":15},{"order":18,"id":"18-je-t-aime-mais-je-pars","title":"Je t'aime mais je pars","titleZh":"我爱你，但我离去","lines":[{"id":"la-dame-aux-camelias-18-001","lineIndex":1,"sourceLineIndex":1,"speaker":"","original":"Pour toi, je m'efface.","ipa":"/pˈuʁ twˈa ʒˈə- mefˈas/","zh":"为了你，我悄然退场。","en":"For you, I fade away.","note":"推定修订"},{"id":"la-dame-aux-camelias-18-002","lineIndex":2,"sourceLineIndex":2,"speaker":"","original":"Sans laisser de traces.","ipa":"/sˈɑ̃ lɛsˈe dˈə- tʁˈas/","zh":"不留下一丝痕迹。","en":"Without leaving a trace.","note":"推定修订"},{"id":"la-dame-aux-camelias-18-003","lineIndex":3,"sourceLineIndex":3,"speaker":"","original":"Je tourne la page.","ipa":"/ʒˈə- tˈuʁn lˈa- pˈaʒ/","zh":"我翻过这一页。","en":"I turn the page.","note":"推定修订"},{"id":"la-dame-aux-camelias-18-004","lineIndex":4,"sourceLineIndex":4,"speaker":"","original":"Et garde pour mon naufrage.","ipa":"/ˈe ɡˈaʁd pˈuʁ mˈɔ̃ nofʁˈaʒ/","zh":"并为我的沉沦留下……。","en":"And save it for my shipwreck.","note":"推定修订"},{"id":"la-dame-aux-camelias-18-005","lineIndex":5,"sourceLineIndex":5,"speaker":"","original":"Pour toi, je laisse la place.","ipa":"/pˈuʁ twˈa ʒˈə- lˈɛs lˈa- plˈas/","zh":"为了你，我让出位置。","en":"For you, I make room.","note":"推定修订"},{"id":"la-dame-aux-camelias-18-006","lineIndex":6,"sourceLineIndex":6,"speaker":"","original":"Je fais volte-face.","ipa":"/ʒˈə- fˈɛ vˈɔltfˈas/","zh":"我来了个急转身。","en":"I do an about-face.","note":"推定修订"},{"id":"la-dame-aux-camelias-18-007","lineIndex":7,"sourceLineIndex":7,"speaker":"","original":"Ton père me l'a dit.","ipa":"/tˈɔ̃ pˈɛʁ mˈə- lˈa- dˈi/","zh":"你父亲这样告诉了我。","en":"Your father told me so.","note":"推定修订"},{"id":"la-dame-aux-camelias-18-008","lineIndex":8,"sourceLineIndex":8,"speaker":"","original":"Toi et moi, c'est fini.","ipa":"/twˈa ˈe mwˈa sˈɛ finˈi/","zh":"你和我，已经结束了。","en":"You and I are over.","note":"推定修订"},{"id":"la-dame-aux-camelias-18-009","lineIndex":9,"sourceLineIndex":9,"speaker":"","original":"Je t'aime et je pars.","ipa":"/ʒˈə- tˈɛm ˈe ʒˈə- pˈaʁ/","zh":"我爱你，但我就要离开。","en":"I love you, and I'm leaving.","note":"推定修订"},{"id":"la-dame-aux-camelias-18-010","lineIndex":10,"sourceLineIndex":10,"speaker":"","original":"Pour l'amour de toi.","ipa":"/pˈuʁ lamˈuʁ dˈə- twˈa/","zh":"为了爱你。","en":"For love of you.","note":"推定修订"},{"id":"la-dame-aux-camelias-18-011","lineIndex":11,"sourceLineIndex":11,"speaker":"","original":"Pour toutes tes victoires.","ipa":"/pˈuʁ tˈut tˈe- viktwˈaʁ/","zh":"为了你所有的胜利。","en":"For all your victories.","note":"推定修订"},{"id":"la-dame-aux-camelias-18-012","lineIndex":12,"sourceLineIndex":12,"speaker":"","original":"J'enterre notre histoire.","ipa":"/ʒɑ̃tˈɛʁ nˈotʁ istwˈaʁ/","zh":"我埋葬我们的故事。","en":"I bury our story.","note":"推定修订"},{"id":"la-dame-aux-camelias-18-013","lineIndex":13,"sourceLineIndex":13,"speaker":"","original":"Pour toi, mon aimé.","ipa":"/pˈuʁ twˈa mˈɔ̃ ɛmˈe/","zh":"为了你，我的爱人。","en":"For you, my beloved.","note":"推定修订"},{"id":"la-dame-aux-camelias-18-014","lineIndex":14,"sourceLineIndex":14,"speaker":"","original":"Je dois m'en aller.","ipa":"/ʒˈə- dwˈa mˈɑ̃ alˈe/","zh":"我必须离开。","en":"I have to go.","note":"推定修订"},{"id":"la-dame-aux-camelias-18-015","lineIndex":15,"sourceLineIndex":15,"speaker":"","original":"Mais te dire adieu,","ipa":"/mˈɛ tˈə- dˈiʁ adjˈø/","zh":"但要向你道别，","en":"But to say goodbye to you,","note":"推定修订"},{"id":"la-dame-aux-camelias-18-016","lineIndex":16,"sourceLineIndex":16,"speaker":"","original":"Je ne sais si je peux.","ipa":"/ʒˈə- nˈə- sˈɛ sˈi ʒˈə- pˈø/","zh":"我不知道自己能不能做到。","en":"I don't know if I can.","note":"推定修订"},{"id":"la-dame-aux-camelias-18-017","lineIndex":17,"sourceLineIndex":17,"speaker":"","original":"Mes rêves se brisent.","ipa":"/mˈe- ʁˈɛv sˈə- bʁˈiz/","zh":"我的梦想正在破碎。","en":"My dreams are breaking apart.","note":"推定修订"},{"id":"la-dame-aux-camelias-18-018","lineIndex":18,"sourceLineIndex":18,"speaker":"","original":"Face à ce sacrifice.","ipa":"/fˈas ˈa sˈə- sakʁifˈis/","zh":"面对这份牺牲。","en":"In the face of this sacrifice.","note":"推定修订"},{"id":"la-dame-aux-camelias-18-019","lineIndex":19,"sourceLineIndex":19,"speaker":"","original":"Chaque pas qui m’éloigne de toi est comme un supplice.","ipa":"/ʃˈak pˈa kˈi melwˈaɲ dˈə- twˈa ˈɛ kˈɔm ˈœ̃ syplˈis/","zh":"每一步离你更远，都如同一种折磨。","en":"Every step that takes me away from you is like a torment.","note":"推定修订"},{"id":"la-dame-aux-camelias-18-021","lineIndex":20,"sourceLineIndex":20,"speaker":"","original":"Les ombres déjà","ipa":"/lˈe- ˈɔ̃bʁ deʒˈa/","zh":"阴影已经","en":"The shadows already","note":"推定修订"},{"id":"la-dame-aux-camelias-18-022","lineIndex":21,"sourceLineIndex":21,"speaker":"","original":"Planent sur ma joie.","ipa":"/plˈan sˈyʁ mˈa- ʒwˈa/","zh":"盘旋在我的欢欣之上。","en":"Hover over my joy.","note":"推定修订"},{"id":"la-dame-aux-camelias-18-023","lineIndex":22,"sourceLineIndex":22,"speaker":"","original":"Un jour, tu sauras","ipa":"/ˈœ̃ ʒˈuʁ tˈy soʁˈa/","zh":"有一天，你会明白","en":"One day, you'll know","note":"推定修订"},{"id":"la-dame-aux-camelias-18-024","lineIndex":23,"sourceLineIndex":23,"speaker":"","original":"Pourquoi je renonce à toi.","ipa":"/puʁkwˈa ʒˈə- ʁənˈɔ̃s ˈa twˈa/","zh":"我为何放弃你。","en":"Why I give you up.","note":"推定修订"},{"id":"la-dame-aux-camelias-18-025","lineIndex":24,"sourceLineIndex":24,"speaker":"","original":"Je t'aime et je pars.","ipa":"/ʒˈə- tˈɛm ˈe ʒˈə- pˈaʁ/","zh":"我爱你，但我就要离开。","en":"I love you, and I'm leaving.","note":"推定修订"},{"id":"la-dame-aux-camelias-18-026","lineIndex":25,"sourceLineIndex":25,"speaker":"","original":"Pour l'amour de toi.","ipa":"/pˈuʁ lamˈuʁ dˈə- twˈa/","zh":"为了爱你。","en":"For love of you.","note":"推定修订"},{"id":"la-dame-aux-camelias-18-027","lineIndex":26,"sourceLineIndex":26,"speaker":"","original":"Pour toutes tes victoires.","ipa":"/pˈuʁ tˈut tˈe- viktwˈaʁ/","zh":"为了你所有的胜利。","en":"For all your victories.","note":"推定修订"},{"id":"la-dame-aux-camelias-18-028","lineIndex":27,"sourceLineIndex":27,"speaker":"","original":"J'enterre notre histoire.","ipa":"/ʒɑ̃tˈɛʁ nˈotʁ istwˈaʁ/","zh":"我埋葬我们的故事。","en":"I bury our story.","note":"推定修订"},{"id":"la-dame-aux-camelias-18-029","lineIndex":28,"sourceLineIndex":28,"speaker":"","original":"Mes rêves se brisent","ipa":"/mˈe- ʁˈɛv sˈə- bʁˈiz/","zh":"我的梦想正在破碎","en":"My dreams are breaking apart","note":"推定修订"},{"id":"la-dame-aux-camelias-18-030","lineIndex":29,"sourceLineIndex":29,"speaker":"","original":"Face à ce sacrifice.","ipa":"/fˈas ˈa sˈə- sakʁifˈis/","zh":"面对这份牺牲。","en":"In the face of this sacrifice.","note":"推定修订"},{"id":"la-dame-aux-camelias-18-031","lineIndex":30,"sourceLineIndex":30,"speaker":"","original":"Chaque fois qu'il est loin de toi.","ipa":"/ʃˈak fwˈa kˈil ˈɛ lwˈɛ̃ dˈə- twˈa/","zh":"每当他远离你时。","en":"Each time he's far from you.","note":"推定修订"},{"id":"la-dame-aux-camelias-18-032","lineIndex":31,"sourceLineIndex":31,"speaker":"","original":"Et comme un supplice.","ipa":"/ˈe kˈɔm ˈœ̃ syplˈis/","zh":"又像一种折磨。","en":"And like a torment.","note":"推定修订"},{"id":"la-dame-aux-camelias-18-033","lineIndex":32,"sourceLineIndex":32,"speaker":"","original":"Dans une autre vie,","ipa":"/dˈɑ̃ ˈyn ˈotʁ vˈi/","zh":"在另一个人生里，","en":"In another life,","note":"推定修订"},{"id":"la-dame-aux-camelias-18-034","lineIndex":33,"sourceLineIndex":33,"speaker":"","original":"Dans une autre peau,","ipa":"/dˈɑ̃ ˈyn ˈotʁ pˈo/","zh":"换一个身份，","en":"In another skin,","note":"推定修订"},{"id":"la-dame-aux-camelias-18-035","lineIndex":34,"sourceLineIndex":34,"speaker":"","original":"On se reconnaîtra sans se dire un mot.","ipa":"/ˈɔ̃ sˈə- ʁəkɔnɛtʁˈa sˈɑ̃ sˈə- dˈiʁ ˈœ̃ mˈo/","zh":"我们会认出彼此，无须说出一个字。","en":"We'll recognize each other without saying a word.","note":"推定修订"}],"sourceOrder":18,"displayOrder":18},{"order":20,"id":"20-la-promesse","title":"La promesse","titleZh":"承诺","lines":[{"id":"la-dame-aux-camelias-20-001","lineIndex":1,"sourceLineIndex":1,"speaker":"","original":"C'est vous que je supplie d'épargner sa vie.","ipa":"/sˈɛ vˈu kˈə ʒˈə- syplˈi depaʁnjˈe sˈa- vˈi/","zh":"我恳求您饶他一命。","en":"It is you I beg to spare his life.","note":"推定修订"},{"id":"la-dame-aux-camelias-20-002","lineIndex":2,"sourceLineIndex":2,"speaker":"","original":"Je vous offre toutes mes nuits si vous ne le mettez pas au défi.","ipa":"/ʒˈə- vˈu ˈɔfʁ tˈut mˈe- nyˈi sˈi vˈu nˈə- lˈə- mɛtˈe pˈa ˈo defˈi/","zh":"只要您不向他发起挑战，我愿把每个夜晚都献给您。","en":"I offer you all my nights if you won't challenge him.","note":"推定修订"},{"id":"la-dame-aux-camelias-20-003","lineIndex":3,"sourceLineIndex":3,"speaker":"","original":"Les mots blessants ne valent pas le sang sur l'épée.","ipa":"/lˈe- mˈo blɛsˈɑ̃ nˈə- vˈal pˈa lˈə- sˈɑ̃ sˈyʁ lepˈe/","zh":"伤人的话不值得以剑上的鲜血为代价。","en":"Hurtful words aren't worth blood on the sword.","note":"推定修订"},{"id":"la-dame-aux-camelias-20-004","lineIndex":4,"sourceLineIndex":4,"speaker":"","original":"Songez à les oublier si je me glisse… pieds.","ipa":"/sɔ̃ʒˈe ˈa lˈe- ubliˈe sˈi ʒˈə- mˈə- ɡlˈis pjˈe/","zh":"不如忘了那些话，若我……匍匐到您脚边。","en":"Consider forgetting them if I slip… at your feet.","note":"推定修订"},{"id":"la-dame-aux-camelias-20-005","lineIndex":5,"sourceLineIndex":5,"speaker":"","original":"Je vous en fais la promesse.","ipa":"/ʒˈə- vˈu ˈɑ̃ fˈɛ lˈa- pʁomˈɛs/","zh":"我向您保证。","en":"I promise you this.","note":"推定修订"},{"id":"la-dame-aux-camelias-20-006","lineIndex":6,"sourceLineIndex":6,"speaker":"","original":"Ajoutez-moi vos richesses.","ipa":"/aʒutˈemwˈa vˈo ʁiʃˈɛs/","zh":"再把您的财富也给我。","en":"Add your riches to my share.","note":"推定修订"},{"id":"la-dame-aux-camelias-20-007","lineIndex":7,"sourceLineIndex":7,"speaker":"","original":"Qu'enfin, à présent, je sois votre merveille.","ipa":"/kɑ̃fˈɛ̃ ˈa pʁezˈɑ̃ ʒˈə- swˈa vˈotʁ mɛʁvˈɛj/","zh":"好让我终于在此刻成为您的珍宝。","en":"So that at last, now, I may be your wonder.","note":"推定修订"},{"id":"la-dame-aux-camelias-20-008","lineIndex":8,"sourceLineIndex":8,"speaker":"","original":"C’est en votre pouvoir qu’une lueur scintille.","ipa":"/sˈɛ ˈɑ̃ vˈotʁ puvwˈaʁ kˈyn lyˈœʁ sɛ̃tˈij/","zh":"能否让一线微光闪烁，全在于你。","en":"It is within your power to make a glimmer shine.","note":"推定修订"},{"id":"la-dame-aux-camelias-20-009","lineIndex":9,"sourceLineIndex":9,"speaker":"","original":"Qu'au son de votre pardon, l'espoir ne vacille.","ipa":"/kˈo sˈɔ̃ dˈə- vˈotʁ paʁdˈɔ̃ lɛspwˈaʁ nˈə- vasˈij/","zh":"愿希望不会在听见您的宽恕时动摇。","en":"May hope not falter at the sound of your forgiveness.","note":"推定修订"},{"id":"la-dame-aux-camelias-20-010","lineIndex":10,"sourceLineIndex":10,"speaker":"","original":"Ne faites pas couler ce sang si sacré.","ipa":"/nˈə- fˈɛt pˈa kulˈe sˈə- sˈɑ̃ sˈi sakʁˈe/","zh":"请不要让这神圣的鲜血流淌。","en":"Do not spill this sacred blood.","note":"推定修订"},{"id":"la-dame-aux-camelias-20-011","lineIndex":11,"sourceLineIndex":11,"speaker":"","original":"À l’idée, mon âme se glace.","ipa":"/ˈa lidˈe mˈɔ̃ ˈaːm sˈə- ɡlˈas/","zh":"一想到这里，我的灵魂便不寒而栗。","en":"At the thought, my soul turns cold.","note":"推定修订"},{"id":"la-dame-aux-camelias-20-012","lineIndex":12,"sourceLineIndex":12,"speaker":"","original":"Laissez tomber cette sombre menace. La colère n'est jamais la meilleure conseillère.","ipa":"/lɛsˈe tɔ̃bˈe sˈɛt sˈɔ̃bʁ mənˈas lˈa- kolˈɛʁ nˈɛ ʒamˈɛ lˈa- mɛjˈœʁ kɔ̃sɛjˈɛʁ/","zh":"放下这可怕的威胁吧。愤怒从来都不是最好的谋士。","en":"Let go of this dark threat. Anger is never the best adviser.","note":"推定修订"},{"id":"la-dame-aux-camelias-20-013","lineIndex":13,"sourceLineIndex":13,"speaker":"","original":"Là, devant votre cou, je me mets à genoux.","ipa":"/lˈa dəvˈɑ̃ vˈotʁ kˈu ʒˈə- mˈə- mˈɛ ˈa ʒənˈu/","zh":"此刻，在您的颈前，我跪了下来。","en":"There, before your neck, I fall to my knees.","note":"推定修订"},{"id":"la-dame-aux-camelias-20-014","lineIndex":14,"sourceLineIndex":14,"speaker":"","original":"Je vous ouvre mon lit, s'il n'est plus votre ennemi.","ipa":"/ʒˈə- vˈu ˈuvʁ mˈɔ̃ lˈi sˈil nˈɛ plˈy vˈotʁ ɛnmˈi/","zh":"若它不再是您的敌人，我愿向您敞开我的床榻。","en":"I offer you my bed, if it is no longer your enemy.","note":"推定修订"},{"id":"la-dame-aux-camelias-20-015","lineIndex":15,"sourceLineIndex":15,"speaker":"","original":"Je vous en fais la promesse.","ipa":"/ʒˈə- vˈu ˈɑ̃ fˈɛ lˈa- pʁomˈɛs/","zh":"我向您保证。","en":"I promise you this.","note":"推定修订"},{"id":"la-dame-aux-camelias-20-016","lineIndex":16,"sourceLineIndex":16,"speaker":"","original":"Ajoutez-moi vos richesses.","ipa":"/aʒutˈemwˈa vˈo ʁiʃˈɛs/","zh":"再把您的财富也给我。","en":"Add your riches to my share.","note":"推定修订"},{"id":"la-dame-aux-camelias-20-017","lineIndex":17,"sourceLineIndex":17,"speaker":"","original":"Qu'enfin, à présent, je sois votre merveille.","ipa":"/kɑ̃fˈɛ̃ ˈa pʁezˈɑ̃ ʒˈə- swˈa vˈotʁ mɛʁvˈɛj/","zh":"好让我终于在此刻成为您的珍宝。","en":"So that at last, now, I may be your wonder.","note":"推定修订"},{"id":"la-dame-aux-camelias-20-018","lineIndex":18,"sourceLineIndex":18,"speaker":"","original":"C’est en votre pouvoir qu’une lueur scintille, qu’au son de votre pardon l’espoir ne vacille.","ipa":"/sˈɛ ˈɑ̃ vˈotʁ puvwˈaʁ kˈyn lyˈœʁ sɛ̃tˈij kˈo sˈɔ̃ dˈə- vˈotʁ paʁdˈɔ̃ lɛspwˈaʁ nˈə- vasˈij/","zh":"能否让一线微光闪烁，全在于你；愿听到你的宽恕时，希望不再动摇。","en":"It is within your power to make a glimmer shine, so that at the sound of your forgiveness, hope may not waver.","note":"推定修订"},{"id":"la-dame-aux-camelias-20-019","lineIndex":19,"sourceLineIndex":19,"speaker":"","original":"La suffisance, quand on y écoute, est un poison violent.","ipa":"/lˈa- syfizˈɑ̃s kˈɑ̃ ˈɔ̃ iɡʁˈɛk ekˈut ˈɛ ˈœ̃ pwazˈɔ̃ vjolˈɑ̃/","zh":"自负一旦被倾听，便是一剂猛烈的毒药。","en":"Self-importance, when one listens to it, is a violent poison.","note":"推定修订"},{"id":"la-dame-aux-camelias-20-020","lineIndex":20,"sourceLineIndex":20,"speaker":"","original":"Le cœur s'affole, l'étouffe dans la furie.","ipa":"/lˈə- kˈœʁ safˈɔl letˈuf dˈɑ̃ lˈa- fyʁˈi/","zh":"心慌乱起来，愤怒将它扼住。","en":"The heart panics; fury chokes it.","note":"推定修订"},{"id":"la-dame-aux-camelias-20-021","lineIndex":21,"sourceLineIndex":21,"speaker":"","original":"Elle nous emportait.","ipa":"/ˈɛl nˈu ɑ̃pɔʁtˈɛ/","zh":"她曾带着我们远去。","en":"She was carrying us away.","note":"推定修订"},{"id":"la-dame-aux-camelias-20-022","lineIndex":22,"sourceLineIndex":22,"speaker":"","original":"C'est en votre pouvoir qu'une lueur scintille, qu'au son de votre pardon l'espoir ne meurt.","ipa":"/sˈɛ ˈɑ̃ vˈotʁ puvwˈaʁ kˈyn lyˈœʁ sɛ̃tˈij kˈo sˈɔ̃ dˈə- vˈotʁ paʁdˈɔ̃ lɛspwˈaʁ nˈə- mˈœʁ/","zh":"一束微光能否闪耀，听到您的宽恕希望能否不灭，都在您的掌握之中。","en":"It is in your power that a glimmer shines, that at the sound of your pardon hope does not die.","note":"推定修订"},{"id":"la-dame-aux-camelias-20-023","lineIndex":23,"sourceLineIndex":23,"speaker":"","original":"Je vous en fais la promesse.","ipa":"/ʒˈə- vˈu ˈɑ̃ fˈɛ lˈa- pʁomˈɛs/","zh":"我向您保证。","en":"I promise you this.","note":"推定修订"},{"id":"la-dame-aux-camelias-20-024","lineIndex":24,"sourceLineIndex":24,"speaker":"","original":"Ajoutez-moi vos richesses.","ipa":"/aʒutˈemwˈa vˈo ʁiʃˈɛs/","zh":"再把您的财富也给我。","en":"Add your riches to my share.","note":"推定修订"},{"id":"la-dame-aux-camelias-20-025","lineIndex":25,"sourceLineIndex":25,"speaker":"","original":"Qu’enfin, à présent, je sois votre merveille.","ipa":"/kɑ̃fˈɛ̃ ˈa pʁezˈɑ̃ ʒˈə- swˈa vˈotʁ mɛʁvˈɛj/","zh":"愿我此刻终于成为你的珍宝。","en":"May I at last, now, be your wonder.","note":"推定修订"},{"id":"la-dame-aux-camelias-20-026","lineIndex":26,"sourceLineIndex":26,"speaker":"","original":"C’est en votre pouvoir qu’une lueur scintille, qu’au son de votre pardon l’espoir ne vacille.","ipa":"/sˈɛ ˈɑ̃ vˈotʁ puvwˈaʁ kˈyn lyˈœʁ sɛ̃tˈij kˈo sˈɔ̃ dˈə- vˈotʁ paʁdˈɔ̃ lɛspwˈaʁ nˈə- vasˈij/","zh":"能否让一线微光闪烁，全在于你；愿听到你的宽恕时，希望不再动摇。","en":"It is within your power to make a glimmer shine, so that at the sound of your forgiveness, hope may not waver.","note":"推定修订"}],"sourceOrder":20,"displayOrder":20},{"order":21,"id":"21-pour-qu-elle-choisisse","title":"Pour qu’elle choisisse","titleZh":"让她选择","lines":[{"id":"la-dame-aux-camelias-21-001","lineIndex":1,"sourceLineIndex":1,"speaker":"Armand","original":"Nous voilà face à face","ipa":"/nˈu vwalˈa fˈas ˈa fˈas/","zh":"如今我们面对面","en":"Here we are, face to face","note":""},{"id":"la-dame-aux-camelias-21-002","lineIndex":2,"sourceLineIndex":2,"speaker":"Armand","original":"Une dame est dans la place.","ipa":"/ˈyn dˈam ˈɛ dˈɑ̃ lˈa- plˈas/","zh":"这里有位女士。","en":"There’s a lady here.","note":""},{"id":"la-dame-aux-camelias-21-003","lineIndex":3,"sourceLineIndex":3,"speaker":"Armand","original":"Ton regard de glace Ne te fera pas gagner ses grâces","ipa":"/tˈɔ̃ ʁəɡˈaʁ dˈə- ɡlˈas nˈə- tˈə- fəʁˈa pˈa ɡanjˈe sˈe- ɡʁˈaːs/","zh":"你冰冷的目光可赢不了她的青睐","en":"That icy gaze of yours Won’t win you her favor","note":""},{"id":"la-dame-aux-camelias-21-005","lineIndex":4,"sourceLineIndex":4,"speaker":"Le Baron","original":"Tu ne me fais pas peur","ipa":"/tˈy nˈə- mˈə- fˈɛ pˈa pˈœʁ/","zh":"你吓不倒我","en":"You don’t frighten me","note":""},{"id":"la-dame-aux-camelias-21-006","lineIndex":5,"sourceLineIndex":5,"speaker":"Le Baron","original":"Vas-y, frappe au cœur","ipa":"/vˈaziɡʁˈɛk fʁˈap ˈo kˈœʁ/","zh":"来吧，直击心口","en":"Go on, strike at the heart","note":""},{"id":"la-dame-aux-camelias-21-007","lineIndex":6,"sourceLineIndex":6,"speaker":"Le Baron","original":"Ce tango des rivaux Dansons-le pour elle puisqu’il le faut.","ipa":"/sˈə- tɑ̃ɡˈo dˈe- ʁivˈo dɑ̃sˈɔ̃lˈə- pˈuʁ ˈɛl pˈyiskil lˈə- fˈo/","zh":"这支情敌间的探戈既然非跳不可，就为她跳吧。","en":"This tango of rivals Let’s dance it for her, since we must.","note":""},{"id":"la-dame-aux-camelias-21-009","lineIndex":7,"sourceLineIndex":7,"speaker":"Le Baron et Armand","original":"C’est toi ou moi","ipa":"/sˈɛ twˈa ˈu mwˈa/","zh":"不是你，就是我","en":"It’s you or me","note":""},{"id":"la-dame-aux-camelias-21-010","lineIndex":8,"sourceLineIndex":8,"speaker":"Le Baron et Armand","original":"Qui de nous tiendra?","ipa":"/kˈi dˈə- nˈu tjɛ̃dʁˈa/","zh":"我们之中，谁能撑到最后？","en":"Which of us will hold out?","note":""},{"id":"la-dame-aux-camelias-21-011","lineIndex":9,"sourceLineIndex":9,"speaker":"Le Baron et Armand","original":"Une fois dans l’arène On est là pour qu’elle choisisse!","ipa":"/ˈyn fwˈa dˈɑ̃ laʁˈɛn ˈɔ̃ ˈɛ lˈa pˈuʁ kˈɛl ʃwazˈis/","zh":"一旦踏入角斗场我们站在这里，让她来选择！","en":"Once in the arena We’re here so she can choose!","note":""},{"id":"la-dame-aux-camelias-21-013","lineIndex":10,"sourceLineIndex":10,"speaker":"Le Baron","original":"Allez, viens, avance","ipa":"/alˈe vjˈɛ̃ avˈɑ̃s/","zh":"来啊，过来，再往前一步","en":"Come on, come closer, step forward","note":""},{"id":"la-dame-aux-camelias-21-014","lineIndex":11,"sourceLineIndex":11,"speaker":"Le Baron","original":"Je mènerai la cadence","ipa":"/ʒˈə- mɛnʁˈe lˈa- kadˈɑ̃s/","zh":"节奏由我掌握","en":"I’ll set the pace","note":""},{"id":"la-dame-aux-camelias-21-015","lineIndex":12,"sourceLineIndex":12,"speaker":"Le Baron","original":"Tu m’affrontes ici Pour une femme Qui t’a trahi.","ipa":"/tˈy mafʁˈɔ̃t isˈi pˈuʁ ˈyn fˈam kˈi tˈa- tʁaˈi/","zh":"你在这里与我对峙只为一个女人一个背叛了你的女人。","en":"You face me here For a woman Who betrayed you.","note":""},{"id":"la-dame-aux-camelias-21-018","lineIndex":13,"sourceLineIndex":13,"speaker":"Armand","original":"L’amour et la cendre À moi se font entendre","ipa":"/lamˈuʁ ˈe lˈa- sˈɑ̃dʁ ˈa mwˈa sˈə- fˈɔ̃ ɑ̃tˈɑ̃dʁ/","zh":"爱情与灰烬都在向我发声","en":"Love and ashes Make themselves heard to me","note":""},{"id":"la-dame-aux-camelias-21-020","lineIndex":14,"sourceLineIndex":14,"speaker":"Armand","original":"Mon cœur bat pour elle sans trêve Et me laisse sur les lèvres Un goût amer","ipa":"/mˈɔ̃ kˈœʁ bˈa pˈuʁ ˈɛl sˈɑ̃ tʁˈɛv ˈe mˈə- lˈɛs sˈyʁ lˈe- lˈɛvʁ ˈœ̃ ɡˈu amˈe/","zh":"我的心为她跳动，不曾停歇在我的唇上留下一丝苦涩","en":"My heart beats for her without rest And leaves upon my lips A bitter taste","note":""},{"id":"la-dame-aux-camelias-21-023","lineIndex":15,"sourceLineIndex":15,"speaker":"Le Baron et Armand","original":"C’est toi ou moi","ipa":"/sˈɛ twˈa ˈu mwˈa/","zh":"不是你，就是我","en":"It’s you or me","note":""},{"id":"la-dame-aux-camelias-21-024","lineIndex":16,"sourceLineIndex":16,"speaker":"Le Baron et Armand","original":"Qui de nous tiendra?","ipa":"/kˈi dˈə- nˈu tjɛ̃dʁˈa/","zh":"我们之中，谁能撑到最后？","en":"Which of us will hold out?","note":""},{"id":"la-dame-aux-camelias-21-025","lineIndex":17,"sourceLineIndex":17,"speaker":"Le Baron et Armand","original":"Une fois dans l’arène On est là pour qu’elle choisisse!","ipa":"/ˈyn fwˈa dˈɑ̃ laʁˈɛn ˈɔ̃ ˈɛ lˈa pˈuʁ kˈɛl ʃwazˈis/","zh":"一旦踏入角斗场我们站在这里，让她来选择！","en":"Once in the arena We’re here so she can choose!","note":""},{"id":"la-dame-aux-camelias-21-027","lineIndex":18,"sourceLineIndex":18,"speaker":"Le Baron et Armand","original":"C’est toi ou moi","ipa":"/sˈɛ twˈa ˈu mwˈa/","zh":"不是你，就是我","en":"It’s you or me","note":""},{"id":"la-dame-aux-camelias-21-028","lineIndex":19,"sourceLineIndex":19,"speaker":"Le Baron et Armand","original":"Qui de nous tiendra?","ipa":"/kˈi dˈə- nˈu tjɛ̃dʁˈa/","zh":"我们之中，谁能撑到最后？","en":"Which of us will hold out?","note":""},{"id":"la-dame-aux-camelias-21-029","lineIndex":20,"sourceLineIndex":20,"speaker":"Le Baron et Armand","original":"Une fois dans l’arène On est là pour qu’elle choisisse!","ipa":"/ˈyn fwˈa dˈɑ̃ laʁˈɛn ˈɔ̃ ˈɛ lˈa pˈuʁ kˈɛl ʃwazˈis/","zh":"一旦踏入角斗场我们站在这里，让她来选择！","en":"Once in the arena We’re here so she can choose!","note":""},{"id":"la-dame-aux-camelias-21-031","lineIndex":21,"sourceLineIndex":21,"speaker":"","original":"Fuir, fuir","ipa":"/fyˈiʁ fyˈiʁ/","zh":"逃走，逃走","en":"Flee, flee","note":""},{"id":"la-dame-aux-camelias-21-032","lineIndex":22,"sourceLineIndex":22,"speaker":"","original":"Ce serait me trahir","ipa":"/sˈə- səʁˈɛ mˈə- tʁaˈiʁ/","zh":"那便是背叛自己","en":"That would be to betray myself","note":""},{"id":"la-dame-aux-camelias-21-033","lineIndex":23,"sourceLineIndex":23,"speaker":"","original":"On est dans l’arène, elle dans les coulisses","ipa":"/ˈɔ̃ ˈɛ dˈɑ̃ laʁˈɛn ˈɛl dˈɑ̃ lˈe- kulˈis/","zh":"我们身在角斗场，她却在幕后","en":"We’re in the arena; she’s in the wings","note":""},{"id":"la-dame-aux-camelias-21-034","lineIndex":24,"sourceLineIndex":24,"speaker":"","original":"Spectatrice!","ipa":"/spɛktatʁˈis/","zh":"作壁上观！","en":"A spectator!","note":""}],"sourceOrder":21,"displayOrder":21},{"order":26,"id":"26-fleur-fanee","title":"Fleur fanée","titleZh":"凋零的花","lines":[{"id":"la-dame-aux-camelias-26-001","lineIndex":1,"sourceLineIndex":1,"speaker":"","original":"Le rideau tombe et le feu s’étend.","ipa":"/lˈə- ʁidˈo tˈɔ̃b ˈe lˈə- fˈø setˈɑ̃/","zh":"帷幕落下，火势蔓延。","en":"The curtain falls and the fire spreads.","note":"推定修订"},{"id":"la-dame-aux-camelias-26-002","lineIndex":2,"sourceLineIndex":2,"speaker":"","original":"Je sens le froid qui s’empare de mes mains.","ipa":"/ʒˈə- sˈɑ̃s lˈə- fʁwˈa kˈi sɑ̃pˈaʁ dˈə- mˈe- mˈɛ̃/","zh":"我感到寒意攫住了双手。","en":"I feel the cold taking hold of my hands.","note":"推定修订"},{"id":"la-dame-aux-camelias-26-003","lineIndex":3,"sourceLineIndex":3,"speaker":"","original":"Paris s’éveille au dehors dans le bruit.","ipa":"/paʁˈi sevˈɛj ˈo dəˈɔʁ dˈɑ̃ lˈə- bʁyˈi/","zh":"窗外喧闹声中，巴黎醒来。","en":"Paris awakens outside amid the noise.","note":"推定修订"},{"id":"la-dame-aux-camelias-26-004","lineIndex":4,"sourceLineIndex":4,"speaker":"","original":"Et moi, je glisse lentement dans la nuit.","ipa":"/ˈe mwˈa ʒˈə- ɡlˈis lɑ̃tmˈɑ̃ dˈɑ̃ lˈa- nyˈi/","zh":"而我缓缓滑入黑夜。","en":"And I slowly slip into the night.","note":"推定修订"},{"id":"la-dame-aux-camelias-26-005","lineIndex":5,"sourceLineIndex":5,"speaker":"","original":"Toute ma vie, tant de monde touché.","ipa":"/tˈut mˈa- vˈi tˈɑ̃ dˈə- mˈɔ̃d tuʃˈe/","zh":"这一生，已有那么多人触碰过我。","en":"All my life, I have felt the touch of so many people.","note":"推定修订"},{"id":"la-dame-aux-camelias-26-006","lineIndex":6,"sourceLineIndex":6,"speaker":"","original":"Tant de regards sur moi déshabillés.","ipa":"/tˈɑ̃ dˈə- ʁəɡˈaʁ sˈyʁ mwˈa dezabijˈe/","zh":"那么多目光将我看透。","en":"So many gazes undressed me.","note":"推定修订"},{"id":"la-dame-aux-camelias-26-007","lineIndex":7,"sourceLineIndex":7,"speaker":"","original":"Mais sous la soie, sous le fard et l’éclat.","ipa":"/mˈɛ sˈu lˈa- swˈa sˈu lˈə- fˈaʁ ˈe leklˈa/","zh":"可在丝绸、脂粉与光彩之下。","en":"But beneath the silk, the makeup and the glitter.","note":"推定修订"},{"id":"la-dame-aux-camelias-26-008","lineIndex":8,"sourceLineIndex":8,"speaker":"","original":"Il n’y avait que l’ombre de tes pas.","ipa":"/ˈil nˈi avˈɛ kˈə lˈɔ̃bʁ dˈə- tˈe- pˈa/","zh":"那里只有你脚步的影子。","en":"There was only the shadow of your footsteps.","note":"推定修订"},{"id":"la-dame-aux-camelias-26-009","lineIndex":9,"sourceLineIndex":9,"speaker":"","original":"Je suis la fleur fanée, la fleur oubliée.","ipa":"/ʒˈə- syˈi lˈa- flˈœʁ fanˈe lˈa- flˈœʁ ubliˈe/","zh":"我是一朵凋谢的花，一朵被遗忘的花。","en":"I am the withered flower, the forgotten flower.","note":"推定修订"},{"id":"la-dame-aux-camelias-26-010","lineIndex":10,"sourceLineIndex":10,"speaker":"","original":"Qui se défait, et pétale après un baiser.","ipa":"/kˈi sˈə- defˈɛ ˈe petˈal apʁˈɛ ˈœ̃ bɛzˈe/","zh":"它逐渐散落，一个吻之后，连花瓣也凋零。","en":"That comes apart, and petal after a kiss.","note":"推定修订"},{"id":"la-dame-aux-camelias-26-011","lineIndex":11,"sourceLineIndex":11,"speaker":"","original":"Regarde-moi mourir, regarde-moi partir.","ipa":"/ʁəɡˈaʁdmwˈa muʁˈiʁ ʁəɡˈaʁdmwˈa paʁtˈiʁ/","zh":"看着我死去，看着我离开。","en":"Watch me die, watch me leave.","note":"推定修订"},{"id":"la-dame-aux-camelias-26-012","lineIndex":12,"sourceLineIndex":12,"speaker":"","original":"Je n’ai plus rien à moi pour te retenir.","ipa":"/ʒˈə- nˈe plˈy ʁiˈɛ̃ ˈa mwˈa pˈuʁ tˈə- ʁətnˈiʁ/","zh":"我已一无所有，无法再留住你。","en":"I have nothing of my own left to keep you here.","note":"推定修订"},{"id":"la-dame-aux-camelias-26-013","lineIndex":13,"sourceLineIndex":13,"speaker":"","original":"Fleur fanée, fleur damnée.","ipa":"/flˈœʁ fanˈe flˈœʁ danˈe/","zh":"凋谢的花，被诅咒的花。","en":"Withered flower, cursed flower.","note":"推定修订"},{"id":"la-dame-aux-camelias-26-014","lineIndex":14,"sourceLineIndex":14,"speaker":"","original":"Au pied de ton amour, je me suis prosternée.","ipa":"/ˈo pjˈe dˈə- tˈɔ̃ amˈuʁ ʒˈə- mˈə- syˈi pʁɔstɛʁnˈe/","zh":"我曾匍匐在你爱情的脚下。","en":"At the feet of your love, I prostrated myself.","note":"推定修订"},{"id":"la-dame-aux-camelias-26-015","lineIndex":15,"sourceLineIndex":15,"speaker":"","original":"Fleur fanée, fleur condamnée.","ipa":"/flˈœʁ fanˈe flˈœʁ kɔ̃danˈe/","zh":"凋谢的花，注定毁灭的花。","en":"Withered flower, doomed flower.","note":"推定修订"},{"id":"la-dame-aux-camelias-26-016","lineIndex":16,"sourceLineIndex":16,"speaker":"","original":"Et mon dernier souffle, j’aurais voulu te le donner.","ipa":"/ˈe mˈɔ̃ dɛʁnjˈe sˈufl ʒoʁˈɛ vulˈy tˈə- lˈə- dɔnˈe/","zh":"而我曾多么希望，把最后一口气也献给你。","en":"And my last breath, I would have wanted to give it to you.","note":"推定修订"},{"id":"la-dame-aux-camelias-26-017","lineIndex":17,"sourceLineIndex":17,"speaker":"","original":"Le seul moment à moi, ton son de finie.","ipa":"/lˈə- sˈœl momˈɑ̃ ˈa mwˈa tˈɔ̃ sˈɔ̃ dˈə- finˈi/","zh":"只属于我的时刻，是你那 finie 的声音。","en":"The only moment of my own, your sound of finie.","note":"推定修订"},{"id":"la-dame-aux-camelias-26-018","lineIndex":18,"sourceLineIndex":18,"speaker":"","original":"C’est cet instant précis où je perds la vie.","ipa":"/sˈɛ sˈɛt ɛ̃stˈɑ̃ pʁesˈi ˈu ʒˈə- pˈɛʁ lˈa- vˈi/","zh":"正是那个瞬间，我失去了生命。","en":"It is that precise instant when I lose my life.","note":"推定修订"},{"id":"la-dame-aux-camelias-26-019","lineIndex":19,"sourceLineIndex":19,"speaker":"","original":"Tu m’as maudite en croyant me juger.","ipa":"/tˈy mˈa modˈit ˈɑ̃ kʁwajˈɑ̃ mˈə- ʒyʒˈe/","zh":"你以为自己在评判我，却诅咒了我。","en":"You cursed me, thinking you were judging me.","note":"推定修订"},{"id":"la-dame-aux-camelias-26-020","lineIndex":20,"sourceLineIndex":20,"speaker":"","original":"Mais c’est pour toi, Armand, que j’ai dû changer.","ipa":"/mˈɛ sˈɛ pˈuʁ twˈa aʁmˈɑ̃ kˈə ʒˈe dˈyː ʃɑ̃ʒˈe/","zh":"但阿尔芒，我是为了你才不得不改变。","en":"But it was for you, Armand, that I had to change.","note":"推定修订"},{"id":"la-dame-aux-camelias-26-021","lineIndex":21,"sourceLineIndex":21,"speaker":"","original":"La mort n’est pas perdue, la mort est un rendu.","ipa":"/lˈa- mˈɔʁ nˈɛ pˈa pɛʁdˈy lˈa- mˈɔʁ ˈɛ ˈœ̃ ʁɑ̃dˈy/","zh":"死亡并未失去；死亡是一种归还。","en":"Death is not lost; death is a return.","note":"推定修订"},{"id":"la-dame-aux-camelias-26-022","lineIndex":22,"sourceLineIndex":22,"speaker":"","original":"Je reprends ce vieux corps que tant d’autres ont eu.","ipa":"/ʒˈə- ʁəpʁˈɑ̃ sˈə- vjˈø kˈɔʁ kˈə tˈɑ̃ dˈotʁ ˈɔ̃ ˈy/","zh":"我取回这具曾被许多人拥有过的旧躯体。","en":"I take back this old body that so many others have had.","note":"推定修订"},{"id":"la-dame-aux-camelias-26-023","lineIndex":23,"sourceLineIndex":23,"speaker":"","original":"Ne pleure pas sur ma peau de velours.","ipa":"/nˈə- plˈœʁ pˈa sˈyʁ mˈa- pˈo dˈə- vəlˈuʁ/","zh":"别在我天鹅绒般的肌肤上落泪。","en":"Do not weep upon my velvet skin.","note":"推定修订"},{"id":"la-dame-aux-camelias-26-024","lineIndex":24,"sourceLineIndex":24,"speaker":"","original":"Je meurs de fièvre et de mon amour.","ipa":"/ʒˈə- mˈœʁ dˈə- fjˈɛvʁ ˈe dˈə- mˈɔ̃ amˈuʁ/","zh":"我因热病与爱情而濒临死亡。","en":"I am dying of fever and of my love.","note":"推定修订"},{"id":"la-dame-aux-camelias-26-025","lineIndex":25,"sourceLineIndex":25,"speaker":"","original":"Je suis la fleur fanée, la fleur oubliée.","ipa":"/ʒˈə- syˈi lˈa- flˈœʁ fanˈe lˈa- flˈœʁ ubliˈe/","zh":"我是一朵凋谢的花，一朵被遗忘的花。","en":"I am the withered flower, the forgotten flower.","note":"推定修订"},{"id":"la-dame-aux-camelias-26-026","lineIndex":26,"sourceLineIndex":26,"speaker":"","original":"Qui se défait, pétale après baiser.","ipa":"/kˈi sˈə- defˈɛ petˈal apʁˈɛ bɛzˈe/","zh":"它逐渐散落，一吻之后便凋零。","en":"That comes apart, petal after kiss.","note":"推定修订"},{"id":"la-dame-aux-camelias-26-027","lineIndex":27,"sourceLineIndex":27,"speaker":"","original":"Regarde-moi mourir, regarde-moi partir.","ipa":"/ʁəɡˈaʁdmwˈa muʁˈiʁ ʁəɡˈaʁdmwˈa paʁtˈiʁ/","zh":"看着我死去，看着我离开。","en":"Watch me die, watch me leave.","note":"推定修订"},{"id":"la-dame-aux-camelias-26-028","lineIndex":28,"sourceLineIndex":28,"speaker":"","original":"Je n’ai plus rien à moi pour te retenir.","ipa":"/ʒˈə- nˈe plˈy ʁiˈɛ̃ ˈa mwˈa pˈuʁ tˈə- ʁətnˈiʁ/","zh":"我已一无所有，无法再留住你。","en":"I have nothing of my own left to keep you here.","note":"推定修订"},{"id":"la-dame-aux-camelias-26-029","lineIndex":29,"sourceLineIndex":29,"speaker":"","original":"Fleur fanée, fleur damnée.","ipa":"/flˈœʁ fanˈe flˈœʁ danˈe/","zh":"凋谢的花，被诅咒的花。","en":"Withered flower, cursed flower.","note":"推定修订"},{"id":"la-dame-aux-camelias-26-030","lineIndex":30,"sourceLineIndex":30,"speaker":"","original":"Au pied de ton amour, je me suis prosternée.","ipa":"/ˈo pjˈe dˈə- tˈɔ̃ amˈuʁ ʒˈə- mˈə- syˈi pʁɔstɛʁnˈe/","zh":"我曾匍匐在你爱情的脚下。","en":"At the feet of your love, I prostrated myself.","note":"推定修订"},{"id":"la-dame-aux-camelias-26-031","lineIndex":31,"sourceLineIndex":31,"speaker":"","original":"Fleur fanée, fleur condamnée.","ipa":"/flˈœʁ fanˈe flˈœʁ kɔ̃danˈe/","zh":"凋谢的花，注定毁灭的花。","en":"Withered flower, doomed flower.","note":"推定修订"},{"id":"la-dame-aux-camelias-26-032","lineIndex":32,"sourceLineIndex":32,"speaker":"","original":"Et mon dernier souffle, j’aurais voulu te le donner.","ipa":"/ˈe mˈɔ̃ dɛʁnjˈe sˈufl ʒoʁˈɛ vulˈy tˈə- lˈə- dɔnˈe/","zh":"而我曾多么希望，把最后一口气也献给你。","en":"And my last breath, I would have wanted to give it to you.","note":"推定修订"},{"id":"la-dame-aux-camelias-26-033","lineIndex":33,"sourceLineIndex":33,"speaker":"","original":"Mon camélia blanc devient tout rouge.","ipa":"/mˈɔ̃ kameljˈa blˈɑ̃ dəvjˈɛ̃ tˈu ʁˈuʒ/","zh":"我的白茶花变得通红。","en":"My white camellia turns completely red.","note":"推定修订"},{"id":"la-dame-aux-camelias-26-034","lineIndex":34,"sourceLineIndex":34,"speaker":"","original":"Le monde s’arrête, plus rien ne bouge.","ipa":"/lˈə- mˈɔ̃d saʁˈɛt plˈy ʁiˈɛ̃ nˈə- bˈuʒ/","zh":"世界停了下来，一切都不再移动。","en":"The world stops; nothing moves anymore.","note":"推定修订"},{"id":"la-dame-aux-camelias-26-035","lineIndex":35,"sourceLineIndex":35,"speaker":"","original":"Pardonne-moi, Armand, pardonne-moi, Této.","ipa":"/paʁdˈɔnmwˈa aʁmˈɑ̃ paʁdˈɔnmwˈa tetˈo/","zh":"原谅我，阿尔芒；原谅我，Této。","en":"Forgive me, Armand; forgive me, Této.","note":"推定修订"},{"id":"la-dame-aux-camelias-26-036","lineIndex":36,"sourceLineIndex":36,"speaker":"","original":"Si petite, si seule.","ipa":"/sˈi pətˈit sˈi sˈœl/","zh":"如此渺小，如此孤单。","en":"So small, so alone.","note":"推定修订"},{"id":"la-dame-aux-camelias-26-037","lineIndex":37,"sourceLineIndex":37,"speaker":"","original":"Fleurs fanées, fleurs oubliées.","ipa":"/flˈœʁ fanˈe flˈœʁ ubliˈe/","zh":"凋谢的花，被遗忘的花。","en":"Withered flowers, forgotten flowers.","note":"推定修订"},{"id":"la-dame-aux-camelias-26-038","lineIndex":38,"sourceLineIndex":38,"speaker":"","original":"On s’est tant aimées, on s’est tant aisées.","ipa":"/ˈɔ̃ sˈɛ tˈɑ̃ ɛmˈe ˈɔ̃ sˈɛ tˈɑ̃ ɛzˈe/","zh":"我们曾如此相爱，也曾如此相助。","en":"We loved each other so much; we aided each other so much.","note":"推定修订"},{"id":"la-dame-aux-camelias-26-039","lineIndex":39,"sourceLineIndex":39,"speaker":"","original":"Je te regarde fuir, je te regarde partir.","ipa":"/ʒˈə- tˈə- ʁəɡˈaʁd fyˈiʁ ʒˈə- tˈə- ʁəɡˈaʁd paʁtˈiʁ/","zh":"我看着你逃走，看着你离开。","en":"I watch you flee, I watch you leave.","note":"推定修订"},{"id":"la-dame-aux-camelias-26-040","lineIndex":40,"sourceLineIndex":40,"speaker":"","original":"Je n’ai plus que mon âme pour te souvenir.","ipa":"/ʒˈə- nˈe plˈy kˈə mˈɔ̃ ˈaːm pˈuʁ tˈə- suvnˈiʁ/","zh":"我只剩灵魂可以用来怀念你。","en":"All I have left is my soul to remember you.","note":"推定修订"},{"id":"la-dame-aux-camelias-26-041","lineIndex":41,"sourceLineIndex":41,"speaker":"","original":"Fleur fanée.","ipa":"/flˈœʁ fanˈe/","zh":"凋谢的花。","en":"Withered flower.","note":"推定修订"},{"id":"la-dame-aux-camelias-26-042","lineIndex":42,"sourceLineIndex":42,"speaker":"","original":"Fleur fanée.","ipa":"/flˈœʁ fanˈe/","zh":"凋谢的花。","en":"Withered flower.","note":"推定修订"}],"sourceOrder":26,"displayOrder":26}];
